String normalizeBusinessAccountStatus(String? value) {
  final clean = (value ?? '').trim().toLowerCase();
  switch (clean) {
    case 'approved':
    case 'rejected':
    case 'suspended':
    case 'pending':
      return clean;
    default:
      return 'pending';
  }
}

String businessAccountStatusLabel(String? value) {
  switch (normalizeBusinessAccountStatus(value)) {
    case 'approved':
      return 'Approved';
    case 'rejected':
      return 'Needs Attention';
    case 'suspended':
      return 'Suspended';
    default:
      return 'Pending Review';
  }
}

Color businessAccountStatusColor(String? value) {
  switch (normalizeBusinessAccountStatus(value)) {
    case 'approved':
      return FarmColors.success;
    case 'rejected':
      return FarmColors.warning;
    case 'suspended':
      return FarmColors.danger;
    default:
      return FarmColors.primary;
  }
}
