class _AccountOptionsSnapshot {
  final MarketplaceProgramSettings settings;
  final BusinessAccount? businessAccount;
  final FarmerProfile? farmerProfile;

  const _AccountOptionsSnapshot({
    required this.settings,
    required this.businessAccount,
    required this.farmerProfile,
  });
}

Future<_AccountOptionsSnapshot> fetchAccountOptionsSnapshot() async {
  final values = await Future.wait<dynamic>([
    fetchMarketplaceProgramSettings(),
    fetchCurrentBusinessAccount(),
    fetchCurrentFarmerProfile(),
  ]);

  return _AccountOptionsSnapshot(
    settings: values[0] as MarketplaceProgramSettings,
    businessAccount: values[1] as BusinessAccount?,
    farmerProfile: values[2] as FarmerProfile?,
  );
}

class AccountOptionsScreen extends StatefulWidget {
  const AccountOptionsScreen({super.key});

  @override
  State<AccountOptionsScreen> createState() => _AccountOptionsScreenState();
}

class _AccountOptionsScreenState extends State<AccountOptionsScreen> {
  late Future<_AccountOptionsSnapshot> _future;

  @override
  void initState() {
    super.initState();
    _future = fetchAccountOptionsSnapshot();
  }

  Future<void> _reload() async {
    final next = fetchAccountOptionsSnapshot();
    setState(() {
      _future = next;
    });
    await next;
  }

  void _open(Widget screen) {
    Navigator.of(context)
        .push(MaterialPageRoute<void>(builder: (_) => screen))
        .then((_) => _reload());
  }

  @override
  Widget build(BuildContext context) {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      return const GuestProtectedScreen(
        title: 'Account Options',
        subtitle: 'Business and farmer access',
        message: 'Sign in to apply for additional account access.',
      );
    }

    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(title: const Text('Account Options')),
      body: FutureBuilder<_AccountOptionsSnapshot>(
        future: _future,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting &&
              snapshot.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          final data = snapshot.data;
          if (data == null) {
            return FarmPage(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 120),
                children: [
                  _MarketplaceProgramNotice(
                    icon: Icons.error_outline,
                    title: 'Could not load account options',
                    message: 'Please check your connection and try again.',
                    actionLabel: 'Try Again',
                    onAction: _reload,
                  ),
                ],
              ),
            );
          }

          final business = data.businessAccount;
          final farmer = data.farmerProfile;
          final settings = data.settings;

          final businessStatus = business == null
              ? settings.wholesaleApplicationsEnabled
                  ? 'Applications open'
                  : 'Applications paused'
              : businessAccountStatusLabel(business.status);

          final farmerStatus = farmer == null
              ? settings.farmerApplicationsEnabled
                  ? 'Applications open'
                  : 'Applications paused'
              : farmer.statusLabel;

          return FarmPage(
            child: RefreshIndicator(
              onRefresh: _reload,
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 120),
                children: [
                  Container(
                    padding: const EdgeInsets.all(20),
                    decoration: BoxDecoration(
                      gradient: const LinearGradient(
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                        colors: [FarmColors.deepGreen, FarmColors.green],
                      ),
                      borderRadius: BorderRadius.circular(28),
                    ),
                    child: const Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Icon(
                          Icons.manage_accounts_outlined,
                          color: Colors.white,
                          size: 34,
                        ),
                        SizedBox(height: 14),
                        Text(
                          'One login. More ways to participate.',
                          style: TextStyle(
                            color: Colors.white,
                            fontSize: 24,
                            fontWeight: FontWeight.w900,
                            height: 1.12,
                          ),
                        ),
                        SizedBox(height: 8),
                        Text(
                          'Your regular customer shopping, orders, favourites, and rewards remain available after you apply.',
                          style: TextStyle(
                            color: Colors.white70,
                            height: 1.4,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 16),
                  _AccountProgramCard(
                    icon: Icons.storefront_outlined,
                    title: 'Business / Wholesale Shopper',
                    subtitle: business == null
                        ? 'Apply for reviewed bulk pricing and wholesale ordering.'
                        : 'Open your wholesale application or approved workspace.',
                    status: businessStatus,
                    enabled: business != null ||
                        settings.wholesaleApplicationsEnabled,
                    onTap: () => _open(const BusinessWholesaleHubScreen()),
                  ),
                  const SizedBox(height: 12),
                  _AccountProgramCard(
                    icon: Icons.agriculture_outlined,
                    title: 'Farmer Partner',
                    subtitle: farmer == null
                        ? 'Submit your farm details for review and approval.'
                        : 'Open your farmer application or partner workspace.',
                    status: farmerStatus,
                    enabled:
                        farmer != null || settings.farmerApplicationsEnabled,
                    onTap: () => _open(const FarmerAccessGate()),
                  ),
                  const SizedBox(height: 14),
                  FarmCard(
                    padding: const EdgeInsets.all(16),
                    child: const Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Icon(Icons.info_outline, color: FarmColors.primary),
                        SizedBox(width: 10),
                        Expanded(
                          child: Text(
                            'Applications are reviewed before extra access is granted. You do not need another email address or a second account.',
                            style: TextStyle(
                              color: FarmColors.mutedText,
                              height: 1.4,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}

