class BusinessAccount {
  final String id;
  final String userId;
  final String email;
  final String businessName;
  final String businessType;
  final String contactName;
  final String phone;
  final String whatsapp;
  final String address;
  final String parish;
  final String registrationNumber;
  final double expectedWeeklySpend;
  final List<String> preferredDeliveryDays;
  final String status;
  final String adminNotes;

  // Phase 3P — wholesale credit control
  final bool wholesaleCreditEnabled;
  final double wholesaleCreditLimit;
  final int wholesalePaymentTermsDays;
  final String wholesaleCreditStatus;
  final String wholesaleCreditNote;
  final DateTime? wholesaleCreditUpdatedAt;
  final String? wholesaleCreditUpdatedBy;

  final DateTime? approvedAt;
  final String? approvedBy;
  final DateTime? createdAt;
  final DateTime? updatedAt;

  const BusinessAccount({
    required this.id,
    required this.userId,
    required this.email,
    required this.businessName,
    required this.businessType,
    required this.contactName,
    required this.phone,
    required this.whatsapp,
    required this.address,
    required this.parish,
    required this.registrationNumber,
    required this.expectedWeeklySpend,
    required this.preferredDeliveryDays,
    required this.status,
    required this.adminNotes,
    this.wholesaleCreditEnabled = false,
    this.wholesaleCreditLimit = 0,
    this.wholesalePaymentTermsDays = 0,
    this.wholesaleCreditStatus = 'cash_only',
    this.wholesaleCreditNote = '',
    this.wholesaleCreditUpdatedAt,
    this.wholesaleCreditUpdatedBy,
    this.approvedAt,
    this.approvedBy,
    this.createdAt,
    this.updatedAt,
  });

  factory BusinessAccount.fromSupabase(Map<String, dynamic> data) {
    final rawDays = data['preferred_delivery_days'];
    final days = rawDays is Iterable
        ? rawDays
            .map((item) => item.toString().trim())
            .where((item) => item.isNotEmpty)
            .toList()
        : const <String>[];

    return BusinessAccount(
      id: (data['id'] ?? '').toString(),
      userId: (data['user_id'] ?? '').toString(),
      email: (data['email'] ?? '').toString().trim().toLowerCase(),
      businessName: (data['business_name'] ?? '').toString().trim(),
      businessType: (data['business_type'] ?? 'Other').toString().trim(),
      contactName: (data['contact_name'] ?? '').toString().trim(),
      phone: (data['phone'] ?? '').toString().trim(),
      whatsapp: (data['whatsapp'] ?? '').toString().trim(),
      address: (data['address'] ?? '').toString().trim(),
      parish: (data['parish'] ?? '').toString().trim(),
      registrationNumber: (data['registration_number'] ?? '').toString().trim(),
      expectedWeeklySpend: Product._toDouble(data['expected_weekly_spend']),
      preferredDeliveryDays: days,
      status: normalizeBusinessAccountStatus(data['status']?.toString()),
      adminNotes: (data['admin_notes'] ?? '').toString().trim(),
      wholesaleCreditEnabled: data['wholesale_credit_enabled'] == true,
      wholesaleCreditLimit: Product._toDouble(data['wholesale_credit_limit']),
      wholesalePaymentTermsDays:
          (data['wholesale_payment_terms_days'] as num?)?.toInt() ??
              int.tryParse(
                data['wholesale_payment_terms_days']?.toString() ?? '',
              ) ??
              0,
      wholesaleCreditStatus: (data['wholesale_credit_status'] ?? 'cash_only')
          .toString()
          .trim()
          .toLowerCase(),
      wholesaleCreditNote:
          (data['wholesale_credit_note'] ?? '').toString().trim(),
      wholesaleCreditUpdatedAt:
          parseProductDate(data['wholesale_credit_updated_at']),
      wholesaleCreditUpdatedBy: data['wholesale_credit_updated_by']?.toString(),
      approvedAt: parseProductDate(data['approved_at']),
      approvedBy: data['approved_by']?.toString(),
      createdAt: parseProductDate(data['created_at']),
      updatedAt: parseProductDate(data['updated_at']),
    );
  }

  bool get isApproved => status == 'approved';
  bool get isPending => status == 'pending';
  bool get isRejected => status == 'rejected';
  bool get isSuspended => status == 'suspended';

  String get displayName =>
      businessName.isEmpty ? 'Business account' : businessName;

  bool get hasActiveWholesaleCredit =>
      wholesaleCreditEnabled && wholesaleCreditStatus == 'active';

  bool get isWholesaleCreditOnHold => wholesaleCreditStatus == 'hold';

  String get wholesaleCreditStatusLabel {
    if (!wholesaleCreditEnabled || wholesaleCreditStatus == 'cash_only') {
      return 'Cash / Due Now';
    }

    if (wholesaleCreditStatus == 'hold') {
      return 'Credit Hold';
    }

    return 'Credit Active';
  }

  String get wholesalePaymentTermsLabel => wholesalePaymentTermsDays <= 0
      ? 'Due on issue'
      : 'Net $wholesalePaymentTermsDays';
}

// =====================================================
// PHASE 3P — WHOLESALE ACCOUNT AGING
// =====================================================

class WholesaleAccountAging {
  final double current;
  final double days1To30;
  final double days31To60;
  final double days61Plus;

  const WholesaleAccountAging({
    required this.current,
    required this.days1To30,
    required this.days31To60,
    required this.days61Plus,
  });

  double get total => current + days1To30 + days31To60 + days61Plus;

  factory WholesaleAccountAging.fromInvoices(
    Iterable<WholesaleInvoice> invoices, {
    DateTime? asOf,
  }) {
    final now = (asOf ?? DateTime.now()).toLocal();
    final today = DateTime(now.year, now.month, now.day);

    double current = 0;
    double days1To30 = 0;
    double days31To60 = 0;
    double days61Plus = 0;

    for (final invoice in invoices) {
      if (!invoice.isIssued || invoice.isVoid || invoice.amountDue <= 0.005) {
        continue;
      }

      final due = invoice.dueDate?.toLocal();
      if (due == null) {
        current += invoice.amountDue;
        continue;
      }

      final dueDay = DateTime(due.year, due.month, due.day);
      final daysOverdue = today.difference(dueDay).inDays;

      if (daysOverdue <= 0) {
        current += invoice.amountDue;
      } else if (daysOverdue <= 30) {
        days1To30 += invoice.amountDue;
      } else if (daysOverdue <= 60) {
        days31To60 += invoice.amountDue;
      } else {
        days61Plus += invoice.amountDue;
      }
    }

    return WholesaleAccountAging(
      current: current,
      days1To30: days1To30,
      days31To60: days31To60,
      days61Plus: days61Plus,
    );
  }
}

