class WholesaleScheduleOption {
  final String windowId;
  final DateTime scheduledDate;
  final String dispatchMethod;
  final String label;
  final String startTime;
  final String endTime;
  final int maxRequests;
  final int bookedRequests;
  final int remainingCapacity;

  const WholesaleScheduleOption({
    required this.windowId,
    required this.scheduledDate,
    required this.dispatchMethod,
    required this.label,
    required this.startTime,
    required this.endTime,
    required this.maxRequests,
    required this.bookedRequests,
    required this.remainingCapacity,
  });

  factory WholesaleScheduleOption.fromSupabase(Map<String, dynamic> data) {
    int whole(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    final rawDate = data['scheduled_date']?.toString() ?? '';

    return WholesaleScheduleOption(
      windowId: (data['window_id'] ?? '').toString(),
      scheduledDate: DateTime.tryParse(rawDate) ?? DateTime.now(),
      dispatchMethod: (data['dispatch_method'] ?? 'hpj_delivery')
          .toString()
          .trim()
          .toLowerCase(),
      label: (data['window_label'] ?? 'Available window').toString().trim(),
      startTime: (data['start_time'] ?? '').toString().trim(),
      endTime: (data['end_time'] ?? '').toString().trim(),
      maxRequests: whole(data['max_requests']),
      bookedRequests: whole(data['booked_requests']),
      remainingCapacity: whole(data['remaining_capacity']),
    );
  }

  String get selectionKey => '${windowId}_${scheduledDate.toIso8601String()}';

  bool get isAvailable => remainingCapacity > 0;

  String get methodLabel => dispatchMethod == 'business_collection'
      ? 'Business Collection'
      : 'HPJ Delivery';

  String get dateLabel {
    const weekdays = <String>['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    final date = scheduledDate.toLocal();
    return '${weekdays[date.weekday - 1]}, ${date.day} ${months[date.month - 1]}';
  }

  String get displayLabel =>
      '$dateLabel • $label • $remainingCapacity slot${remainingCapacity == 1 ? '' : 's'} left';
}

