class WholesaleOrderJourney {
  final String requestId;
  final String requestStatus;
  final DateTime? requestCreatedAt;
  final DateTime? requestedDate;
  final String requestedDispatchMethod;
  final String requestedWindowLabel;
  final String fulfillmentStatus;
  final DateTime? preparationStartedAt;
  final DateTime? packingStartedAt;
  final DateTime? readyAt;
  final String invoiceNumber;
  final String invoiceStatus;
  final String paymentStatus;
  final double invoiceTotal;
  final double amountDue;
  final String dispatchStatus;
  final String dispatchMethod;
  final DateTime? scheduledFor;
  final DateTime? dispatchedAt;
  final DateTime? deliveredAt;
  final DateTime? collectedAt;

  const WholesaleOrderJourney({
    required this.requestId,
    required this.requestStatus,
    this.requestCreatedAt,
    this.requestedDate,
    required this.requestedDispatchMethod,
    required this.requestedWindowLabel,
    required this.fulfillmentStatus,
    this.preparationStartedAt,
    this.packingStartedAt,
    this.readyAt,
    required this.invoiceNumber,
    required this.invoiceStatus,
    required this.paymentStatus,
    required this.invoiceTotal,
    required this.amountDue,
    required this.dispatchStatus,
    required this.dispatchMethod,
    this.scheduledFor,
    this.dispatchedAt,
    this.deliveredAt,
    this.collectedAt,
  });

  factory WholesaleOrderJourney.fromSupabase(Map<String, dynamic> data) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    DateTime? date(dynamic value) =>
        value == null ? null : DateTime.tryParse(value.toString());

    return WholesaleOrderJourney(
      requestId: (data['request_id'] ?? '').toString(),
      requestStatus:
          (data['request_status'] ?? 'pending').toString().trim().toLowerCase(),
      requestCreatedAt: date(data['request_created_at']),
      requestedDate: date(data['requested_date']),
      requestedDispatchMethod:
          (data['requested_dispatch_method'] ?? 'hpj_delivery')
              .toString()
              .trim()
              .toLowerCase(),
      requestedWindowLabel:
          (data['requested_window_label'] ?? '').toString().trim(),
      fulfillmentStatus:
          (data['fulfillment_status'] ?? '').toString().trim().toLowerCase(),
      preparationStartedAt: date(data['preparation_started_at']),
      packingStartedAt: date(data['packing_started_at']),
      readyAt: date(data['ready_at']),
      invoiceNumber: (data['invoice_number'] ?? '').toString().trim(),
      invoiceStatus:
          (data['invoice_status'] ?? '').toString().trim().toLowerCase(),
      paymentStatus:
          (data['payment_status'] ?? '').toString().trim().toLowerCase(),
      invoiceTotal: number(data['invoice_total']),
      amountDue: number(data['amount_due']),
      dispatchStatus:
          (data['dispatch_status'] ?? '').toString().trim().toLowerCase(),
      dispatchMethod:
          (data['dispatch_method'] ?? '').toString().trim().toLowerCase(),
      scheduledFor: date(data['scheduled_for']),
      dispatchedAt: date(data['dispatched_at']),
      deliveredAt: date(data['delivered_at']),
      collectedAt: date(data['collected_at']),
    );
  }

  bool get isCollection =>
      (dispatchMethod.isNotEmpty ? dispatchMethod : requestedDispatchMethod) ==
      'business_collection';

  bool get isComplete =>
      dispatchStatus == 'delivered' || dispatchStatus == 'collected';

  int get currentStageIndex {
    if (requestStatus == 'cancelled' || requestStatus == 'rejected') return 0;
    if (isComplete) return 6;
    if (dispatchStatus == 'out_for_delivery' ||
        dispatchStatus == 'ready_for_pickup') {
      return 5;
    }
    if (dispatchStatus == 'planned' || dispatchStatus == 'assigned') return 4;
    if (fulfillmentStatus == 'ready_for_dispatch') return 4;
    if (fulfillmentStatus == 'packing') return 3;
    if (fulfillmentStatus == 'preparing') return 2;
    if (requestStatus == 'approved' || requestStatus == 'fulfilled') return 1;
    return 0;
  }

  String get currentStageLabel {
    if (requestStatus == 'cancelled') return 'Cancelled';
    if (requestStatus == 'rejected') return 'Needs Attention';
    if (dispatchStatus == 'delivered') return 'Delivered';
    if (dispatchStatus == 'collected') return 'Collected';
    if (dispatchStatus == 'out_for_delivery') return 'Out for Delivery';
    if (dispatchStatus == 'ready_for_pickup') return 'Ready for Collection';
    if (dispatchStatus == 'assigned' || dispatchStatus == 'planned') {
      return isCollection ? 'Collection Scheduled' : 'Delivery Scheduled';
    }
    if (fulfillmentStatus == 'ready_for_dispatch') return 'Ready for Dispatch';
    if (fulfillmentStatus == 'packing') return 'Packing';
    if (fulfillmentStatus == 'preparing') return 'Preparing';
    if (requestStatus == 'approved' || requestStatus == 'fulfilled')
      return 'Confirmed';
    if (requestStatus == 'quoted') return 'Quote Ready';
    return 'Submitted';
  }

  List<String> get stageLabels => <String>[
        'Submitted',
        'Confirmed',
        'Preparing',
        'Packing',
        isCollection ? 'Ready for Collection' : 'Ready for Dispatch',
        isCollection ? 'Collection Ready' : 'Out for Delivery',
        isCollection ? 'Collected' : 'Delivered',
      ];
}

