class WholesaleOrderingControl {
  final String businessAccountId;
  final String accountStatus;
  final bool creditEnabled;
  final String creditStatus;
  final double creditLimit;
  final int paymentTermsDays;
  final double outstandingInvoices;
  final double approvedCommitments;
  final double estimatedRequestTotal;
  final double exposureAfterRequest;
  final double availableCredit;
  final double availableAfterRequest;
  final double days1To30;
  final double days31To60;
  final double days61Plus;
  final int maxDaysOverdue;
  final String orderingStatus;
  final String reason;

  const WholesaleOrderingControl({
    required this.businessAccountId,
    required this.accountStatus,
    required this.creditEnabled,
    required this.creditStatus,
    required this.creditLimit,
    required this.paymentTermsDays,
    required this.outstandingInvoices,
    required this.approvedCommitments,
    required this.estimatedRequestTotal,
    required this.exposureAfterRequest,
    required this.availableCredit,
    required this.availableAfterRequest,
    required this.days1To30,
    required this.days31To60,
    required this.days61Plus,
    required this.maxDaysOverdue,
    required this.orderingStatus,
    required this.reason,
  });

  factory WholesaleOrderingControl.fromSupabase(
    Map<String, dynamic> data,
  ) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    int whole(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    return WholesaleOrderingControl(
      businessAccountId: (data['business_account_id'] ?? '').toString(),
      accountStatus:
          (data['account_status'] ?? '').toString().trim().toLowerCase(),
      creditEnabled: data['credit_enabled'] == true,
      creditStatus: (data['credit_status'] ?? 'cash_only')
          .toString()
          .trim()
          .toLowerCase(),
      creditLimit: number(data['credit_limit']),
      paymentTermsDays: whole(data['payment_terms_days']),
      outstandingInvoices: number(data['outstanding_invoices']),
      approvedCommitments: number(data['approved_commitments']),
      estimatedRequestTotal: number(data['estimated_request_total']),
      exposureAfterRequest: number(data['exposure_after_request']),
      availableCredit: number(data['available_credit']),
      availableAfterRequest: number(data['available_after_request']),
      days1To30: number(data['days_1_to_30']),
      days31To60: number(data['days_31_to_60']),
      days61Plus: number(data['days_61_plus']),
      maxDaysOverdue: whole(data['max_days_overdue']),
      orderingStatus: (data['ordering_status'] ?? 'allowed')
          .toString()
          .trim()
          .toLowerCase(),
      reason: (data['reason'] ?? '').toString().trim(),
    );
  }

  bool get isBlocked => orderingStatus == 'blocked';
  bool get hasWarning => orderingStatus == 'warning';
  bool get isAllowed => !isBlocked;

  bool get hasHardCreditLimit =>
      creditEnabled && creditStatus == 'active' && creditLimit > 0;

  String get statusLabel {
    if (isBlocked) return 'Ordering Blocked';
    if (hasWarning) return 'Account Review';
    return 'Ready to Order';
  }

  String get termsLabel =>
      paymentTermsDays <= 0 ? 'Due on issue' : 'Net $paymentTermsDays';
}

class _WholesaleOrderingControlCard extends StatelessWidget {
  final WholesaleOrderingControl control;
  final bool showRequestEstimate;
  final VoidCallback? onRefresh;

  const _WholesaleOrderingControlCard({
    required this.control,
    this.showRequestEstimate = false,
    this.onRefresh,
  });

  @override
  Widget build(BuildContext context) {
    final color = control.isBlocked
        ? FarmColors.danger
        : control.hasWarning
            ? FarmColors.warning
            : FarmColors.green;

    final icon = control.isBlocked
        ? Icons.block_outlined
        : control.hasWarning
            ? Icons.warning_amber_rounded
            : Icons.verified_outlined;

    Widget amountRow(String label, double value) {
      return Padding(
        padding: const EdgeInsets.only(top: 5),
        child: Row(
          children: [
            Expanded(
              child: Text(
                label,
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ),
            Text(
              formatJmd(value),
              style: const TextStyle(
                color: FarmColors.ink,
                fontSize: 10.5,
                fontWeight: FontWeight.w900,
              ),
            ),
          ],
        ),
      );
    }

    return FarmCard(
      padding: const EdgeInsets.all(15),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 40,
                height: 40,
                decoration: BoxDecoration(
                  color: color.withOpacity(.10),
                  borderRadius: BorderRadius.circular(13),
                ),
                child: Icon(icon, color: color),
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      control.statusLabel,
                      style: TextStyle(
                        color: color,
                        fontSize: 13,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      control.termsLabel,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
              if (onRefresh != null)
                IconButton(
                  tooltip: 'Refresh ordering status',
                  onPressed: onRefresh,
                  icon: const Icon(Icons.refresh_outlined, size: 19),
                ),
            ],
          ),
          const SizedBox(height: 10),
          Text(
            control.reason.isEmpty
                ? 'Your wholesale ordering status is available.'
                : control.reason,
            style: const TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10.5,
              height: 1.35,
              fontWeight: FontWeight.w700,
            ),
          ),
          if (control.outstandingInvoices > 0 ||
              control.approvedCommitments > 0 ||
              showRequestEstimate ||
              control.hasHardCreditLimit) ...[
            const SizedBox(height: 10),
            const Divider(height: 1),
            amountRow('Outstanding invoices', control.outstandingInvoices),
            if (control.approvedCommitments > 0)
              amountRow('Approved commitments', control.approvedCommitments),
            if (showRequestEstimate)
              amountRow('This request', control.estimatedRequestTotal),
            if (control.hasHardCreditLimit) ...[
              amountRow('Credit limit', control.creditLimit),
              amountRow(
                showRequestEstimate
                    ? 'Available after request'
                    : 'Available credit',
                showRequestEstimate
                    ? control.availableAfterRequest
                    : control.availableCredit,
              ),
            ],
          ],
          if (control.maxDaysOverdue > 0) ...[
            const SizedBox(height: 8),
            Text(
              'Oldest overdue balance: ${control.maxDaysOverdue} day${control.maxDaysOverdue == 1 ? '' : 's'}.',
              style: TextStyle(
                color: control.days61Plus > 0
                    ? FarmColors.danger
                    : FarmColors.warning,
                fontSize: 9.5,
                fontWeight: FontWeight.w900,
              ),
            ),
          ],
        ],
      ),
    );
  }
}

