          (data['frequency'] ?? 'one_time').toString().trim().toLowerCase(),
      certainty:
          (data['certainty'] ?? 'likely').toString().trim().toLowerCase(),
      status: (data['status'] ?? 'forecast').toString().trim().toLowerCase(),
      notes: (data['notes'] ?? '').toString().trim(),
      adminNotes: (data['admin_notes'] ?? '').toString().trim(),
      convertedRequestId: _nullableText(
        data['converted_request_id'],
      ),
      sourceType: (data['source_type'] ?? 'planning')
          .toString()
          .trim()
          .toLowerCase(),
      sourceRequestId: _nullableText(data['source_request_id']),
      sourceRequestItemId: _nullableText(data['source_request_item_id']),
      sourceReceivingBatchId:
          _nullableText(data['source_receiving_batch_id']),
      createdAt: parseProductDate(
        data['created_at'],
      ),
      updatedAt: parseProductDate(
        data['updated_at'],
      ),
    );
  }

  // ===================================================
  // STATUS HELPERS
  // ===================================================

  bool get isForecast => status == 'forecast';

  bool get isMatched => status == 'matched';

  bool get isReserved => status == 'reserved';

  bool get isConverted => status == 'converted';

  bool get isCancelled => status == 'cancelled';

  bool get isActive => !isConverted && !isCancelled;

  bool get isPlanningDemand => sourceType == 'planning';
  bool get isOrderDemand => sourceType == 'wholesale_order';
  bool get isReceivingShortfall => sourceType == 'receiving_shortfall';

  String get sourceLabel {
    if (isReceivingShortfall) return 'Receiving Shortfall';
    if (isOrderDemand) return 'Wholesale Order';
    return 'Planning Ahead';
  }

  // ===================================================
  // DISPLAY LABELS
  // ===================================================

  String get statusLabel {
    switch (status) {
      case 'matched':
        return 'Partially Secured';

      case 'reserved':
        return 'Supply Secured';

      case 'converted':
        return 'Procurement Confirmed';

      case 'cancelled':
        return 'Cancelled';

      default:
        return 'Needs Supply';
    }
  }

  String get frequencyLabel {
    switch (frequency) {
      case 'weekly':
        return 'Weekly';

      case 'biweekly':
        return 'Every 2 Weeks';

      case 'monthly':
        return 'Monthly';

      default:
        return 'One Time';
    }
  }

  String get certaintyLabel {
    switch (certainty) {
      case 'tentative':
        return 'Tentative';

      case 'expected':
        return 'Expected';

      default:
        return 'Likely';
    }
  }

  String get formattedQuantity {
    final value = quantity == quantity.roundToDouble()
        ? quantity.toInt().toString()
        : quantity.toStringAsFixed(1);

    return '$value $unit';
  }

  // ===================================================
  // PRIVATE HELPERS
  // ===================================================

  static String? _nullableText(
    dynamic value,
  ) {
    if (value == null) return null;

    final text = value.toString().trim();

    return text.isEmpty ? null : text;
  }
}

class WholesaleProduct {
  final Product product;
  final bool wholesaleEnabled;
  final double wholesalePrice;
  final int minimumQuantity;
  final String wholesaleUnit;

  const WholesaleProduct({
    required this.product,
    required this.wholesaleEnabled,
    required this.wholesalePrice,
    required this.minimumQuantity,
    required this.wholesaleUnit,
  });

  factory WholesaleProduct.fromSupabase(Map<String, dynamic> data) {
    final product = Product.fromSupabase(data);
    final cleanUnit =
        (data['wholesale_unit'] ?? product.unit ?? 'unit').toString().trim();

    return WholesaleProduct(
      product: product,
      wholesaleEnabled: data['wholesale_enabled'] == true,
      wholesalePrice: Product._toDouble(data['wholesale_price']),
      minimumQuantity: mathMaxInt(
        1,
        Product._toInt(data['wholesale_min_quantity'] ?? 1),
      ),
      wholesaleUnit: cleanUnit.isEmpty ? 'unit' : cleanUnit,
    );
  }

  bool get canOrder =>
      wholesaleEnabled &&
      wholesalePrice > 0 &&
      product.isCustomerVisible &&
      product.isAvailable;

  String get formattedWholesalePrice => formatJmd(wholesalePrice);

  double totalFor(int quantity) => wholesalePrice * quantity;
}
