  bool get isPreparing => status == 'preparing';

  bool get isPacked => status == 'packed';

  bool get isShort => status == 'short';

  bool get isRemoved => status == 'removed';

  bool get isAccountedFor => isPacked || isShort || isRemoved;

  String get statusLabel {
    switch (status) {
      case 'preparing':
        return 'Preparing';

      case 'packed':
        return 'Packed';

      case 'short':
        return 'Short';

      case 'removed':
        return 'Removed';

      default:
