    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text = value.toString().trim();

    if (text.isEmpty) {
      return null;
    }

    return DateTime.tryParse(
      text,
    );
  }
}

// =====================================================
// WHOLESALE FULFILMENT
// Warehouse preparation / packing header
// =====================================================

class WholesaleFulfillment {
  final String id;
  final String requestId;

  final String status;

  final String? assignedTo;

  final String preparationNotes;
  final String packingNotes;

  final DateTime? startedAt;
  final DateTime? packingStartedAt;
  final DateTime? readyAt;
  final DateTime? cancelledAt;

  final String? createdBy;

  final DateTime? createdAt;
  final DateTime? updatedAt;

  final List<WholesaleFulfillmentItem> items;

  const WholesaleFulfillment({
    required this.id,
    required this.requestId,
    required this.status,
    this.assignedTo,
    required this.preparationNotes,
    required this.packingNotes,
    this.startedAt,
    this.packingStartedAt,
    this.readyAt,
    this.cancelledAt,
    this.createdBy,
    this.createdAt,
    this.updatedAt,
    this.items = const <WholesaleFulfillmentItem>[],
  });

  factory WholesaleFulfillment.fromSupabase(
    Map<String, dynamic> data,
  ) {
    final rawItems = data['wholesale_fulfillment_items'];

    final fulfillmentItems = rawItems is List
        ? rawItems
            .map(
              (item) => WholesaleFulfillmentItem.fromSupabase(
                Map<String, dynamic>.from(
                  item as Map,
                ),
              ),
            )
            .toList()
        : <WholesaleFulfillmentItem>[];

    fulfillmentItems.sort(
      (a, b) => a.productName.toLowerCase().compareTo(
            b.productName.toLowerCase(),
          ),
    );

    return WholesaleFulfillment(
      id: (data['id'] ?? '').toString(),
      requestId: (data['request_id'] ?? '').toString(),
      status:
          (data['status'] ?? 'waiting_stock').toString().trim().toLowerCase(),
      assignedTo: _fulfillmentNullableText(
        data['assigned_to'],
      ),
      preparationNotes: (data['preparation_notes'] ?? '').toString().trim(),
      packingNotes: (data['packing_notes'] ?? '').toString().trim(),
      startedAt: _fulfillmentDate(
        data['started_at'],
      ),
      packingStartedAt: _fulfillmentDate(
        data['packing_started_at'],
      ),
      readyAt: _fulfillmentDate(
        data['ready_at'],
      ),
      cancelledAt: _fulfillmentDate(
        data['cancelled_at'],
      ),
      createdBy: _fulfillmentNullableText(
        data['created_by'],
      ),
      createdAt: _fulfillmentDate(
        data['created_at'],
      ),
      updatedAt: _fulfillmentDate(
        data['updated_at'],
      ),
      items: fulfillmentItems,
    );
  }

  // ===================================================
  // STATUS HELPERS
  // ===================================================

  bool get isWaitingStock => status == 'waiting_stock';

  bool get isReadyToPrepare => status == 'ready_to_prepare';

  bool get isPreparing => status == 'preparing';

  bool get isPacking => status == 'packing';

  bool get isReadyForDispatch => status == 'ready_for_dispatch';

  bool get isCancelled => status == 'cancelled';

  String get statusLabel {
    switch (status) {
      case 'ready_to_prepare':
        return 'Ready to Prepare';

      case 'preparing':
        return 'Preparing';

      case 'packing':
        return 'Packing';

      case 'ready_for_dispatch':
        return 'Ready for Dispatch';

      case 'cancelled':
        return 'Cancelled';

      default:
        return 'Waiting Stock';
    }
  }

  int get totalItemCount => items.length;

  int get packedItemCount => items
      .where(
        (item) => item.isPacked,
      )
      .length;

  int get shortItemCount => items
      .where(
        (item) => item.isShort,
      )
      .length;

  int get accountedItemCount => items
      .where(
        (item) => item.isAccountedFor,
      )
      .length;

  bool get allItemsAccountedFor =>
      items.isNotEmpty && accountedItemCount == items.length;

  double get packingProgress {
    if (items.isEmpty) {
      return 0;
    }

    return accountedItemCount / items.length;
  }

  String get progressLabel => '$accountedItemCount / '
      '$totalItemCount items';

  static String? _fulfillmentNullableText(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text = value.toString().trim();

    return text.isEmpty ? null : text;
  }

  static DateTime? _fulfillmentDate(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text = value.toString().trim();

    if (text.isEmpty) {
      return null;
    }

    return DateTime.tryParse(
      text,
    );
  }
}

int mathMaxInt(int first, int second) => first > second ? first : second;
