        data['dispatched_at'],
      ),
      deliveredAt: _dispatchDate(
        data['delivered_at'],
      ),
      collectedAt: _dispatchDate(
        data['collected_at'],
      ),
      cancelledAt: _dispatchDate(
        data['cancelled_at'],
      ),
      recipientName: (data['recipient_name'] ?? '').toString().trim(),
      proofNote: (data['proof_note'] ?? '').toString().trim(),
      proofPhotoPath: (data['proof_photo_path'] ?? '').toString().trim(),
      deliveryLatitude: _dispatchNullableDouble(
        data['delivery_latitude'],
      ),
      deliveryLongitude: _dispatchNullableDouble(
        data['delivery_longitude'],
      ),
      driverNotes: (data['driver_notes'] ?? '').toString().trim(),
      adminNotes: (data['admin_notes'] ?? '').toString().trim(),
      createdBy: _dispatchNullableText(
        data['created_by'],
      ),
      createdAt: _dispatchDate(
        data['created_at'],
      ),
      updatedAt: _dispatchDate(
        data['updated_at'],
      ),
    );
  }

  // ===================================================
  // METHOD HELPERS
  // ===================================================

  bool get isHpjDelivery => dispatchMethod == 'hpj_delivery';

  bool get isBusinessCollection => dispatchMethod == 'business_collection';

  String get dispatchMethodLabel =>
      isBusinessCollection ? 'Business Collection' : 'HPJ Delivery';

  // ===================================================
  // STATUS HELPERS
  // ===================================================

  bool get isPlanned => status == 'planned';

  bool get isAssigned => status == 'assigned';

  bool get isReadyForPickup => status == 'ready_for_pickup';

  bool get isOutForDelivery => status == 'out_for_delivery';

  bool get isDelivered => status == 'delivered';

  bool get isCollected => status == 'collected';

  bool get isCancelled => status == 'cancelled';

  bool get isComplete => isDelivered || isCollected;

  bool get isActive => !isComplete && !isCancelled;

  String get statusLabel {
    switch (status) {
      case 'assigned':
        return 'Assigned';

      case 'ready_for_pickup':
        return 'Ready for Pickup';

      case 'out_for_delivery':
        return 'Out for Delivery';

      case 'delivered':
        return 'Delivered';

      case 'collected':
        return 'Collected';

      case 'cancelled':
        return 'Cancelled';

      default:
        return 'Planned';
    }
  }

  String get shortId {
    final clean = id.replaceAll('-', '').toUpperCase();

    return clean.length <= 8 ? clean : clean.substring(0, 8);
  }

  bool get hasProofPhoto => proofPhotoPath.trim().isNotEmpty;

  bool get hasGps => deliveryLatitude != null && deliveryLongitude != null;

  static String? _dispatchNullableText(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text = value.toString().trim();

    return text.isEmpty ? null : text;
  }

  static double? _dispatchNullableDouble(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    if (value is num) {
      return value.toDouble();
    }

    return double.tryParse(
      value.toString(),
    );
  }

  static DateTime? _dispatchDate(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final text = value.toString().trim();

    if (text.isEmpty) {
      return null;
    }

    return DateTime.tryParse(
      text,
    );
  }
}
// =====================================================
// DELIVERY STAFF
// =====================================================

Future<List<WholesaleDeliveryStaff>> fetchWholesaleDeliveryStaff() async {
  await requireAdminAccess();

  final response = await supabase.rpc(
    'admin_list_wholesale_delivery_staff',
  );

  return (response as List)
      .map(
        (item) => WholesaleDeliveryStaff.fromSupabase(
          Map<String, dynamic>.from(
            item as Map,
          ),
        ),
      )
      .where(
        (item) => item.userId.isNotEmpty,
      )
      .toList();
}

// =====================================================
// DISPATCH PROOF PHOTO
// =====================================================

Future<String> captureWholesaleDispatchProofPhoto(
  WholesaleDispatch dispatch,
) async {
  await requireAdminAccess();

  final picker = ImagePicker();

  final image = await picker.pickImage(
    source: ImageSource.camera,
    imageQuality: 80,
    maxWidth: 1600,
  );

  if (image == null) {
    return '';
  }

  final bytes = await image.readAsBytes();

  if (bytes.isEmpty) {
    throw Exception(
      'The proof photo could not be read.',
    );
  }

  const maxBytes = 6 * 1024 * 1024;

  if (bytes.length > maxBytes) {
    throw Exception(
      'Use a proof photo smaller than 6 MB.',
    );
  }

  final cleanDispatchId = dispatch.id.replaceAll(
    RegExp(r'[^A-Za-z0-9_-]'),
    '',
  );

  final fileName = '${DateTime.now().millisecondsSinceEpoch}.jpg';

  final path = '$cleanDispatchId/$fileName';

  await supabase.storage
      .from(
        'wholesale-dispatch-proofs',
      )
      .uploadBinary(
        path,
        bytes,
        fileOptions: const FileOptions(
          contentType: 'image/jpeg',
          upsert: false,
        ),
      );

  return supabase.storage
      .from(
        'wholesale-dispatch-proofs',
      )
      .getPublicUrl(
        path,
      );
}

