// =====================================================
// WHOLESALE INVOICE
// =====================================================

class WholesaleInvoice {
  final String id;
  final String invoiceNumber;

  final String requestId;
  final String fulfillmentId;

  final String? businessAccountId;

  final String businessName;
  final String contactName;
  final String contactPhone;

  final String billingAddress;
  final String billingParish;

  final String invoiceStatus;
  final String paymentStatus;

  final double subtotal;

  final double deliveryFee;
  final double discountAmount;
  final double taxAmount;
  final double otherAmount;

  final double totalAmount;
  final double paidAmount;
  final double amountDue;

  final int paymentTermsDays;

  final DateTime? issueDate;
  final DateTime? dueDate;

  final String customerNote;
  final String internalNote;

  final DateTime? issuedAt;
  final DateTime? voidedAt;

  final String? createdBy;

  final DateTime? createdAt;
  final DateTime? updatedAt;

  final List<WholesaleInvoiceItem> items;
  final List<WholesaleInvoicePayment> payments;

  const WholesaleInvoice({
    required this.id,
    required this.invoiceNumber,
    required this.requestId,
    required this.fulfillmentId,
    this.businessAccountId,
    required this.businessName,
    required this.contactName,
    required this.contactPhone,
    required this.billingAddress,
    required this.billingParish,
    required this.invoiceStatus,
    required this.paymentStatus,
    required this.subtotal,
    required this.deliveryFee,
    required this.discountAmount,
    required this.taxAmount,
    required this.otherAmount,
    required this.totalAmount,
    required this.paidAmount,
    required this.amountDue,
    required this.paymentTermsDays,
    this.issueDate,
    this.dueDate,
    required this.customerNote,
    required this.internalNote,
    this.issuedAt,
    this.voidedAt,
    this.createdBy,
    this.createdAt,
    this.updatedAt,
    required this.items,
    required this.payments,
  });

  factory WholesaleInvoice.fromSupabase(
    Map<String, dynamic> data,
  ) {
    final rawItems = data['wholesale_invoice_items'];

    final rawPayments = data['wholesale_invoice_payments'];

    final items = rawItems is List
        ? rawItems
            .whereType<Map>()
            .map(
              (item) => WholesaleInvoiceItem.fromSupabase(
                Map<String, dynamic>.from(
                  item,
                ),
              ),
            )
            .toList()
        : <WholesaleInvoiceItem>[];

    final payments = rawPayments is List
        ? rawPayments
            .whereType<Map>()
            .map(
              (item) => WholesaleInvoicePayment.fromSupabase(
                Map<String, dynamic>.from(
                  item,
                ),
              ),
            )
            .toList()
        : <WholesaleInvoicePayment>[];

    items.sort(
      (a, b) => a.productName.toLowerCase().compareTo(
            b.productName.toLowerCase(),
          ),
    );

    payments.sort(
      (a, b) {
        final aDate = a.paidAt ??
            DateTime.fromMillisecondsSinceEpoch(
              0,
            );

        final bDate = b.paidAt ??
            DateTime.fromMillisecondsSinceEpoch(
              0,
            );

        return bDate.compareTo(
          aDate,
        );
      },
    );

    return WholesaleInvoice(
      id: (data['id'] ?? '').toString(),
      invoiceNumber: (data['invoice_number'] ?? '').toString().trim(),
      requestId: (data['request_id'] ?? '').toString(),
      fulfillmentId: (data['fulfillment_id'] ?? '').toString(),
      businessAccountId: _invoiceNullableText(
        data['business_account_id'],
      ),
      businessName: (data['business_name'] ?? '').toString().trim(),
      contactName: (data['contact_name'] ?? '').toString().trim(),
      contactPhone: (data['contact_phone'] ?? '').toString().trim(),
      billingAddress: (data['billing_address'] ?? '').toString().trim(),
      billingParish: (data['billing_parish'] ?? '').toString().trim(),
      invoiceStatus:
          (data['invoice_status'] ?? 'draft').toString().trim().toLowerCase(),
      paymentStatus:
          (data['payment_status'] ?? 'unpaid').toString().trim().toLowerCase(),
      subtotal: _invoiceDouble(
        data['subtotal'],
      ),
      deliveryFee: _invoiceDouble(
        data['delivery_fee'],
      ),
      discountAmount: _invoiceDouble(
        data['discount_amount'],
      ),
      taxAmount: _invoiceDouble(
        data['tax_amount'],
      ),
      otherAmount: _invoiceDouble(
        data['other_amount'],
      ),
      totalAmount: _invoiceDouble(
        data['total_amount'],
      ),
      paidAmount: _invoiceDouble(
        data['paid_amount'],
      ),
      amountDue: _invoiceDouble(
        data['amount_due'],
      ),
      paymentTermsDays: _invoiceInt(
        data['payment_terms_days'],
      ),
      issueDate: _invoiceDate(
        data['issue_date'],
      ),
      dueDate: _invoiceDate(
        data['due_date'],
      ),
      customerNote: (data['customer_note'] ?? '').toString().trim(),
      internalNote: (data['internal_note'] ?? '').toString().trim(),
      issuedAt: _invoiceDate(
        data['issued_at'],
      ),
      voidedAt: _invoiceDate(
        data['voided_at'],
      ),
      createdBy: _invoiceNullableText(
        data['created_by'],
      ),
      createdAt: _invoiceDate(
        data['created_at'],
      ),
      updatedAt: _invoiceDate(
        data['updated_at'],
      ),
      items: items,
      payments: payments,
    );
  }

  // ===================================================
  // INVOICE STATUS
  // ===================================================

  bool get isDraft => invoiceStatus == 'draft';

  bool get isIssued => invoiceStatus == 'issued';

  bool get isVoid => invoiceStatus == 'void';

  String get invoiceStatusLabel {
    switch (invoiceStatus) {
      case 'issued':
        return 'Issued';

      case 'void':
        return 'Void';

      default:
        return 'Draft';
    }
  }

  // ===================================================
  // PAYMENT STATUS
  // ===================================================

  bool get isUnpaid => paymentStatus == 'unpaid';

  bool get isPartiallyPaid => paymentStatus == 'partially_paid';

  bool get isPaid => paymentStatus == 'paid';

  String get paymentStatusLabel {
    switch (paymentStatus) {
      case 'partially_paid':
        return 'Partially Paid';

      case 'paid':
        return 'Paid';

      default:
        return 'Unpaid';
    }
  }

  bool get isOverdue {
    if (!isIssued || isPaid || dueDate == null) {
      return false;
    }

    final today = DateTime.now();

    final todayOnly = DateTime(
      today.year,
      today.month,
      today.day,
    );

    final due = dueDate!.toLocal();

    final dueOnly = DateTime(
      due.year,
      due.month,
      due.day,
    );

    return dueOnly.isBefore(
      todayOnly,
    );
  }

  String get formattedSubtotal => formatJmd(subtotal);

  String get formattedTotal => formatJmd(totalAmount);

  String get formattedPaid => formatJmd(paidAmount);

  String get formattedDue => formatJmd(amountDue);

  static double _invoiceDouble(
    dynamic value,
  ) {
    if (value is num) {
      return value.toDouble();
    }

    return double.tryParse(
          value?.toString() ?? '',
        ) ??
        0;
  }

  static int _invoiceInt(
    dynamic value,
  ) {
    if (value is num) {
      return value.toInt();
    }

    return int.tryParse(
          value?.toString() ?? '',
        ) ??
        0;
  }

  static String? _invoiceNullableText(
    dynamic value,
  ) {
    final clean = value?.toString().trim() ?? '';

    return clean.isEmpty ? null : clean;
  }

  static DateTime? _invoiceDate(
    dynamic value,
  ) {
    if (value == null) {
      return null;
    }

    final clean = value.toString().trim();

    if (clean.isEmpty) {
      return null;
    }

    return DateTime.tryParse(
      clean,
    );
  }
}

