class WholesalePaymentSubmission {
  final String id;
  final String invoiceId;
  final String businessAccountId;
  final String submittedBy;
  final double amount;
  final String paymentMethod;
  final String paymentReference;
  final String proofPath;
  final String note;
  final String status;
  final String adminNote;
  final String? paymentId;
  final String? reviewedBy;
  final DateTime? reviewedAt;
  final DateTime? createdAt;
  final DateTime? updatedAt;

  final String invoiceNumber;
  final String businessName;
  final double invoiceTotal;
  final double invoiceAmountDue;

  const WholesalePaymentSubmission({
    required this.id,
    required this.invoiceId,
    required this.businessAccountId,
    required this.submittedBy,
    required this.amount,
    required this.paymentMethod,
    required this.paymentReference,
    required this.proofPath,
    required this.note,
    required this.status,
    required this.adminNote,
    this.paymentId,
    this.reviewedBy,
    this.reviewedAt,
    this.createdAt,
    this.updatedAt,
    required this.invoiceNumber,
    required this.businessName,
    required this.invoiceTotal,
    required this.invoiceAmountDue,
  });

  factory WholesalePaymentSubmission.fromSupabase(
    Map<String, dynamic> data,
  ) {
    Map<String, dynamic> invoice = const <String, dynamic>{};
    final rawInvoice = data['wholesale_invoices'];

    if (rawInvoice is Map) {
      invoice = Map<String, dynamic>.from(rawInvoice);
    } else if (rawInvoice is List && rawInvoice.isNotEmpty) {
      invoice = Map<String, dynamic>.from(rawInvoice.first as Map);
    }

    return WholesalePaymentSubmission(
      id: (data['id'] ?? '').toString(),
      invoiceId: (data['invoice_id'] ?? '').toString(),
      businessAccountId: (data['business_account_id'] ?? '').toString(),
      submittedBy: (data['submitted_by'] ?? '').toString(),
      amount: Product._toDouble(data['amount']),
      paymentMethod: (data['payment_method'] ?? 'bank_transfer')
          .toString()
          .trim()
          .toLowerCase(),
      paymentReference: (data['payment_reference'] ?? '').toString().trim(),
      proofPath: (data['proof_path'] ?? '').toString().trim(),
      note: (data['note'] ?? '').toString().trim(),
      status: (data['status'] ?? 'pending').toString().trim().toLowerCase(),
      adminNote: (data['admin_note'] ?? '').toString().trim(),
      paymentId: _nullableText(data['payment_id']),
      reviewedBy: _nullableText(data['reviewed_by']),
      reviewedAt: parseProductDate(data['reviewed_at']),
      createdAt: parseProductDate(data['created_at']),
      updatedAt: parseProductDate(data['updated_at']),
      invoiceNumber: (invoice['invoice_number'] ?? '').toString().trim(),
      businessName: (invoice['business_name'] ?? '').toString().trim(),
      invoiceTotal: Product._toDouble(invoice['total_amount']),
      invoiceAmountDue: Product._toDouble(invoice['amount_due']),
    );
  }

  static String? _nullableText(dynamic value) {
    final clean = value?.toString().trim() ?? '';
    return clean.isEmpty ? null : clean;
  }

  bool get isPending => status == 'pending';
  bool get isApproved => status == 'approved';
  bool get isRejected => status == 'rejected';
  bool get isCancelled => status == 'cancelled';

  String get statusLabel {
    switch (status) {
      case 'approved':
        return 'Approved';
      case 'rejected':
        return 'Needs Attention';
      case 'cancelled':
        return 'Cancelled';
      default:
        return 'Waiting Review';
    }
  }

  String get methodLabel {
    switch (paymentMethod) {
      case 'cash':
        return 'Cash';
      case 'card':
        return 'Card';
      case 'cheque':
        return 'Cheque';
      case 'other':
        return 'Other';
      default:
        return 'Bank Transfer';
    }
  }

  String get formattedAmount => formatJmd(amount);
}

