class WholesaleSavedOrderItem {
  final String id;
  final String parentId;
  final String? productId;
  final String productName;
  final double quantity;
  final String unit;
  final double unitPriceSnapshot;

  const WholesaleSavedOrderItem({
    required this.id,
    required this.parentId,
    this.productId,
    required this.productName,
    required this.quantity,
    required this.unit,
    required this.unitPriceSnapshot,
  });

  factory WholesaleSavedOrderItem.fromSupabase(
    Map<String, dynamic> data, {
    required String parentField,
  }) {
    final cleanProductId = data['product_id']?.toString().trim() ?? '';
    return WholesaleSavedOrderItem(
      id: (data['id'] ?? '').toString(),
      parentId: (data[parentField] ?? '').toString(),
      productId: cleanProductId.isEmpty ? null : cleanProductId,
      productName: (data['product_name'] ?? 'Product').toString().trim(),
      quantity: Product._toDouble(data['quantity']),
      unit: (data['unit'] ?? 'unit').toString().trim(),
      unitPriceSnapshot: Product._toDouble(
        data['unit_price_snapshot'] ?? data['fixed_unit_price'],
      ),
    );
  }

  String get quantityLabel {
    if (quantity == quantity.roundToDouble())
      return quantity.toInt().toString();
    return quantity
        .toStringAsFixed(2)
        .replaceFirst(RegExp(r'0+$'), '')
        .replaceFirst(RegExp(r'\.$'), '');
  }
}

