class WholesaleStandingOrder {
  final String id;
  final String businessAccountId;
  final String userId;
  final String businessName;
  final String name;
  final String status;
  final String frequency;
  final DateTime? startDate;
  final DateTime? endDate;
  final DateTime? nextDueDate;
  final String dispatchMethod;
  final String deliveryAddress;
  final String deliveryParish;
  final String notes;
  final String pricingMode;
  final DateTime? approvedAt;
  final String? lastRequestId;
  final DateTime? createdAt;
  final DateTime? updatedAt;
  final List<WholesaleSavedOrderItem> items;

  const WholesaleStandingOrder({
    required this.id,
    required this.businessAccountId,
    required this.userId,
    required this.businessName,
    required this.name,
    required this.status,
    required this.frequency,
    this.startDate,
    this.endDate,
    this.nextDueDate,
    required this.dispatchMethod,
    required this.deliveryAddress,
    required this.deliveryParish,
    required this.notes,
    required this.pricingMode,
    this.approvedAt,
    this.lastRequestId,
    this.createdAt,
    this.updatedAt,
    this.items = const <WholesaleSavedOrderItem>[],
  });

  factory WholesaleStandingOrder.fromSupabase(Map<String, dynamic> data) {
    String businessName = '';
    final rawBusiness = data['business_accounts'];
    if (rawBusiness is Map) {
      businessName = (rawBusiness['business_name'] ?? '').toString().trim();
    } else if (rawBusiness is List && rawBusiness.isNotEmpty) {
      final first = rawBusiness.first;
      if (first is Map) {
        businessName = (first['business_name'] ?? '').toString().trim();
      }
    }

    final rawItems = data['wholesale_standing_order_items'];
    final items = rawItems is List
        ? rawItems
            .whereType<Map>()
            .map(
              (item) => WholesaleSavedOrderItem.fromSupabase(
                Map<String, dynamic>.from(item),
                parentField: 'standing_order_id',
              ),
            )
            .toList()
        : <WholesaleSavedOrderItem>[];

    return WholesaleStandingOrder(
      id: (data['id'] ?? '').toString(),
      businessAccountId: (data['business_account_id'] ?? '').toString(),
      userId: (data['user_id'] ?? '').toString(),
      businessName: businessName,
      name: (data['name'] ?? 'Standing Order').toString().trim(),
      status: (data['status'] ?? 'proposed').toString().trim().toLowerCase(),
      frequency:
          (data['frequency'] ?? 'weekly').toString().trim().toLowerCase(),
      startDate: parseProductDate(data['start_date']),
      endDate: parseProductDate(data['end_date']),
      nextDueDate: parseProductDate(data['next_due_date']),
      dispatchMethod: (data['dispatch_method'] ?? 'hpj_delivery')
          .toString()
          .trim()
          .toLowerCase(),
      deliveryAddress: (data['delivery_address'] ?? '').toString().trim(),
      deliveryParish: (data['delivery_parish'] ?? '').toString().trim(),
      notes: (data['notes'] ?? '').toString().trim(),
      pricingMode:
          (data['pricing_mode'] ?? 'current_wholesale').toString().trim(),
      approvedAt: parseProductDate(data['approved_at']),
      lastRequestId: data['last_request_id']?.toString(),
      createdAt: parseProductDate(data['created_at']),
      updatedAt: parseProductDate(data['updated_at']),
      items: items,
    );
  }

  bool get isProposed => status == 'proposed';
  bool get isActive => status == 'active';
  bool get isPaused => status == 'paused';
  bool get isRejected => status == 'rejected';
  bool get isCancelled => status == 'cancelled';
  bool get isCompleted => status == 'completed';

  String get statusLabel {
    switch (status) {
      case 'active':
        return 'Active';
      case 'paused':
        return 'Paused';
      case 'rejected':
        return 'Needs Attention';
      case 'cancelled':
        return 'Cancelled';
      case 'completed':
        return 'Completed';
      default:
        return 'Awaiting HPJ Approval';
    }
  }

  String get frequencyLabel {
    switch (frequency) {
      case 'biweekly':
        return 'Every 2 Weeks';
      case 'monthly':
        return 'Monthly';
      default:
        return 'Weekly';
    }
  }

  String get dispatchMethodLabel => dispatchMethod == 'business_collection'
      ? 'Business Collection'
      : 'HPJ Delivery';
}

