class WholesaleOrderRequest {
  final String id;
  final String userId;
  final String businessAccountId;
  final String businessName;
  final String contactName;
  final String contactPhone;
  final String deliveryAddress;
  final String deliveryParish;
  final DateTime? requestedDate;
  final String requestedDispatchMethod;
  final String? requestedWindowId;
  final String requestedWindowLabel;
  final DateTime? scheduleReservedAt;
  final String notes;
  final String status;
  final double subtotalEstimate;
  final double? quotedTotal;
  final String adminNotes;
  final DateTime? createdAt;
  final DateTime? updatedAt;
  final BusinessAccount? businessAccount;
  final List<WholesaleRequestLine> items;

  const WholesaleOrderRequest({
    required this.id,
    required this.userId,
    required this.businessAccountId,
    required this.businessName,
    required this.contactName,
    required this.contactPhone,
    required this.deliveryAddress,
    required this.deliveryParish,
    required this.requestedDate,
    this.requestedDispatchMethod = 'hpj_delivery',
    this.requestedWindowId,
    this.requestedWindowLabel = '',
    this.scheduleReservedAt,
    required this.notes,
    required this.status,
    required this.subtotalEstimate,
    this.quotedTotal,
    required this.adminNotes,
    this.createdAt,
    this.updatedAt,
    this.businessAccount,
    this.items = const <WholesaleRequestLine>[],
  });

  factory WholesaleOrderRequest.fromSupabase(Map<String, dynamic> data) {
    BusinessAccount? account;
    final rawAccount = data['business_accounts'];
    if (rawAccount is Map) {
      account = BusinessAccount.fromSupabase(
        Map<String, dynamic>.from(rawAccount),
      );
    } else if (rawAccount is List && rawAccount.isNotEmpty) {
      account = BusinessAccount.fromSupabase(
        Map<String, dynamic>.from(rawAccount.first as Map),
      );
    }

    final rawItems = data['wholesale_order_items'];
    final items = rawItems is List
        ? rawItems
            .map(
              (item) => WholesaleRequestLine.fromSupabase(
                Map<String, dynamic>.from(item as Map),
              ),
            )
            .toList()
        : const <WholesaleRequestLine>[];

    return WholesaleOrderRequest(
      id: (data['id'] ?? '').toString(),
      userId: (data['user_id'] ?? '').toString(),
      businessAccountId: (data['business_account_id'] ?? '').toString(),
      businessName: (data['business_name'] ?? '').toString(),
      contactName: (data['contact_name'] ?? '').toString(),
      contactPhone: (data['contact_phone'] ?? '').toString(),
      deliveryAddress: (data['delivery_address'] ?? '').toString(),
      deliveryParish: (data['delivery_parish'] ?? '').toString(),
      requestedDate: parseProductDate(data['requested_date']),
      requestedDispatchMethod:
          (data['requested_dispatch_method'] ?? 'hpj_delivery')
              .toString()
              .trim()
              .toLowerCase(),
      requestedWindowId: data['requested_window_id']?.toString(),
      requestedWindowLabel:
          (data['requested_window_label'] ?? '').toString().trim(),
      scheduleReservedAt: parseProductDate(data['schedule_reserved_at']),
      notes: (data['notes'] ?? '').toString(),
      status: (data['status'] ?? 'pending').toString().trim().toLowerCase(),
      subtotalEstimate: Product._toDouble(data['subtotal_estimate']),
      quotedTotal: parseNullableDouble(data['quoted_total']),
      adminNotes: (data['admin_notes'] ?? '').toString(),
      createdAt: parseProductDate(data['created_at']),
      updatedAt: parseProductDate(data['updated_at']),
      businessAccount: account,
      items: items,
    );
  }

  String get shortId {
    final clean = id.replaceAll('-', '').toUpperCase();
    return clean.length <= 8 ? clean : clean.substring(0, 8);
  }
}

