Future<BusinessAccount?> fetchCurrentBusinessAccount() async {
  final user = supabase.auth.currentUser;
  if (user == null) return null;

  try {
    final response = await supabase
        .from('business_accounts')
        .select(_businessAccountSelectFields)
        .eq('user_id', user.id)
        .maybeSingle();

    if (response == null) return null;
    return BusinessAccount.fromSupabase(
      Map<String, dynamic>.from(response as Map),
    );
  } catch (error) {
    farmDebugLog('Business account lookup skipped safely: $error');
    return null;
  }
}
// =====================================================
// WHOLESALE PLANNING AHEAD
// DEMAND FORECAST SERVICES
// =====================================================

// =====================================================
// FETCH MY PLANNING AHEAD REQUESTS
// =====================================================

Future<List<WholesaleDemandForecast>> fetchMyWholesaleDemandForecasts({
  bool includeCancelled = true,
}) async {
  final user = supabase.auth.currentUser;

  if (user == null) {
    return const <WholesaleDemandForecast>[];
  }

  try {
    dynamic query = supabase
        .from('wholesale_demand_forecasts')
        .select(_wholesaleDemandSelectFields)
        .eq('user_id', user.id);

    if (!includeCancelled) {
      query = query.neq(
        'status',
        'cancelled',
      );
    }

    final response = await query
        .order(
          'need_by_date',
          ascending: true,
        )
        .limit(100);

    return (response as List)
        .map(
          (item) => WholesaleDemandForecast.fromSupabase(
            Map<String, dynamic>.from(
              item as Map,
            ),
          ),
        )
        .toList();
  } catch (error) {
    farmDebugLog(
      'Wholesale demand forecast load failed: $error',
    );

    return const <WholesaleDemandForecast>[];
  }
}

// =====================================================
// CREATE PLANNING AHEAD FORECAST
// =====================================================

Future<WholesaleDemandForecast> createWholesaleDemandForecast({
  String? productId,
  required String productName,
  String? category,
  required double quantity,
  required String unit,
  required DateTime needByDate,
  String frequency = 'one_time',
  String certainty = 'likely',
  String notes = '',
}) async {
  final user = supabase.auth.currentUser;

  if (user == null) {
    throw Exception(
      'Please sign in before planning a future requirement.',
    );
  }

  final account = await fetchCurrentBusinessAccount();

  if (account == null) {
    throw Exception(
      'A wholesale business account is required.',
    );
  }

  if (!account.isApproved) {
    throw Exception(
      'Your wholesale account must be approved before using Planning Ahead.',
    );
  }

  final cleanProductName = productName.trim();

  final cleanUnit = unit.trim();

  final cleanCategory = category?.trim();

  final cleanProductId = productId?.trim();

  final cleanFrequency = frequency.trim().toLowerCase();

  final cleanCertainty = certainty.trim().toLowerCase();

  if (cleanProductName.isEmpty) {
    throw Exception(
      'Enter the product you expect to need.',
    );
  }

  if (quantity <= 0 || quantity.isNaN || quantity.isInfinite) {
    throw Exception(
      'Enter a valid quantity greater than zero.',
    );
  }

  if (cleanUnit.isEmpty) {
    throw Exception(
      'Select a unit.',
    );
  }

  if (!_wholesaleDemandFrequencies.contains(
    cleanFrequency,
  )) {
    throw Exception(
      'Select a valid frequency.',
    );
  }

  if (!_wholesaleDemandCertainties.contains(
    cleanCertainty,
  )) {
    throw Exception(
      'Select a valid planning confidence.',
    );
  }

  final todayNow = DateTime.now();

  final today = DateTime(
    todayNow.year,
    todayNow.month,
    todayNow.day,
  );

  final targetDate = DateTime(
    needByDate.year,
    needByDate.month,
    needByDate.day,
  );

  if (targetDate.isBefore(today)) {
    throw Exception(
      'The need-by date cannot be in the past.',
    );
  }

  final response = await supabase
      .from('wholesale_demand_forecasts')
      .insert({
        'user_id': user.id,
        'business_account_id': account.id,

        'product_id': cleanProductId == null || cleanProductId.isEmpty
            ? null
            : cleanProductId,

        'product_name': cleanProductName,

        'category': cleanCategory == null || cleanCategory.isEmpty
            ? null
            : cleanCategory,

        'quantity': quantity,

        'unit': cleanUnit,

        'need_by_date': _wholesaleDemandDateIso(
          targetDate,
        ),

        'frequency': cleanFrequency,

        'certainty': cleanCertainty,

        // A Planning Ahead entry is NOT an order.
        'status': 'forecast',

        'notes': notes.trim(),
      })
      .select(
        _wholesaleDemandSelectFields,
      )
      .single();

  final forecast = WholesaleDemandForecast.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );

  await createAdminNotification(
    title: 'New wholesale demand forecast',
    message:
        '${account.displayName} expects ${forecast.formattedQuantity} of ${forecast.productName}.',
    type: 'wholesale',
    actionType: 'admin_wholesale_demand',
    actionId: forecast.id,
    dedupeKey: 'admin-wholesale-demand:${forecast.id}',
  );

  return forecast;
}

// =====================================================
// MULTI-ITEM PLANNING AHEAD
// Saves several product forecasts in one atomic insert.
// Each product remains a separate demand row for matching.
// =====================================================

class WholesaleDemandPlanItem {
  final String? productId;
  final String productName;
  final String? category;
  final double quantity;
  final String unit;
  final DateTime needByDate;

  const WholesaleDemandPlanItem({
    this.productId,
    required this.productName,
    this.category,
    required this.quantity,
    required this.unit,
    required this.needByDate,
  });
}

Future<List<WholesaleDemandForecast>> createWholesaleDemandForecastBatch({
  required List<WholesaleDemandPlanItem> items,
  String frequency = 'one_time',
  String certainty = 'likely',
  String notes = '',
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Please sign in before planning a future requirement.');
  }
  if (items.isEmpty) {
    throw Exception('Choose at least one product to plan.');
  }
  if (items.length > 25) {
    throw Exception('Please keep each Planning Ahead list to 25 products or fewer.');
  }

  final account = await fetchCurrentBusinessAccount();
  if (account == null) {
    throw Exception('A wholesale business account is required.');
  }
  if (!account.isApproved) {
    throw Exception(
      'Your wholesale account must be approved before using Planning Ahead.',
    );
  }

  final cleanFrequency = frequency.trim().toLowerCase();
  final cleanCertainty = certainty.trim().toLowerCase();
  if (!_wholesaleDemandFrequencies.contains(cleanFrequency)) {
    throw Exception('Select a valid frequency.');
  }
  if (!_wholesaleDemandCertainties.contains(cleanCertainty)) {
    throw Exception('Select a valid planning confidence.');
  }

  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  final seen = <String>{};
  final planGroupId =
      'plan_${user.id}_${DateTime.now().toUtc().microsecondsSinceEpoch}';
  final rows = <Map<String, dynamic>>[];

  for (final item in items) {
    final productName = item.productName.trim();
    final productId = item.productId?.trim();
    final category = item.category?.trim();
    final unit = item.unit.trim();

    if (productName.isEmpty) {
      throw Exception('Every planned item needs a product.');
    }
    if (item.quantity <= 0 || item.quantity.isNaN || item.quantity.isInfinite) {
      throw Exception('Enter a valid quantity for $productName.');
    }
    if (unit.isEmpty) {
      throw Exception('Select a unit for $productName.');
    }

    final target = DateTime(
      item.needByDate.year,
      item.needByDate.month,
      item.needByDate.day,
    );
    if (target.isBefore(today)) {
      throw Exception('The need-by date for $productName cannot be in the past.');
    }

    final duplicateKey = productId != null && productId.isNotEmpty
        ? 'id:$productId'
        : 'name:${productName.toLowerCase()}';
    if (!seen.add(duplicateKey)) {
      throw Exception('$productName is already in this planning list.');
    }

    rows.add({
      'user_id': user.id,
      'business_account_id': account.id,
      'plan_group_id': planGroupId,
      'product_id': productId == null || productId.isEmpty ? null : productId,
      'product_name': productName,
      'category': category == null || category.isEmpty ? null : category,
      'quantity': item.quantity,
      'unit': unit,
      'need_by_date': _wholesaleDemandDateIso(target),
      'frequency': cleanFrequency,
      'certainty': cleanCertainty,
      'status': 'forecast',
      'notes': notes.trim(),
    });
  }

  // PostgREST sends this as one INSERT statement, so the planning list is
  // all-or-nothing instead of leaving a half-saved list if one row fails.
  final response = await supabase
      .from('wholesale_demand_forecasts')
      .insert(rows)
      .select(_wholesaleDemandSelectFields);

  final forecasts = (response as List)
      .map(
        (item) => WholesaleDemandForecast.fromSupabase(
          Map<String, dynamic>.from(item as Map),
        ),
      )
      .toList();

  // The plan itself is already saved. A notification problem must not make
  // the business think the planning list failed and submit it again.
  try {
    final preview = forecasts.take(3).map((item) => item.productName).join(', ');
    final more = forecasts.length > 3 ? ' +${forecasts.length - 3} more' : '';
    await createAdminNotification(
      title: 'New wholesale planning list',
      message:
          '${account.displayName} added ${forecasts.length} planned item${forecasts.length == 1 ? '' : 's'}: $preview$more.',
      type: 'wholesale',
      actionType: 'admin_wholesale_demand',
      actionId: forecasts.isEmpty ? null : forecasts.first.id,
      dedupeKey: forecasts.isEmpty
          ? null
          : 'admin-wholesale-planning:${forecasts.first.id}:'
              '${forecasts.length}',
    );
  } catch (error) {
    farmDebugLog(
      'Planning list saved, but admin notification was skipped: $error',
    );
  }

  return forecasts;
}

// =====================================================
// UPDATE MY FORECAST
//
// Only records still in "forecast" status should be
// editable by the business customer.
// =====================================================

Future<WholesaleDemandForecast> updateWholesaleDemandForecast({
  required WholesaleDemandForecast forecast,
  String? productId,
  required String productName,
  String? category,
  required double quantity,
  required String unit,
  required DateTime needByDate,
  required String frequency,
  required String certainty,
  String notes = '',
}) async {
  final user = supabase.auth.currentUser;

  if (user == null) {
    throw Exception(
      'Please sign in again.',
    );
  }

  if (!forecast.isForecast) {
    throw Exception(
      'This requirement is already being handled by HPJ and can no longer be edited.',
    );
  }

  if (forecast.userId != user.id) {
    throw Exception(
      'You do not have permission to update this requirement.',
    );
  }

  final account = await fetchCurrentBusinessAccount();

  if (account == null || !account.isApproved) {
    throw Exception(
      'An approved wholesale account is required.',
    );
  }

  if (account.id != forecast.businessAccountId) {
    throw Exception(
      'This requirement does not belong to your business account.',
    );
  }

  final cleanProductName = productName.trim();

  final cleanProductId = productId?.trim();

  final cleanCategory = category?.trim();

  final cleanUnit = unit.trim();

  final cleanFrequency = frequency.trim().toLowerCase();

  final cleanCertainty = certainty.trim().toLowerCase();

  if (cleanProductName.isEmpty) {
    throw Exception(
      'Product name is required.',
    );
  }

  if (quantity <= 0 || quantity.isNaN || quantity.isInfinite) {
    throw Exception(
      'Enter a valid quantity greater than zero.',
    );
  }

  if (cleanUnit.isEmpty) {
    throw Exception(
      'Select a unit.',
    );
  }

  if (!_wholesaleDemandFrequencies.contains(
    cleanFrequency,
  )) {
    throw Exception(
      'Select a valid frequency.',
    );
  }

  if (!_wholesaleDemandCertainties.contains(
    cleanCertainty,
  )) {
    throw Exception(
      'Select a valid planning confidence.',
    );
  }

  final todayNow = DateTime.now();

  final today = DateTime(
    todayNow.year,
    todayNow.month,
    todayNow.day,
  );

  final targetDate = DateTime(
    needByDate.year,
    needByDate.month,
    needByDate.day,
  );

  if (targetDate.isBefore(today)) {
    throw Exception(
      'The need-by date cannot be in the past.',
    );
  }

  final response = await supabase
      .from('wholesale_demand_forecasts')
      .update({
        'product_id': cleanProductId == null || cleanProductId.isEmpty
            ? null
            : cleanProductId,
        'product_name': cleanProductName,
        'category': cleanCategory == null || cleanCategory.isEmpty
            ? null
            : cleanCategory,
        'quantity': quantity,
        'unit': cleanUnit,
        'need_by_date': _wholesaleDemandDateIso(
          targetDate,
        ),
        'frequency': cleanFrequency,
        'certainty': cleanCertainty,
        'notes': notes.trim(),
      })
      .eq(
        'id',
        forecast.id,
      )
      .eq(
        'user_id',
        user.id,
      )
      .eq(
        'status',
        'forecast',
      )
      .select(
        _wholesaleDemandSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This requirement could not be updated. HPJ may already be processing it.',
    );
  }

  return WholesaleDemandForecast.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// CANCEL MY FORECAST
// =====================================================

Future<void> cancelWholesaleDemandForecast(
  String forecastId,
) async {
  final user = supabase.auth.currentUser;

  if (user == null) {
    throw Exception(
      'Please sign in again.',
    );
  }

  final cleanId = forecastId.trim();

  if (cleanId.isEmpty) {
    throw Exception(
      'Invalid Planning Ahead requirement.',
    );
  }

  final response = await supabase
      .from('wholesale_demand_forecasts')
      .update({
        'status': 'cancelled',
      })
      .eq(
        'id',
        cleanId,
      )
      .eq(
        'user_id',
        user.id,
      )
      .eq(
        'status',
        'forecast',
      )
      .select('id')
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This requirement can no longer be cancelled.',
    );
  }
}

// =====================================================
// ADMIN — FETCH ALL DEMAND FORECASTS
// =====================================================

Future<List<WholesaleDemandForecast>> fetchAdminWholesaleDemandForecasts({
  String? status,
}) async {
  await requireAdminAccess();

  final cleanStatus = status?.trim().toLowerCase();

  if (cleanStatus != null &&
      cleanStatus.isNotEmpty &&
      !_wholesaleDemandStatuses.contains(
        cleanStatus,
      )) {
    throw Exception(
      'Invalid demand forecast status.',
    );
  }

  dynamic query = supabase.from('wholesale_demand_forecasts').select(
        _wholesaleDemandSelectFields,
      );

  if (cleanStatus != null && cleanStatus.isNotEmpty) {
    query = query.eq(
      'status',
      cleanStatus,
    );
  }

  final response = await query
      .order(
        'need_by_date',
        ascending: true,
      )
      .limit(500);

  return (response as List)
      .map(
        (item) => WholesaleDemandForecast.fromSupabase(
          Map<String, dynamic>.from(
            item as Map,
          ),
        ),
      )
      .toList();
}

// =====================================================
// ADMIN — CHANGE FORECAST STATUS
//
// This will later power:
// Forecast → Matched → Reserved → Converted
// =====================================================

Future<void> adminUpdateWholesaleDemandForecast({
  required WholesaleDemandForecast forecast,
  required String status,
  String adminNotes = '',
  String? convertedRequestId,
}) async {
  await requireAdminAccess();

  final cleanStatus = status.trim().toLowerCase();

  if (!_wholesaleDemandStatuses.contains(
    cleanStatus,
  )) {
    throw Exception(
      'Invalid demand forecast status.',
    );
  }

  final payload = <String, dynamic>{
    'status': cleanStatus,
    'admin_notes': adminNotes.trim(),
  };

  final cleanConvertedId = convertedRequestId?.trim();

  if (cleanStatus == 'converted') {
    if (cleanConvertedId == null || cleanConvertedId.isEmpty) {
      throw Exception(
        'A wholesale request must be linked before marking this forecast as converted.',
      );
    }

    payload['converted_request_id'] = cleanConvertedId;
  } else {
    payload['converted_request_id'] = null;
  }

  await supabase.from('wholesale_demand_forecasts').update(payload).eq(
        'id',
        forecast.id,
      );

  String message;

  switch (cleanStatus) {
    case 'matched':
      message =
          '${forecast.productName} has been matched with expected farm supply.';
      break;

    case 'reserved':
      message = '${forecast.productName} has moved to reserved supply.';
      break;

    case 'converted':
      message =
          '${forecast.productName} has been converted to a wholesale request.';
      break;

    case 'cancelled':
      message = '${forecast.productName} planning requirement was cancelled.';
      break;

    default:
      message = '${forecast.productName} has been returned to Planning Ahead.';
  }

  await createFarmNotification(
    title: 'Planning Ahead update',
    message: message,
    type: 'wholesale',
    userId: forecast.userId,
    actionType: 'wholesale_plan',
    actionId: forecast.id,
    dedupeKey:
        'wholesale-plan:${forecast.id}:${status.trim().toLowerCase()}',
  );
}
// =====================================================
// SUPPLY → DEMAND ALLOCATION SERVICES
// =====================================================

String _normalizeProcurementName(String value) {
  var clean = value
      .trim()
      .toLowerCase()
      .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();

  const aliases = <String, String>{
    'scotch bonnet pepper': 'scotch bonnet',
    'scotch bonnet peppers': 'scotch bonnet',
    'bell pepper': 'sweet pepper',
    'bell peppers': 'sweet pepper',
    'green plantain': 'plantain',
    'green plantains': 'plantain',
    'escallion': 'scallion',
    'escallions': 'scallion',
  };

  return aliases[clean] ?? clean;
}

String _normalizeProcurementUnit(String value) {
  final clean = value.trim().toLowerCase();

  const aliases = <String, String>{
    'lb': 'lb',
    'lbs': 'lb',
    'pound': 'lb',
    'pounds': 'lb',
    'kg': 'kg',
    'kgs': 'kg',
    'kilogram': 'kg',
    'kilograms': 'kg',
    'unit': 'each',
    'units': 'each',
    'each': 'each',
    'ea': 'each',
    'crate': 'crate',
    'crates': 'crate',
    'bag': 'bag',
    'bags': 'bag',
    'dozen': 'dozen',
    'doz': 'dozen',
    'case': 'case',
    'cases': 'case',
    'tray': 'tray',
    'trays': 'tray',
    'bunch': 'bunch',
    'bunches': 'bunch',
  };

  return aliases[clean] ?? clean;
}

// =====================================================
// FETCH ALLOCATIONS
// =====================================================

Future<List<SupplyDemandAllocation>> fetchSupplyDemandAllocations({
  String? demandForecastId,
  String? supplyForecastId,
  bool includeInactive = false,
}) async {
  await requireAdminAccess();

  try {
    dynamic query = supabase.from('supply_demand_allocations').select(
          _supplyAllocationSelectFields,
        );

    final cleanDemandId = demandForecastId?.trim();

    final cleanSupplyId = supplyForecastId?.trim();

    if (cleanDemandId != null && cleanDemandId.isNotEmpty) {
      query = query.eq(
        'demand_forecast_id',
        cleanDemandId,
      );
    }

    if (cleanSupplyId != null && cleanSupplyId.isNotEmpty) {
      query = query.eq(
        'supply_forecast_id',
        cleanSupplyId,
      );
    }

    if (!includeInactive) {
      query = query.inFilter(
        'status',
        [
          'reserved',
          'converted',
        ],
      );
    }

    final response = await query.order(
      'created_at',
      ascending: false,
    );

    return (response as List)
        .map(
          (item) => SupplyDemandAllocation.fromSupabase(
            Map<String, dynamic>.from(
              item as Map,
            ),
          ),
        )
        .toList();
  } catch (error) {
    farmDebugLog(
      'Supply allocation load failed: $error',
    );

    rethrow;
  }
}

// =====================================================
// RESERVED QUANTITY FOR ONE SUPPLY RECORD
// =====================================================

Future<double> fetchAllocatedSupplyQuantity(
  String supplyForecastId,
) async {
  final allocations = await fetchSupplyDemandAllocations(
    supplyForecastId: supplyForecastId,
  );

  var total = 0.0;

  for (final allocation in allocations) {
    total += allocation.allocatedQuantity;
  }

  return total;
}

// =====================================================
// RESERVED QUANTITY FOR ONE DEMAND RECORD
// =====================================================

Future<double> fetchAllocatedDemandQuantity(
  String demandForecastId,
) async {
  final allocations = await fetchSupplyDemandAllocations(
    demandForecastId: demandForecastId,
  );

  var total = 0.0;

  for (final allocation in allocations) {
    total += allocation.allocatedQuantity;
  }

  return total;
}

// =====================================================
// CREATE / RESTORE RESERVATION
// =====================================================

Future<SupplyDemandAllocation> createSupplyDemandAllocation({
  required FarmerSupplyForecast supply,
  required WholesaleDemandForecast demand,
  required double quantity,
  String adminNotes = '',
}) async {
  await requireAdminAccess();

  if (!supply.isHpjConfirmed) {
    throw Exception(
      'Only HPJ-confirmed farmer supply can be reserved.',
    );
  }

  final confirmedQuantity = supply.hpjConfirmedQuantity ?? 0;

  if (confirmedQuantity <= 0) {
    throw Exception(
      'This farmer supply has no confirmed quantity.',
    );
  }

  if (quantity <= 0 || quantity.isNaN || quantity.isInfinite) {
    throw Exception(
      'Enter a valid reservation quantity.',
    );
  }

  final supplyName = _normalizeProcurementName(supply.cropName);

  final demandName = _normalizeProcurementName(demand.productName);

  if (supplyName != demandName) {
    throw Exception(
      'The farmer crop does not match the wholesale requirement.',
    );
  }

  final supplyUnit = _normalizeProcurementUnit(supply.unit);

  final demandUnit = _normalizeProcurementUnit(demand.unit);

  if (supplyUnit != demandUnit) {
    throw Exception(
      'Supply and demand units must match.',
    );
  }

  // ---------------------------------------------------
  // Enforce live availability in the service layer too.
  // The UI also calculates availability, but this prevents
  // stale screens or two admins from over-reserving supply.
  // ---------------------------------------------------

  final existingSupplyAllocations = await fetchSupplyDemandAllocations(
    supplyForecastId: supply.id,
  );
  final existingDemandAllocations = await fetchSupplyDemandAllocations(
    demandForecastId: demand.id,
  );

  double currentPairQuantity = 0;
  double usedSupply = 0;
  for (final allocation in existingSupplyAllocations) {
    usedSupply += allocation.allocatedQuantity;
    if (allocation.demandForecastId == demand.id) {
      currentPairQuantity = allocation.allocatedQuantity;
    }
  }

  double usedDemand = 0;
  for (final allocation in existingDemandAllocations) {
    usedDemand += allocation.allocatedQuantity;
  }

  final usedElsewhere = usedSupply - currentPairQuantity;
  final demandUsedElsewhere = usedDemand - currentPairQuantity;
  final supplyAvailable = confirmedQuantity - usedElsewhere;
  final demandAvailable = demand.quantity - demandUsedElsewhere;
  final maximumAllowed = supplyAvailable < demandAvailable
      ? supplyAvailable
      : demandAvailable;

  if (maximumAllowed <= 0 || quantity > maximumAllowed + 0.0001) {
    throw Exception(
      'Only ${maximumAllowed < 0 ? 0 : maximumAllowed.toStringAsFixed(maximumAllowed == maximumAllowed.roundToDouble() ? 0 : 1)} ${supply.unit} is currently available for this requirement.',
    );
  }

  // ---------------------------------------------------
  // Check whether this exact farm supply → demand pair
  // already exists.
  //
  // The database uses a unique pair, so a previously
  // released reservation is restored rather than
  // creating a duplicate row.
  // ---------------------------------------------------

  final existingResponse = await supabase
      .from(
        'supply_demand_allocations',
      )
      .select(
        _supplyAllocationSelectFields,
      )
      .eq(
        'supply_forecast_id',
        supply.id,
      )
      .eq(
        'demand_forecast_id',
        demand.id,
      )
      .maybeSingle();

  if (existingResponse != null) {
    final existing = SupplyDemandAllocation.fromSupabase(
      Map<String, dynamic>.from(
        existingResponse as Map,
      ),
    );

    if (existing.isConverted) {
      throw Exception(
        'This supply allocation has already been converted to an order.',
      );
    }

    final response = await supabase
        .from(
          'supply_demand_allocations',
        )
        .update({
          'allocated_quantity': quantity,
          'unit': supply.unit,
          'status': 'reserved',
          'admin_notes': adminNotes.trim(),
          'wholesale_request_id': null,
        })
        .eq(
          'id',
          existing.id,
        )
        .select(
          _supplyAllocationSelectFields,
        )
        .single();

    return SupplyDemandAllocation.fromSupabase(
      Map<String, dynamic>.from(
        response as Map,
      ),
    );
  }

  final user = supabase.auth.currentUser;

  final response = await supabase
      .from(
        'supply_demand_allocations',
      )
      .insert({
        'supply_forecast_id': supply.id,
        'demand_forecast_id': demand.id,
        'allocated_quantity': quantity,
        'unit': supply.unit,
        'status': 'reserved',
        'admin_notes': adminNotes.trim(),
        'created_by': user?.id,
      })
      .select(
        _supplyAllocationSelectFields,
      )
      .single();

  return SupplyDemandAllocation.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// UPDATE RESERVATION QUANTITY
// =====================================================

Future<SupplyDemandAllocation> updateSupplyDemandAllocation({
  required SupplyDemandAllocation allocation,
  required double quantity,
  String? adminNotes,
}) async {
  await requireAdminAccess();

  if (!allocation.isReserved) {
    throw Exception(
      'Only active reservations can be changed.',
    );
  }

  if (quantity <= 0 || quantity.isNaN || quantity.isInfinite) {
    throw Exception(
      'Enter a valid reservation quantity.',
    );
  }

  final payload = <String, dynamic>{
    'allocated_quantity': quantity,
  };

  if (adminNotes != null) {
    payload['admin_notes'] = adminNotes.trim();
  }

  final response = await supabase
      .from(
        'supply_demand_allocations',
      )
      .update(payload)
      .eq(
        'id',
        allocation.id,
      )
      .eq(
        'status',
        'reserved',
      )
      .select(
        _supplyAllocationSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This reservation can no longer be changed.',
    );
  }

  return SupplyDemandAllocation.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// RELEASE RESERVED SUPPLY
//
// We do NOT delete allocation history.
// =====================================================

Future<void> releaseSupplyDemandAllocation(
  SupplyDemandAllocation allocation, {
  String adminNotes = '',
}) async {
  await requireAdminAccess();

  if (allocation.isConverted) {
    throw Exception(
      'Converted supply cannot be released from Planning Ahead.',
    );
  }

  await supabase
      .from(
    'supply_demand_allocations',
  )
      .update({
    'status': 'released',
    'admin_notes':
        adminNotes.trim().isEmpty ? allocation.adminNotes : adminNotes.trim(),
    'wholesale_request_id': null,
  }).eq(
    'id',
    allocation.id,
  );
}

// =====================================================
// CONVERT ALLOCATION
//
// Actual order conversion will call this later.
// =====================================================

Future<void> convertSupplyDemandAllocation({
  required SupplyDemandAllocation allocation,
  required String wholesaleRequestId,
}) async {
  await requireAdminAccess();

  if (!allocation.isReserved) {
    throw Exception(
      'Only reserved supply can be converted.',
    );
  }

  final cleanRequestId = wholesaleRequestId.trim();

  if (cleanRequestId.isEmpty) {
    throw Exception(
      'A wholesale request is required.',
    );
  }

  await supabase
      .from(
    'supply_demand_allocations',
  )
      .update({
    'status': 'converted',
    'wholesale_request_id': cleanRequestId,
  }).eq(
    'id',
    allocation.id,
  );
}

// =====================================================
// ENSURE COLLECTION / RECEIVING PLACEHOLDERS
//
// Once farmer supply is converted into a real wholesale order,
// create one planned receiving batch per converted allocation.
// Admin can then schedule the date/route in Collection Planning
// instead of manually recreating the procurement link.
// =====================================================

Future<int> ensureWholesaleReceivingBatchesForDemand({
  required String demandForecastId,
  required String wholesaleRequestId,
}) async {
  await requireAdminAccess();

  final cleanDemandId = demandForecastId.trim();
  final cleanRequestId = wholesaleRequestId.trim();

  if (cleanDemandId.isEmpty || cleanRequestId.isEmpty) return 0;

  final allocations = await fetchSupplyDemandAllocations(
    demandForecastId: cleanDemandId,
  );

  final existing = await fetchWholesaleReceivingBatches(
    wholesaleRequestId: cleanRequestId,
    includeCancelled: true,
  );

  final existingAllocationIds = existing
      .where((batch) => !batch.isCancelled)
      .map((batch) => batch.allocationId)
      .toSet();

  var created = 0;

  for (final allocation in allocations) {
    if (!allocation.isConverted ||
        allocation.wholesaleRequestId != cleanRequestId ||
        existingAllocationIds.contains(allocation.id)) {
      continue;
    }

    await createWholesaleReceivingBatch(
      allocation: allocation,
      scheduledQuantity: allocation.allocatedQuantity,
      notes: 'Created automatically when procurement was confirmed.',
    );

    existingAllocationIds.add(allocation.id);
    created += 1;
  }

  return created;
}

// =====================================================
// ADMIN — CONVERT RESERVED DEMAND TO WHOLESALE REQUEST
// =====================================================

Future<String> adminConvertReservedDemandToRequest({
  required WholesaleDemandForecast demand,
  required double unitPrice,
  required String deliveryAddress,
  required String deliveryParish,
  required DateTime requestedDate,
  String notes = '',
}) async {
  await requireAdminAccess();

  if (!demand.isReserved) {
    throw Exception(
      'This requirement must be fully reserved before conversion.',
    );
  }

  if (unitPrice <= 0 || unitPrice.isNaN || unitPrice.isInfinite) {
    throw Exception(
      'Enter a valid wholesale unit price.',
    );
  }

  final cleanDeliveryParish = normalizeOptionalJamaicaParish(
    deliveryParish,
    fieldLabel: 'Delivery parish',
  );

  final response = await supabase.rpc(
    'admin_convert_reserved_demand_to_request',
    params: {
      'p_demand_forecast_id': demand.id,
      'p_unit_price': unitPrice,
      'p_delivery_address':
          deliveryAddress.trim().isEmpty ? null : deliveryAddress.trim(),
      'p_delivery_parish': cleanDeliveryParish,
      'p_requested_date': _wholesaleDemandDateIso(
        requestedDate,
      ),
      'p_notes': notes.trim(),
    },
  );

  final requestId = response?.toString().trim() ?? '';

  if (requestId.isEmpty) {
    throw Exception(
      'The wholesale request could not be created.',
    );
  }

  return requestId;
}
// =====================================================
// WHOLESALE RECEIVING SERVICES
// =====================================================

// =====================================================
// FETCH RECEIVING BATCHES
// =====================================================

Future<List<WholesaleReceivingBatch>> fetchWholesaleReceivingBatches({
  String? wholesaleRequestId,
  String? allocationId,
  String? farmerId,
  String? status,
  bool includeCancelled = false,
}) async {
  await requireAdminAccess();

  final cleanStatus = status?.trim().toLowerCase();

  if (cleanStatus != null &&
      cleanStatus.isNotEmpty &&
      !_wholesaleReceivingStatuses.contains(cleanStatus)) {
    throw Exception(
      'Invalid receiving status.',
    );
  }

  try {
    dynamic query = supabase
        .from(
          'wholesale_receiving_batches',
        )
        .select(
          _wholesaleReceivingSelectFields,
        );

    final cleanRequestId = wholesaleRequestId?.trim();

    final cleanAllocationId = allocationId?.trim();

    final cleanFarmerId = farmerId?.trim();

    if (cleanRequestId != null && cleanRequestId.isNotEmpty) {
      query = query.eq(
        'wholesale_request_id',
        cleanRequestId,
      );
    }

    if (cleanAllocationId != null && cleanAllocationId.isNotEmpty) {
      query = query.eq(
        'allocation_id',
        cleanAllocationId,
      );
    }

    if (cleanFarmerId != null && cleanFarmerId.isNotEmpty) {
      query = query.eq(
        'farmer_id',
        cleanFarmerId,
      );
    }

    if (cleanStatus != null && cleanStatus.isNotEmpty) {
      query = query.eq(
        'status',
        cleanStatus,
      );
    } else if (!includeCancelled) {
      query = query.neq(
        'status',
        'cancelled',
      );
    }

    final response = await query.order(
      'created_at',
      ascending: false,
    );

    return (response as List)
        .map(
          (item) => WholesaleReceivingBatch.fromSupabase(
            Map<String, dynamic>.from(
              item as Map,
            ),
          ),
        )
        .toList();
  } catch (error) {
    farmDebugLog(
      'Wholesale receiving load failed: $error',
    );

    rethrow;
  }
}

// =====================================================
// CREATE RECEIVING / COLLECTION BATCH
// =====================================================

Future<WholesaleReceivingBatch> createWholesaleReceivingBatch({
  required SupplyDemandAllocation allocation,
  required double scheduledQuantity,
  DateTime? collectionDate,
  String collectionMethod = 'hpj_collection',
  double? farmerUnitCost,
  String notes = '',
}) async {
  await requireAdminAccess();

  if (!allocation.isConverted || allocation.wholesaleRequestId == null) {
    throw Exception(
      'This farmer supply must first be converted to a wholesale request.',
    );
  }

  if (scheduledQuantity <= 0 ||
      scheduledQuantity.isNaN ||
      scheduledQuantity.isInfinite) {
    throw Exception(
      'Enter a valid collection quantity.',
    );
  }

  final cleanMethod = collectionMethod.trim().toLowerCase();

  if (!_wholesaleCollectionMethods.contains(cleanMethod)) {
    throw Exception(
      'Select a valid collection method.',
    );
  }

  if (farmerUnitCost != null &&
      (farmerUnitCost < 0 ||
          farmerUnitCost.isNaN ||
          farmerUnitCost.isInfinite)) {
    throw Exception(
      'Enter a valid farmer unit cost.',
    );
  }

  final initialStatus =
      collectionDate == null ? 'planned' : 'collection_scheduled';

  final response = await supabase
      .from(
        'wholesale_receiving_batches',
      )
      .insert({
        // The database trigger fills all trusted
        // request/farmer/supply IDs from this allocation.
        'allocation_id': allocation.id,

        'scheduled_quantity': scheduledQuantity,

        'collection_method': cleanMethod,

        'collection_date': collectionDate == null
            ? null
            : _wholesaleDemandDateIso(
                collectionDate,
              ),

        'farmer_unit_cost': farmerUnitCost,

        'status': initialStatus,

        'notes': notes.trim(),
      })
      .select(
        _wholesaleReceivingSelectFields,
      )
      .single();

  return WholesaleReceivingBatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// EDIT COLLECTION PLAN
// Only before produce has been collected.
// =====================================================

Future<WholesaleReceivingBatch> updateWholesaleReceivingBatchPlan({
  required WholesaleReceivingBatch batch,
  required double scheduledQuantity,
  DateTime? collectionDate,
  required String collectionMethod,
  double? farmerUnitCost,
  String? notes,
}) async {
  await requireAdminAccess();

  if (!batch.isPlanned && !batch.isCollectionScheduled) {
    throw Exception(
      'This collection has already started and can no longer be rescheduled.',
    );
  }

  if (scheduledQuantity <= 0 ||
      scheduledQuantity.isNaN ||
      scheduledQuantity.isInfinite) {
    throw Exception(
      'Enter a valid collection quantity.',
    );
  }

  final cleanMethod = collectionMethod.trim().toLowerCase();

  if (!_wholesaleCollectionMethods.contains(cleanMethod)) {
    throw Exception(
      'Select a valid collection method.',
    );
  }

  if (farmerUnitCost != null &&
      (farmerUnitCost < 0 ||
          farmerUnitCost.isNaN ||
          farmerUnitCost.isInfinite)) {
    throw Exception(
      'Enter a valid farmer unit cost.',
    );
  }

  final nextStatus =
      collectionDate == null ? 'planned' : 'collection_scheduled';

  final response = await supabase
      .from(
        'wholesale_receiving_batches',
      )
      .update({
        'scheduled_quantity': scheduledQuantity,
        'collection_date': collectionDate == null
            ? null
            : _wholesaleDemandDateIso(
                collectionDate,
              ),
        'collection_method': cleanMethod,
        'farmer_unit_cost': farmerUnitCost,
        'status': nextStatus,
        if (notes != null) 'notes': notes.trim(),
      })
      .eq(
        'id',
        batch.id,
      )
      .inFilter(
        'status',
        [
          'planned',
          'collection_scheduled',
        ],
      )
      .select(
        _wholesaleReceivingSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This collection plan can no longer be changed.',
    );
  }

  return WholesaleReceivingBatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// MARK PRODUCE COLLECTED
// =====================================================

Future<WholesaleReceivingBatch> markWholesaleBatchCollected({
  required WholesaleReceivingBatch batch,
  required double collectedQuantity,
}) async {
  await requireAdminAccess();

  if (!batch.isPlanned && !batch.isCollectionScheduled) {
    throw Exception(
      'This batch is not waiting for collection.',
    );
  }

  if (collectedQuantity <= 0 || collectedQuantity > batch.scheduledQuantity) {
    throw Exception(
      'Collected quantity must be greater than zero and cannot exceed the scheduled quantity.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_receiving_batches',
      )
      .update({
        'collected_quantity': collectedQuantity,
        'status': 'collected',
      })
      .eq(
        'id',
        batch.id,
      )
      .inFilter(
        'status',
        [
          'planned',
          'collection_scheduled',
        ],
      )
      .select(
        _wholesaleReceivingSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This collection could not be updated.',
    );
  }

  return WholesaleReceivingBatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// MARK PRODUCE RECEIVED AT HPJ
// =====================================================

Future<WholesaleReceivingBatch> markWholesaleBatchReceived({
  required WholesaleReceivingBatch batch,
  required double receivedQuantity,
}) async {
  await requireAdminAccess();

  if (!batch.isCollected) {
    throw Exception(
      'Mark this produce as collected before receiving it.',
    );
  }

  if (receivedQuantity <= 0 || receivedQuantity > batch.scheduledQuantity) {
    throw Exception(
      'Enter a valid quantity received.',
    );
  }

  if (batch.collectedQuantity > 0 &&
      receivedQuantity > batch.collectedQuantity) {
    throw Exception(
      'Received quantity cannot exceed the quantity collected.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_receiving_batches',
      )
      .update({
        'received_quantity': receivedQuantity,
        'status': 'received',
      })
      .eq(
        'id',
        batch.id,
      )
      .eq(
        'status',
        'collected',
      )
      .select(
        _wholesaleReceivingSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This batch could not be marked received.',
    );
  }

  return WholesaleReceivingBatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// QUALITY INSPECTION
// =====================================================

Future<WholesaleReceivingBatch> inspectWholesaleReceivingBatch({
  required WholesaleReceivingBatch batch,
  required double acceptedQuantity,
  required double rejectedQuantity,
  String qualityGrade = '',
  String rejectionReason = '',
  double? farmerUnitCost,
  String? notes,
}) async {
  await requireAdminAccess();

  if (!batch.isReceived) {
    throw Exception(
      'Receive the produce before completing quality inspection.',
    );
  }

  if (acceptedQuantity < 0 || rejectedQuantity < 0) {
    throw Exception(
      'Accepted and rejected quantities cannot be negative.',
    );
  }

  if (acceptedQuantity + rejectedQuantity > batch.receivedQuantity) {
    throw Exception(
      'Accepted plus rejected quantity cannot exceed the amount received.',
    );
  }

  if (rejectedQuantity > 0 && rejectionReason.trim().isEmpty) {
    throw Exception(
      'Enter a reason for rejected produce.',
    );
  }

  if (farmerUnitCost != null &&
      (farmerUnitCost < 0 ||
          farmerUnitCost.isNaN ||
          farmerUnitCost.isInfinite)) {
    throw Exception(
      'Enter a valid farmer unit cost.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_receiving_batches',
      )
      .update({
        'accepted_quantity': acceptedQuantity,
        'rejected_quantity': rejectedQuantity,
        'quality_grade':
            qualityGrade.trim().isEmpty ? null : qualityGrade.trim(),
        'rejection_reason': rejectionReason.trim(),
        'farmer_unit_cost': farmerUnitCost ?? batch.farmerUnitCost,
        if (notes != null) 'notes': notes.trim(),
        'status': 'inspected',
      })
      .eq(
        'id',
        batch.id,
      )
      .eq(
        'status',
        'received',
      )
      .select(
        _wholesaleReceivingSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'This receiving batch could not be inspected.',
    );
  }

  return WholesaleReceivingBatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// COMPLETE RECEIVING BATCH
// =====================================================

Future<WholesaleReceivingBatch> completeWholesaleReceivingBatch(
  WholesaleReceivingBatch batch,
) async {
  await requireAdminAccess();

  if (!batch.isInspected) {
    throw Exception(
      'Complete quality inspection before closing this batch.',
    );
  }

  try {
    final response = await supabase.rpc(
      'admin_complete_wholesale_receiving_batch',
      params: {
        'p_receiving_batch_id': batch.id,
      },
    );

    Map<String, dynamic>? row;

    if (response is Map) {
      row = Map<String, dynamic>.from(response);
    } else if (response is List && response.isNotEmpty) {
      final first = response.first;
      if (first is Map) {
        row = Map<String, dynamic>.from(first);
      }
    }

    if (row == null || row.isEmpty) {
      throw Exception(
        'This receiving batch could not be completed.',
      );
    }

    return WholesaleReceivingBatch.fromSupabase(row);
  } catch (error) {
    farmDebugLog(
      'Wholesale receiving completion failed for ${batch.id}: $error',
    );
    rethrow;
  }
}

// =====================================================
// CANCEL COLLECTION PLAN
//
// Only allowed before physical collection begins.
// History is retained; nothing is deleted.
// =====================================================

Future<void> cancelWholesaleReceivingBatch(
  WholesaleReceivingBatch batch, {
  String notes = '',
}) async {
  await requireAdminAccess();

  if (!batch.isPlanned && !batch.isCollectionScheduled) {
    throw Exception(
      'A batch cannot be cancelled after collection has started.',
    );
  }

  await supabase
      .from(
        'wholesale_receiving_batches',
      )
      .update({
        'status': 'cancelled',
        'notes': notes.trim().isEmpty ? batch.notes : notes.trim(),
      })
      .eq(
        'id',
        batch.id,
      )
      .inFilter(
        'status',
        [
          'planned',
          'collection_scheduled',
        ],
      );
}
