// =====================================================
// CREATE FULFILMENT
//
// Database RPC prevents duplicates and automatically
// copies all wholesale request items.
// =====================================================

Future<WholesaleFulfillment> createWholesaleFulfillment(
  WholesaleOrderRequest request,
) async {
  await requireAdminAccess();

  if (request.status != 'approved') {
    throw Exception(
      'Approve the wholesale request before creating fulfilment.',
    );
  }

  final response = await supabase.rpc(
    'admin_create_wholesale_fulfillment',
    params: {
      'p_request_id': request.id,
    },
  );

  final fulfillmentId = response?.toString().trim() ?? '';

  if (fulfillmentId.isEmpty) {
    throw Exception(
      'The wholesale fulfilment could not be created.',
    );
  }

  final fulfillment = await fetchWholesaleFulfillmentForRequest(
    request.id,
  );

  if (fulfillment == null) {
    throw Exception(
      'Fulfilment was created but could not be loaded.',
    );
  }

  return fulfillment;
}

// =====================================================
// UPDATE FULFILMENT STATUS
// =====================================================

Future<WholesaleFulfillment> updateWholesaleFulfillmentStatus({
  required WholesaleFulfillment fulfillment,
  required String status,
  String? preparationNotes,
  String? packingNotes,
}) async {
  await requireAdminAccess();

  final cleanStatus = status.trim().toLowerCase();

  if (!_wholesaleFulfillmentStatuses.contains(cleanStatus)) {
    throw Exception(
      'Invalid wholesale fulfilment status.',
    );
  }

  if (fulfillment.isCancelled) {
    throw Exception(
      'This fulfilment has been cancelled.',
    );
  }

  if (cleanStatus == 'ready_for_dispatch' &&
      !fulfillment.allItemsAccountedFor) {
    throw Exception(
      'Every item must be packed, marked short, or removed before dispatch.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_fulfillments',
      )
      .update({
        'status': cleanStatus,
        if (preparationNotes != null)
          'preparation_notes': preparationNotes.trim(),
        if (packingNotes != null) 'packing_notes': packingNotes.trim(),
      })
      .eq(
        'id',
        fulfillment.id,
      )
      .select(
        _wholesaleFulfillmentSelectFields,
      )
      .single();

  return WholesaleFulfillment.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

