  await supabase.rpc(
    'admin_reserve_warehouse_stock_for_fulfillment',
    params: {
      'p_fulfillment_id': fulfillment.id,
    },
  );
}


// =====================================================
// GENERIC FULFILMENT ITEM UPDATE
// =====================================================

Future<WholesaleFulfillmentItem> updateWholesaleFulfillmentItem({
  required WholesaleFulfillmentItem item,
  required String status,
  required double packedQuantity,
  required double shortageQuantity,
  String substitutionNote = '',
  String packingNote = '',
}) async {
  await requireAdminAccess();

  final cleanStatus =
      status.trim().toLowerCase();

  if (!_wholesaleFulfillmentItemStatuses
      .contains(cleanStatus)) {
    throw Exception(
      'Invalid packing item status.',
    );
  }

  if (packedQuantity < 0 ||
      packedQuantity.isNaN ||
      packedQuantity.isInfinite) {
    throw Exception(
      'Enter a valid packed quantity.',
    );
  }

  if (shortageQuantity < 0 ||
      shortageQuantity.isNaN ||
      shortageQuantity.isInfinite) {
    throw Exception(
      'Enter a valid shortage quantity.',
    );
  }

  if (packedQuantity > item.orderedQuantity) {
    throw Exception(
      'Packed quantity cannot exceed the ordered quantity.',
    );
  }

  if (packedQuantity + shortageQuantity >
      item.orderedQuantity) {
    throw Exception(
      'Packed plus shortage quantity cannot exceed the ordered quantity.',
    );
  }

  if (cleanStatus == 'packed' &&
      (packedQuantity - item.orderedQuantity)
              .abs() >
          0.001) {
    throw Exception(
      'A fully packed line must equal the ordered quantity.',
    );
  }

  if (cleanStatus == 'short') {
    if (shortageQuantity <= 0) {
      throw Exception(
        'Enter the shortage quantity.',
      );
    }

    if ((packedQuantity +
                    shortageQuantity -
                    item.orderedQuantity)
                .abs() >
            0.001) {
      throw Exception(
        'Packed plus shortage quantity must equal the ordered quantity.',
      );
    }
  }

  // Final packing states must go through the warehouse RPC.
  // It updates the fulfilment line AND warehouse lots/reservations
  // in one database transaction.
  if (cleanStatus == 'packed' ||
      cleanStatus == 'short' ||
      cleanStatus == 'removed') {
    final response = await supabase.rpc(
      'admin_finalize_wholesale_fulfillment_item_inventory',
      params: {
        'p_item_id': item.id,
        'p_status': cleanStatus,
        'p_packed_quantity': packedQuantity,
        'p_shortage_quantity':
            shortageQuantity,
        'p_substitution_note':
            substitutionNote.trim(),
        'p_packing_note':
            packingNote.trim(),
      },
    );

    if (response is! Map) {
      throw Exception(
        'The warehouse packing update completed but HPJ could not reload the item.',
      );
    }

    return WholesaleFulfillmentItem.fromSupabase(
      Map<String, dynamic>.from(
        response,
      ),
    );
  }

  // Non-final states such as "preparing" do not issue stock.
  final response = await supabase
      .from(
        'wholesale_fulfillment_items',
      )
      .update({
        'status': cleanStatus,
        'packed_quantity':
            packedQuantity,
        'shortage_quantity':
            shortageQuantity,
        'substitution_note':
            substitutionNote.trim(),
        'packing_note':
            packingNote.trim(),
      })
      .eq(
        'id',
        item.id,
      )
      .select(
        _wholesaleFulfillmentItemSelectFields,
      )
      .single();

  return WholesaleFulfillmentItem.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// MARK ITEM PREPARING
// =====================================================

Future<WholesaleFulfillmentItem> markWholesaleFulfillmentItemPreparing(
  WholesaleFulfillmentItem item,
) async {
  return updateWholesaleFulfillmentItem(
    item: item,
    status: 'preparing',
    packedQuantity: item.packedQuantity,
    shortageQuantity: item.shortageQuantity,
    substitutionNote: item.substitutionNote,
    packingNote: item.packingNote,
  );
}

// =====================================================
// MARK ITEM FULLY PACKED
// =====================================================

Future<WholesaleFulfillmentItem> markWholesaleFulfillmentItemPacked({
  required WholesaleFulfillmentItem item,
  String packingNote = '',
}) async {
  return updateWholesaleFulfillmentItem(
    item: item,
    status: 'packed',
    packedQuantity: item.orderedQuantity,
    shortageQuantity: 0,
    substitutionNote: item.substitutionNote,
    packingNote: packingNote,
  );
}

// =====================================================
// MARK ITEM SHORT
// Example:
// Ordered 80 lb
// Packed 74 lb
// Shortage 6 lb
// =====================================================

Future<WholesaleFulfillmentItem> markWholesaleFulfillmentItemShort({
  required WholesaleFulfillmentItem item,
  required double packedQuantity,
  required double shortageQuantity,
  String substitutionNote = '',
  String packingNote = '',
}) async {
  if (shortageQuantity <= 0) {
    throw Exception(
      'Enter the shortage quantity.',
    );
  }

  return updateWholesaleFulfillmentItem(
    item: item,
    status: 'short',
    packedQuantity: packedQuantity,
    shortageQuantity: shortageQuantity,
    substitutionNote: substitutionNote,
    packingNote: packingNote,
  );
}

// =====================================================
// REMOVE LINE FROM FULFILMENT
//
// We do not delete it. The line remains in history.
// =====================================================

Future<WholesaleFulfillmentItem> removeWholesaleFulfillmentItem({
  required WholesaleFulfillmentItem item,
  required String reason,
}) async {
  final cleanReason = reason.trim();

  if (cleanReason.isEmpty) {
    throw Exception(
      'Enter the reason this line is being removed.',
    );
  }

  return updateWholesaleFulfillmentItem(
    item: item,
    status: 'removed',
    packedQuantity: 0,
    shortageQuantity: 0,
    substitutionNote: cleanReason,
    packingNote: item.packingNote,
  );
}

// =====================================================
// START PREPARATION
// =====================================================

Future<WholesaleFulfillment> startWholesalePreparation(
  WholesaleFulfillment fulfillment, {
  String notes = '',
}) async {
  if (!fulfillment.isWaitingStock && !fulfillment.isReadyToPrepare) {
    throw Exception(
      'This wholesale order is not waiting to begin preparation.',
    );
  }

  return updateWholesaleFulfillmentStatus(
    fulfillment: fulfillment,
    status: 'preparing',
    preparationNotes: notes,
  );
}

// =====================================================
// START PACKING
// =====================================================

Future<WholesaleFulfillment> startWholesalePacking(
  WholesaleFulfillment fulfillment, {
  String notes = '',
}) async {
  if (!fulfillment.isPreparing) {
    throw Exception(
      'Start preparation before packing.',
    );
  }

  return updateWholesaleFulfillmentStatus(
    fulfillment: fulfillment,
    status: 'packing',
    packingNotes: notes,
  );
}

// =====================================================
// READY FOR DISPATCH
// =====================================================

Future<WholesaleFulfillment> markWholesaleFulfillmentReadyForDispatch(
  WholesaleFulfillment fulfillment,
) async {
  if (!fulfillment.isPacking) {
    throw Exception(
      'The order must be in packing before it can be marked ready for dispatch.',
    );
  }

  if (!fulfillment.allItemsAccountedFor) {
    throw Exception(
      'Every item must be packed, marked short, or removed first.',
    );
  }

  return updateWholesaleFulfillmentStatus(
    fulfillment: fulfillment,
    status: 'ready_for_dispatch',
  );
}
// =====================================================
// WHOLESALE DISPATCH SERVICES
// =====================================================

// =====================================================
// FETCH ADMIN DISPATCHES
// =====================================================

Future<List<WholesaleDispatch>> fetchAdminWholesaleDispatches({
  String? status,
  String? fulfillmentId,
  String? requestId,
  String? driverId,
  bool includeCancelled = false,
}) async {
  await requireAdminAccess();

  final cleanStatus = status?.trim().toLowerCase();

  if (cleanStatus != null &&
      cleanStatus.isNotEmpty &&
      !_wholesaleDispatchStatuses.contains(
        cleanStatus,
      )) {
    throw Exception(
      'Invalid wholesale dispatch status.',
    );
  }

  dynamic query = supabase
      .from(
        'wholesale_dispatches',
      )
      .select(
        _wholesaleDispatchSelectFields,
      );

  if (cleanStatus != null && cleanStatus.isNotEmpty) {
    query = query.eq(
      'status',
      cleanStatus,
    );
  }

  final cleanFulfillment = fulfillmentId?.trim() ?? '';

  if (cleanFulfillment.isNotEmpty) {
    query = query.eq(
      'fulfillment_id',
      cleanFulfillment,
    );
  }

  final cleanRequest = requestId?.trim() ?? '';

  if (cleanRequest.isNotEmpty) {
    query = query.eq(
      'request_id',
      cleanRequest,
    );
  }

  final cleanDriver = driverId?.trim() ?? '';

  if (cleanDriver.isNotEmpty) {
    query = query.eq(
      'assigned_driver_id',
      cleanDriver,
    );
  }

  if (!includeCancelled && (cleanStatus == null || cleanStatus.isEmpty)) {
    query = query.neq(
      'status',
      'cancelled',
    );
  }

  final response = await query.order(
    'created_at',
    ascending: false,
  );

  return (response as List)
      .map(
        (item) => WholesaleDispatch.fromSupabase(
          Map<String, dynamic>.from(
            item as Map,
          ),
        ),
      )
      .toList();
}

// =====================================================
// FETCH DISPATCH FOR ONE FULFILMENT
// =====================================================

Future<WholesaleDispatch?> fetchWholesaleDispatchForFulfillment(
  String fulfillmentId,
) async {
  await requireAdminAccess();

  final cleanId = fulfillmentId.trim();

  if (cleanId.isEmpty) {
    return null;
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .eq(
        'fulfillment_id',
        cleanId,
      )
      .neq(
        'status',
        'cancelled',
      )
      .maybeSingle();

  if (response == null) {
    return null;
  }

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// CREATE DISPATCH
// =====================================================

Future<WholesaleDispatch> createWholesaleDispatch({
  required WholesaleFulfillment fulfillment,
  String dispatchMethod = 'hpj_delivery',
  DateTime? scheduledFor,
}) async {
  await requireAdminAccess();

  if (!fulfillment.isReadyForDispatch) {
    throw Exception(
      'Complete packing before creating dispatch.',
    );
  }

  final cleanMethod = dispatchMethod.trim().toLowerCase();

  if (!_wholesaleDispatchMethods.contains(
    cleanMethod,
  )) {
    throw Exception(
      'Invalid dispatch method.',
    );
  }

  final response = await supabase.rpc(
    'admin_create_wholesale_dispatch',
    params: {
      'p_fulfillment_id': fulfillment.id,
      'p_dispatch_method': cleanMethod,
      'p_scheduled_for': scheduledFor?.toUtc().toIso8601String(),
    },
  );

  final dispatchId = response?.toString().trim() ?? '';

  if (dispatchId.isEmpty) {
    throw Exception(
      'Dispatch could not be created.',
    );
  }

  final dispatch = await fetchWholesaleDispatchForFulfillment(
    fulfillment.id,
  );

  if (dispatch == null) {
    throw Exception(
      'Dispatch was created but could not be loaded.',
    );
  }

  return dispatch;
}

// =====================================================
// UPDATE DISPATCH PLAN
// =====================================================

Future<WholesaleDispatch> updateWholesaleDispatchPlan({
  required WholesaleDispatch dispatch,
  DateTime? scheduledFor,
  String? adminNotes,
}) async {
  await requireAdminAccess();

  if (!dispatch.isPlanned &&
      !dispatch.isAssigned &&
      !dispatch.isReadyForPickup) {
    throw Exception(
      'This dispatch can no longer be rescheduled.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .update({
        'scheduled_for': scheduledFor?.toUtc().toIso8601String(),
        if (adminNotes != null) 'admin_notes': adminNotes.trim(),
      })
      .eq(
        'id',
        dispatch.id,
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .single();

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// ASSIGN DRIVER
//
// PLANNED → ASSIGNED
// =====================================================

Future<WholesaleDispatch> assignWholesaleDispatchDriver({
  required WholesaleDispatch dispatch,
  required String driverUserId,
  DateTime? scheduledFor,
  String adminNotes = '',
}) async {
  await requireAdminAccess();

  if (!dispatch.isHpjDelivery) {
    throw Exception(
      'Drivers can only be assigned to HPJ Delivery.',
    );
  }

  if (!dispatch.isPlanned) {
    throw Exception(
      'Only a planned dispatch can be assigned.',
    );
  }

  final cleanDriverId = driverUserId.trim();

  if (cleanDriverId.isEmpty) {
    throw Exception(
      'Select a driver.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .update({
        'assigned_driver_id': cleanDriverId,
        'status': 'assigned',
        if (scheduledFor != null)
          'scheduled_for': scheduledFor.toUtc().toIso8601String(),
        'admin_notes': adminNotes.trim(),
      })
      .eq(
        'id',
        dispatch.id,
      )
      .eq(
        'status',
        'planned',
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .maybeSingle();

  if (response == null) {
    throw Exception(
      'Dispatch assignment could not be updated.',
    );
  }

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

