// =====================================================
// OUT FOR DELIVERY
//
// ASSIGNED → OUT FOR DELIVERY
// =====================================================

Future<WholesaleDispatch> markWholesaleDispatchOutForDelivery(
  WholesaleDispatch dispatch, {
  String driverNotes = '',
}) async {
  await requireAdminAccess();

  if (!dispatch.isHpjDelivery) {
    throw Exception(
      'This dispatch is not an HPJ delivery.',
    );
  }

  if (!dispatch.isAssigned) {
    throw Exception(
      'Assign the delivery before dispatching it.',
    );
  }

  if ((dispatch.assignedDriverId ?? '').trim().isEmpty) {
    throw Exception(
      'Assign a driver first.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .update({
        'status': 'out_for_delivery',
        'driver_notes': driverNotes.trim(),
      })
      .eq(
        'id',
        dispatch.id,
      )
      .eq(
        'status',
        'assigned',
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .single();

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// COMPLETE HPJ DELIVERY
//
// OUT FOR DELIVERY → DELIVERED
// =====================================================

Future<WholesaleDispatch> completeWholesaleDelivery({
  required WholesaleDispatch dispatch,
  required String recipientName,
  String proofNote = '',
  String proofPhotoPath = '',
  double? latitude,
  double? longitude,
  String driverNotes = '',
}) async {
  await requireAdminAccess();

  if (!dispatch.isHpjDelivery) {
    throw Exception(
      'This dispatch is not an HPJ delivery.',
    );
  }

  if (!dispatch.isOutForDelivery) {
    throw Exception(
      'The order must be out for delivery first.',
    );
  }

  final cleanRecipient = recipientName.trim();

  if (cleanRecipient.isEmpty) {
    throw Exception(
      'Enter the name of the person who received the order.',
    );
  }

  if (latitude != null && (latitude < -90 || latitude > 90)) {
    throw Exception(
      'Invalid delivery latitude.',
    );
  }

  if (longitude != null && (longitude < -180 || longitude > 180)) {
    throw Exception(
      'Invalid delivery longitude.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .update({
        'status': 'delivered',
        'recipient_name': cleanRecipient,
        'proof_note': proofNote.trim(),
        'proof_photo_path': proofPhotoPath.trim(),
        'delivery_latitude': latitude,
        'delivery_longitude': longitude,
        'driver_notes': driverNotes.trim(),
      })
      .eq(
        'id',
        dispatch.id,
      )
      .eq(
        'status',
        'out_for_delivery',
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .single();

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// COMPLETE BUSINESS COLLECTION
//
// READY FOR PICKUP → COLLECTED
// =====================================================

Future<WholesaleDispatch> completeWholesaleBusinessCollection({
  required WholesaleDispatch dispatch,
  required String recipientName,
  String proofNote = '',
  String proofPhotoPath = '',
  String adminNotes = '',
}) async {
  await requireAdminAccess();

  if (!dispatch.isBusinessCollection) {
    throw Exception(
      'This dispatch is not a business collection.',
    );
  }

  if (!dispatch.isReadyForPickup) {
    throw Exception(
      'Mark the order ready for pickup first.',
    );
  }

  final cleanRecipient = recipientName.trim();

  if (cleanRecipient.isEmpty) {
    throw Exception(
      'Enter the name of the person collecting the order.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .update({
        'status': 'collected',
        'recipient_name': cleanRecipient,
        'proof_note': proofNote.trim(),
        'proof_photo_path': proofPhotoPath.trim(),
        'admin_notes': adminNotes.trim(),
      })
      .eq(
        'id',
        dispatch.id,
      )
      .eq(
        'status',
        'ready_for_pickup',
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .single();

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}

// =====================================================
// CANCEL DISPATCH
//
// Completed deliveries / collections cannot be
// cancelled.
// =====================================================

Future<WholesaleDispatch> cancelWholesaleDispatch({
  required WholesaleDispatch dispatch,
  String reason = '',
}) async {
  await requireAdminAccess();

  if (dispatch.isComplete) {
    throw Exception(
      'A completed dispatch cannot be cancelled.',
    );
  }

  if (dispatch.isCancelled) {
    throw Exception(
      'This dispatch is already cancelled.',
    );
  }

  final response = await supabase
      .from(
        'wholesale_dispatches',
      )
      .update({
        'status': 'cancelled',
        'admin_notes': reason.trim(),
      })
      .eq(
        'id',
        dispatch.id,
      )
      .select(
        _wholesaleDispatchSelectFields,
      )
      .single();

  return WholesaleDispatch.fromSupabase(
    Map<String, dynamic>.from(
      response as Map,
    ),
  );
}
