// =====================================================
// BUSINESS PORTAL — MY ISSUED WHOLESALE INVOICES
// RLS remains the final security boundary. This app-side
// check also keeps the user experience clear and predictable.
// =====================================================

Future<List<WholesaleInvoice>> fetchMyWholesaleInvoices({
  bool includePaid = true,
}) async {
  final user = supabase.auth.currentUser;

  if (user == null) {
    return const <WholesaleInvoice>[];
  }

  final account = await fetchCurrentBusinessAccount();

  if (account == null) {
    throw Exception(
      'A wholesale business account is required to view invoices.',
    );
  }

  if (!account.isApproved) {
    throw Exception(
      'Your wholesale account must be approved before viewing invoices.',
    );
  }

  dynamic query = supabase
      .from('wholesale_invoices')
      .select(_businessPortalInvoiceSelectFields)
      .eq('business_account_id', account.id)
      .eq('invoice_status', 'issued');

  if (!includePaid) {
    query = query.neq('payment_status', 'paid');
  }

  final response = await query.order('created_at', ascending: false).limit(100);

  return (response as List)
      .map(
        (item) => WholesaleInvoice.fromSupabase(
          Map<String, dynamic>.from(item as Map),
        ),
      )
      .toList();
}

// =====================================================
// PHASE 3O — BUSINESS PAYMENT CONFIRMATION SERVICES
// =====================================================

// =====================================================
// PHASE 3P — BUSINESS ACCOUNT STATEMENT SNAPSHOT
// =====================================================

class _WholesaleAccountStatementSnapshot {
  final BusinessAccount account;
  final List<WholesaleInvoice> invoices;

  const _WholesaleAccountStatementSnapshot({
    required this.account,
    required this.invoices,
  });

  WholesaleAccountAging get aging =>
      WholesaleAccountAging.fromInvoices(invoices);

  double get outstanding => aging.total;

  double get availableCredit {
    if (!account.hasActiveWholesaleCredit ||
        account.wholesaleCreditLimit <= 0) {
      return 0;
    }

    final available = account.wholesaleCreditLimit - outstanding;
    return available < 0 ? 0 : available;
  }
}

Future<_WholesaleAccountStatementSnapshot>
    fetchMyWholesaleAccountStatement() async {
  final account = await fetchCurrentBusinessAccount();

  if (account == null || !account.isApproved) {
    throw Exception(
      'An approved wholesale account is required to view account statements.',
    );
  }

  final invoices = await fetchMyWholesaleInvoices();

  return _WholesaleAccountStatementSnapshot(
    account: account,
    invoices: invoices,
  );
}

// =====================================================
// PHASE 3Q — WHOLESALE ORDERING CONTROL SERVICE
// =====================================================

Future<WholesaleOrderingControl> fetchWholesaleOrderingControl({
  BusinessAccount? account,
  double estimatedTotal = 0,
}) async {
  final currentUser = supabase.auth.currentUser;
  if (currentUser == null) {
    throw Exception('Please sign in to check wholesale ordering status.');
  }

  final resolvedAccount = account ?? await fetchCurrentBusinessAccount();
  if (resolvedAccount == null) {
    throw Exception('A wholesale business account is required.');
  }

  if (estimatedTotal < 0 || estimatedTotal.isNaN || estimatedTotal.isInfinite) {
    throw Exception('Invalid wholesale request estimate.');
  }

  final response = await supabase.rpc(
    'wholesale_ordering_control_snapshot',
    params: {
      'p_business_account_id': resolvedAccount.id,
      'p_estimated_total': estimatedTotal,
    },
  );

  if (response is List && response.isNotEmpty) {
    return WholesaleOrderingControl.fromSupabase(
      Map<String, dynamic>.from(response.first as Map),
    );
  }

  if (response is Map) {
    return WholesaleOrderingControl.fromSupabase(
      Map<String, dynamic>.from(response),
    );
  }

  throw Exception('Wholesale ordering status could not be loaded.');
}

Future<List<WholesalePaymentSubmission>> fetchMyWholesalePaymentSubmissions({
  String? invoiceId,
}) async {
