Future<String> uploadWholesalePaymentProof({
  required WholesaleInvoice invoice,
  required XFile file,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Please sign in before uploading payment proof.');
  }

  final account = await fetchCurrentBusinessAccount();
  if (account == null || !account.isApproved) {
    throw Exception('An approved wholesale account is required.');
  }

  if (invoice.businessAccountId != account.id) {
    throw Exception('This invoice does not belong to your business account.');
  }

  final bytes = await file.readAsBytes();
  if (bytes.isEmpty) {
    throw Exception('Choose a valid payment proof image.');
  }

  const maxBytes = 6 * 1024 * 1024;
  if (bytes.length > maxBytes) {
    throw Exception('Use a payment proof image smaller than 6 MB.');
  }

  final lower = file.name.toLowerCase();
  final extension = lower.endsWith('.png')
      ? 'png'
      : lower.endsWith('.webp')
          ? 'webp'
          : 'jpg';

  final contentType = extension == 'png'
      ? 'image/png'
      : extension == 'webp'
          ? 'image/webp'
          : 'image/jpeg';

  final safeInvoiceId = invoice.id.replaceAll(
    RegExp(r'[^A-Za-z0-9_-]'),
    '',
  );

  final path = '${user.id}/$safeInvoiceId/'
      '${DateTime.now().millisecondsSinceEpoch}.$extension';

  await supabase.storage.from('wholesale-payment-proofs').uploadBinary(
        path,
        bytes,
        fileOptions: FileOptions(
          contentType: contentType,
          upsert: false,
        ),
      );

  return path;
}

Future<void> submitWholesalePaymentConfirmation({
  required WholesaleInvoice invoice,
  required double amount,
  required String paymentMethod,
  required String proofPath,
  String paymentReference = '',
  String note = '',
}) async {
  final operationBoundary =
      captureHpjPrivateOperationBoundary();

  final user = supabase.auth.currentUser;
  if (user == null || operationBoundary.userId == null) {
    throw Exception('Please sign in before submitting payment confirmation.');
  }

  if (!invoice.isIssued || invoice.isPaid || invoice.isVoid) {
    throw Exception('This invoice is not accepting payment confirmations.');
  }
  if (amount <= 0 || amount.isNaN || amount.isInfinite) {
    throw Exception('Enter a valid payment amount.');
  }

  final method = paymentMethod.trim().toLowerCase();
  if (!_wholesaleInvoicePaymentMethods.contains(method)) {
    throw Exception('Select a valid payment method.');
  }

  final cleanProof = proofPath.trim();
  if (cleanProof.isEmpty) {
    throw Exception('Upload payment proof before submitting.');
  }

  final mutationLease = acquireHpjPrivateMutation(
    'wholesale-payment:${invoice.id}',
    expectedBoundary: operationBoundary,
  );

  try {
    mutationLease.ensureCurrent();

    final idempotencyKey =
        newHpjIdempotencyKey('wholesale-payment:${invoice.id}');

    await supabase.rpc(
      'business_submit_wholesale_payment_confirmation_idempotent',
      params: {
        'p_invoice_id': invoice.id,
        'p_amount': amount,
        'p_payment_method': method,
        'p_payment_reference': paymentReference.trim(),
        'p_proof_path': cleanProof,
        'p_note': note.trim(),
        'p_idempotency_key': idempotencyKey,
      },
    );

    mutationLease.ensureCurrent();

    await createAdminNotification(
      title: 'Wholesale payment confirmation',
      message:
          '${invoice.businessName.trim().isEmpty ? 'A wholesale business' : invoice.businessName} submitted ${formatJmd(amount)} for ${invoice.invoiceNumber}.',
      type: 'wholesale',
      actionType: 'admin_wholesale_payment',
      actionId: invoice.id,
      dedupeKey:
          'admin-wholesale-payment:${invoice.id}:${paymentReference.trim()}',
    );

    mutationLease.ensureCurrent();
  } finally {
    mutationLease.release();
  }
}
Future<void> cancelWholesalePaymentConfirmation(
  WholesalePaymentSubmission submission,
) async {
  if (!submission.isPending) {
    throw Exception('Only a pending payment confirmation can be cancelled.');
  }

  await supabase.rpc(
    'business_cancel_wholesale_payment_confirmation',
    params: {
      'p_submission_id': submission.id,
    },
  );
}

Future<List<WholesalePaymentSubmission>> fetchAdminWholesalePaymentSubmissions({
  String? status,
}) async {
  await requireAdminAccess();

  final cleanStatus = status?.trim().toLowerCase();
  if (cleanStatus != null &&
      cleanStatus.isNotEmpty &&
      !_wholesalePaymentSubmissionStatuses.contains(cleanStatus)) {
    throw Exception('Invalid payment confirmation status.');
  }

  dynamic query = supabase
      .from('wholesale_payment_submissions')
      .select(_wholesalePaymentSubmissionSelectFields);

  if (cleanStatus != null && cleanStatus.isNotEmpty) {
    query = query.eq('status', cleanStatus);
  }

  final response = await query.order('created_at', ascending: false).limit(200);

  return (response as List)
      .map(
        (item) => WholesalePaymentSubmission.fromSupabase(
          Map<String, dynamic>.from(item as Map),
        ),
      )
      .toList();
}

Future<String> getWholesalePaymentProofSignedUrl(
  String proofPath,
) async {
  final cleanPath = proofPath.trim();
  if (cleanPath.isEmpty) {
    throw Exception('No payment proof image is available.');
  }

  return supabase.storage
      .from('wholesale-payment-proofs')
      .createSignedUrl(cleanPath, 900);
}


Future<String?> _wholesaleNotificationRequestIdForInvoice(
  String invoiceId,
) async {
  final cleanInvoiceId = invoiceId.trim();
  if (cleanInvoiceId.isEmpty) return null;

  try {
    final invoice = await fetchWholesaleInvoiceById(cleanInvoiceId);
    final requestId = invoice.requestId.trim();
    return requestId.isEmpty ? null : requestId;
  } catch (error) {
    farmDebugLog(
      'Wholesale notification request lookup skipped for '
      '$cleanInvoiceId: $error',
    );
    return null;
  }
}

Future<void> approveWholesalePaymentConfirmation(
  WholesalePaymentSubmission submission,
) async {
  await requireAdminAccess();

  if (!submission.isPending) {
    throw Exception('This payment confirmation has already been reviewed.');
  }

  await supabase.rpc(
    'admin_approve_wholesale_payment_confirmation',
    params: {
      'p_submission_id': submission.id,
      'p_admin_note': '',
    },
  );

  final requestId =
      await _wholesaleNotificationRequestIdForInvoice(
    submission.invoiceId,
  );

  await createFarmNotification(
    title: 'Wholesale payment approved',
    message:
        '${submission.formattedAmount} was approved for ${submission.invoiceNumber.isEmpty ? 'your wholesale invoice' : submission.invoiceNumber}.',
    type: 'wholesale',
    userId: submission.submittedBy,
    actionType: 'wholesale_order',
    actionId: requestId,
    dedupeKey: 'wholesale-payment-approved:${submission.id}',
  );
}

Future<void> rejectWholesalePaymentConfirmation({
  required WholesalePaymentSubmission submission,
  required String reason,
}) async {
  await requireAdminAccess();

  if (!submission.isPending) {
    throw Exception('This payment confirmation has already been reviewed.');
  }

  final cleanReason = reason.trim();
  if (cleanReason.isEmpty) {
    throw Exception(
        'Enter a reason before rejecting the payment confirmation.');
  }

  await supabase.rpc(
    'admin_reject_wholesale_payment_confirmation',
    params: {
      'p_submission_id': submission.id,
      'p_admin_note': cleanReason,
    },
  );

  final requestId =
      await _wholesaleNotificationRequestIdForInvoice(
    submission.invoiceId,
  );

  await createFarmNotification(
    title: 'Wholesale payment needs attention',
    message:
        '${submission.invoiceNumber.isEmpty ? 'Your wholesale payment confirmation' : 'Payment confirmation for ${submission.invoiceNumber}'} needs attention. $cleanReason',
    type: 'wholesale',
    userId: submission.submittedBy,
    actionType: 'wholesale_order',
    actionId: requestId,
    dedupeKey: 'wholesale-payment-review:${submission.id}:rejected',
  );
}

Future<List<WholesaleInvoice>> fetchAdminWholesaleInvoices({
  String? invoiceStatus,
  String? paymentStatus,
  String? businessAccountId,
}) async {
  await requireAdminAccess();

  final cleanInvoiceStatus = invoiceStatus?.trim().toLowerCase();

  final cleanPaymentStatus = paymentStatus?.trim().toLowerCase();

  if (cleanInvoiceStatus != null &&
      cleanInvoiceStatus.isNotEmpty &&
      !_wholesaleInvoiceStatuses.contains(
        cleanInvoiceStatus,
      )) {
    throw Exception(
      'Invalid invoice status.',
    );
  }

  if (cleanPaymentStatus != null &&
      cleanPaymentStatus.isNotEmpty &&
      !_wholesaleInvoicePaymentStatuses.contains(
        cleanPaymentStatus,
      )) {
    throw Exception(
      'Invalid invoice payment status.',
    );
  }

  dynamic query = supabase
      .from(
        'wholesale_invoices',
      )
      .select(
        _wholesaleInvoiceSelectFields,
      );

  if (cleanInvoiceStatus != null && cleanInvoiceStatus.isNotEmpty) {
    query = query.eq(
      'invoice_status',
      cleanInvoiceStatus,
    );
  }

  if (cleanPaymentStatus != null && cleanPaymentStatus.isNotEmpty) {
    query = query.eq(
      'payment_status',
      cleanPaymentStatus,
    );
  }

  final cleanBusinessId = businessAccountId?.trim() ?? '';

  if (cleanBusinessId.isNotEmpty) {
    query = query.eq(
      'business_account_id',
      cleanBusinessId,
    );
  }

  final response = await query.order(
    'created_at',
    ascending: false,
  );

  return (response as List)
      .map(
        (item) => WholesaleInvoice.fromSupabase(
          Map<String, dynamic>.from(
            item as Map,
          ),
        ),
      )
      .toList();
}

