// =====================================================
// FETCH INVOICE FOR REQUEST
// =====================================================

Future<WholesaleInvoice?> fetchWholesaleInvoiceForRequest(
  String requestId, {
  bool includeVoid = false,
}) async {
  await requireAdminAccess();

  final cleanId = requestId.trim();

  if (cleanId.isEmpty) {
    return null;
  }

  dynamic query = supabase
      .from(
        'wholesale_invoices',
      )
      .select(
        _wholesaleInvoiceSelectFields,
      )
      .eq(
        'request_id',
        cleanId,
      );

  if (!includeVoid) {
    query = query.neq(
      'invoice_status',
      'void',
    );
  }

  final response = await query
      .order(
        'created_at',
        ascending: false,
      )
      .limit(
        1,
      );

  final rows = response as List;

  if (rows.isEmpty) {
    return null;
  }

  return WholesaleInvoice.fromSupabase(
    Map<String, dynamic>.from(
      rows.first as Map,
    ),
  );
}

