Future<WholesaleInvoice> createWholesaleInvoice(
  WholesaleOrderRequest request,
) async {
  await requireAdminAccess();

  if (request.status != 'approved' && request.status != 'fulfilled') {
    throw Exception(
      'The wholesale request must be approved before invoicing.',
    );
  }

  final response = await supabase.rpc(
    'admin_create_wholesale_invoice',
    params: {
      'p_request_id': request.id,
    },
  );

  final invoiceId = response?.toString().trim() ?? '';

  if (invoiceId.isEmpty) {
    throw Exception(
      'Wholesale invoice could not be created.',
    );
  }

  return fetchWholesaleInvoiceById(
    invoiceId,
  );
}

// =====================================================
// UPDATE DRAFT INVOICE
// =====================================================

Future<WholesaleInvoice> updateWholesaleInvoiceDraft({
  required WholesaleInvoice invoice,
  double? deliveryFee,
  double? discountAmount,
  double? taxAmount,
  double? otherAmount,
  int? paymentTermsDays,
  String? billingAddress,
  String? billingParish,
  String? customerNote,
  String? internalNote,
}) async {
  await requireAdminAccess();

  if (!invoice.isDraft) {
    throw Exception(
      'Only a draft invoice can be edited.',
    );
  }

  bool invalidAmount(
    double? value,
  ) {
    return value != null && (value < 0 || value.isNaN || value.isInfinite);
  }

  if (invalidAmount(
        deliveryFee,
      ) ||
      invalidAmount(
        discountAmount,
      ) ||
      invalidAmount(
        taxAmount,
      ) ||
      invalidAmount(
        otherAmount,
      )) {
    throw Exception(
      'Invoice adjustments cannot be negative.',
    );
  }

  if (paymentTermsDays != null &&
      (paymentTermsDays < 0 || paymentTermsDays > 365)) {
    throw Exception(
      'Payment terms must be between 0 and 365 days.',
    );
  }

  final update = <String, dynamic>{
    if (deliveryFee != null) 'delivery_fee': deliveryFee,
    if (discountAmount != null) 'discount_amount': discountAmount,
    if (taxAmount != null) 'tax_amount': taxAmount,
    if (otherAmount != null) 'other_amount': otherAmount,
    if (paymentTermsDays != null) 'payment_terms_days': paymentTermsDays,
    if (billingAddress != null) 'billing_address': billingAddress.trim(),
    if (billingParish != null)
      'billing_parish': normalizeOptionalJamaicaParish(
            billingParish,
            fieldLabel: 'Billing parish',
          ) ??
          '',
    if (customerNote != null) 'customer_note': customerNote.trim(),
    if (internalNote != null) 'internal_note': internalNote.trim(),
  };

  if (update.isEmpty) {
    return invoice;
  }

  await supabase
      .from(
        'wholesale_invoices',
      )
      .update(
        update,
      )
      .eq(
        'id',
        invoice.id,
      )
      .eq(
        'invoice_status',
        'draft',
      );

  // Fetch again because the database trigger may have
  // recalculated totals after adjustment changes.
  return fetchWholesaleInvoiceById(
    invoice.id,
  );
}

// =====================================================
// ISSUE INVOICE
// =====================================================

Future<WholesaleInvoice> issueWholesaleInvoice(
  WholesaleInvoice invoice,
) async {
  await requireAdminAccess();

  if (!invoice.isDraft) {
    throw Exception(
      'Only a draft invoice can be issued.',
    );
  }

  if (invoice.totalAmount <= 0) {
    throw Exception(
      'Invoice total must be greater than zero.',
    );
  }

  await supabase
      .from(
        'wholesale_invoices',
      )
      .update({
        'invoice_status': 'issued',
      })
      .eq(
        'id',
        invoice.id,
      )
      .eq(
        'invoice_status',
        'draft',
      );

  return fetchWholesaleInvoiceById(
    invoice.id,
  );
}

// =====================================================
// RECORD PAYMENT
// =====================================================

Future<WholesaleInvoice> recordWholesaleInvoicePayment({
  required WholesaleInvoice invoice,
  required double amount,
  required String paymentMethod,
  String paymentReference = '',
  String paymentNote = '',
  DateTime? paidAt,
}) async {
  await requireAdminAccess();

  if (!invoice.isIssued) {
    throw Exception(
      'Issue the invoice before recording payment.',
    );
  }

  if (invoice.isPaid) {
    throw Exception(
      'This invoice is already fully paid.',
    );
  }

  if (amount <= 0 || amount.isNaN || amount.isInfinite) {
    throw Exception(
      'Enter a valid payment amount.',
    );
  }

  if (amount > invoice.amountDue + 0.01) {
    throw Exception(
      'Payment cannot exceed the outstanding balance.',
    );
  }

  final cleanMethod = paymentMethod.trim().toLowerCase();

  if (!_wholesaleInvoicePaymentMethods.contains(
    cleanMethod,
  )) {
    throw Exception(
      'Select a valid payment method.',
    );
  }

  await supabase.rpc(
    'admin_record_wholesale_invoice_payment',
    params: {
      'p_invoice_id': invoice.id,
      'p_amount': amount,
      'p_payment_method': cleanMethod,
      'p_payment_reference':
          paymentReference.trim().isEmpty ? null : paymentReference.trim(),
      'p_payment_note': paymentNote.trim().isEmpty ? null : paymentNote.trim(),
      'p_paid_at': (paidAt ?? DateTime.now()).toUtc().toIso8601String(),
    },
  );

  return fetchWholesaleInvoiceById(
    invoice.id,
  );
}

// =====================================================
// REVERSE PAYMENT
// =====================================================

Future<WholesaleInvoice> reverseWholesaleInvoicePayment({
  required WholesaleInvoice invoice,
  required WholesaleInvoicePayment payment,
  required String reason,
}) async {
  await requireAdminAccess();

  if (payment.isReversed) {
    throw Exception(
      'This payment has already been reversed.',
    );
  }

  final cleanReason = reason.trim();

  if (cleanReason.isEmpty) {
    throw Exception(
      'Enter a reason for reversing the payment.',
    );
  }

  await supabase.rpc(
    'admin_reverse_wholesale_invoice_payment',
    params: {
      'p_payment_id': payment.id,
      'p_reason': cleanReason,
    },
  );

  return fetchWholesaleInvoiceById(
    invoice.id,
  );
}

// =====================================================
// VOID INVOICE
// =====================================================

Future<WholesaleInvoice> voidWholesaleInvoice(
  WholesaleInvoice invoice,
) async {
  await requireAdminAccess();

  if (invoice.isVoid) {
    throw Exception(
      'This invoice is already void.',
    );
  }

  if (invoice.paidAmount > 0) {
    throw Exception(
      'Reverse all confirmed payments before voiding the invoice.',
    );
  }

  await supabase
      .from(
    'wholesale_invoices',
  )
      .update({
    'invoice_status': 'void',
  }).eq(
    'id',
    invoice.id,
  );

  return fetchWholesaleInvoiceById(
    invoice.id,
  );
}

Future<void> submitBusinessApplication({
  required String businessName,
  required String businessType,
  required String contactName,
  required String phone,
  required String whatsapp,
  required String address,
  required String parish,
  required String registrationNumber,
  required double expectedWeeklySpend,
  required List<String> preferredDeliveryDays,
}) async {
  if (!isLoggedIn || supabase.auth.currentUser == null) {
    throw Exception('Please sign in before submitting a business application.');
  }

  final existing = await fetchCurrentBusinessAccount();
  final settings = await fetchMarketplaceProgramSettings();

  // Closing applications blocks only NEW applicants. Existing applicants may
  // still update their saved details or respond to owner feedback.
  if (existing == null && !settings.wholesaleApplicationsEnabled) {
    throw Exception('Wholesale applications are temporarily paused.');
  }

  final cleanName = businessName.trim();
  final cleanContact = contactName.trim();
  final cleanPhone = phone.trim();

  if (cleanName.isEmpty ||
      cleanContact.isEmpty ||
      cleanPhone.isEmpty ||
      parish.trim().isEmpty) {
    throw Exception(
      'Business name, contact person, phone, and parish are required.',
    );
  }

  final cleanParish = requireJamaicaParish(
    parish,
    fieldLabel: 'Business parish',
  );

  await supabase.rpc(
    'upsert_business_application',
    params: {
      'p_business_name': cleanName,
      'p_business_type': businessType.trim(),
      'p_contact_name': cleanContact,
      'p_phone': cleanPhone,
      'p_whatsapp': whatsapp.trim(),
      'p_address': address.trim(),
      'p_parish': cleanParish,
      'p_registration_number': registrationNumber.trim(),
      'p_expected_weekly_spend': expectedWeeklySpend,
      'p_preferred_delivery_days': preferredDeliveryDays,
    },
  );

  final savedAccount = await fetchCurrentBusinessAccount();

  await createAdminNotification(
    title: existing == null
        ? 'New wholesale application'
        : 'Wholesale application updated',
    message: existing == null
        ? '$cleanName submitted a business shopper application.'
        : '$cleanName updated its business shopper details.',
    type: 'wholesale',
    actionType: 'admin_wholesale_application',
    actionId: savedAccount?.id,
    dedupeKey: savedAccount?.id == null
        ? null
        : 'admin-wholesale-application:${savedAccount!.id}:'
            '${existing == null ? 'new' : 'updated'}',
  );
}

Future<List<WholesaleProduct>> fetchWholesaleCatalogue() async {
  final settings = await fetchMarketplaceProgramSettings();
  if (!settings.wholesaleWorkspaceEnabled) {
    throw Exception('Wholesale ordering is temporarily unavailable.');
  }

  final response = await supabase.rpc('fetch_wholesale_catalogue');

  return (response as List)
      .map(
        (item) => WholesaleProduct.fromSupabase(
          Map<String, dynamic>.from(item as Map),
        ),
      )
      .where((item) => item.canOrder)
      .toList()
    ..sort(
      (a, b) => a.product.name.toLowerCase().compareTo(
            b.product.name.toLowerCase(),
          ),
    );
}

// =====================================================
// PHASE 3R — SCHEDULING SERVICES
// =====================================================

Future<List<WholesaleScheduleOption>> fetchWholesaleScheduleOptions({
  String dispatchMethod = 'hpj_delivery',
  int daysAhead = 45,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Please sign in to view wholesale delivery windows.');
  }

  final method = dispatchMethod.trim().toLowerCase();
  if (!const {'hpj_delivery', 'business_collection'}.contains(method)) {
    throw Exception('Choose a valid wholesale fulfilment method.');
  }

  final now = DateTime.now();
  final safeDaysAhead = daysAhead < 7 ? 7 : (daysAhead > 120 ? 120 : daysAhead);
  final to = now.add(Duration(days: safeDaysAhead));

  final response = await supabase.rpc(
    'wholesale_available_schedule_windows',
    params: {
      'p_dispatch_method': method,
      'p_from_date': _wholesaleDemandDateIso(now),
      'p_to_date': _wholesaleDemandDateIso(to),
    },
  );

  return (response as List)
      .map(
        (item) => WholesaleScheduleOption.fromSupabase(
          Map<String, dynamic>.from(item as Map),
        ),
      )
      .where((item) => item.isAvailable)
      .toList();
}

Future<WholesaleScheduleSettings> fetchWholesaleScheduleSettings() async {
