Future<void> adminUpdateWholesaleScheduleSettings({
  required int minLeadDays,
  required int maxAdvanceDays,
  required String cutoffTime,
  required int dailyCapacity,
}) async {
  await requireAdminAccess();

  if (minLeadDays < 0 || minLeadDays > 30) {
    throw Exception('Lead time must be between 0 and 30 days.');
  }
  if (maxAdvanceDays < 7 || maxAdvanceDays > 365) {
    throw Exception('Advance booking must be between 7 and 365 days.');
  }
  if (dailyCapacity < 0 || dailyCapacity > 1000) {
    throw Exception('Daily capacity must be between 0 and 1000.');
  }
  if (!RegExp(r'^([01]\d|2[0-3]):[0-5]\d$').hasMatch(cutoffTime.trim())) {
    throw Exception('Cutoff time must use 24-hour HH:MM format.');
  }

  await supabase.from('wholesale_schedule_settings').update({
    'min_lead_days': minLeadDays,
    'max_advance_days': maxAdvanceDays,
    'cutoff_time': cutoffTime.trim(),
    'daily_capacity': dailyCapacity,
    'updated_at': DateTime.now().toUtc().toIso8601String(),
    'updated_by': supabase.auth.currentUser?.id,
  }).eq('id', 'default');
}

Future<void> adminUpsertWholesaleScheduleWindow({
  String? id,
  required int dayOfWeek,
  required String dispatchMethod,
  required String label,
  required String startTime,
  required String endTime,
  required int maxRequests,
  required bool isActive,
}) async {
  await requireAdminAccess();

  if (dayOfWeek < 0 || dayOfWeek > 6) {
    throw Exception('Choose a valid day of the week.');
  }
  if (maxRequests < 1 || maxRequests > 500) {
    throw Exception('Window capacity must be between 1 and 500 requests.');
  }

  final method = dispatchMethod.trim().toLowerCase();
  if (!const {'hpj_delivery', 'business_collection'}.contains(method)) {
    throw Exception('Choose a valid fulfilment method.');
  }

  final cleanLabel = label.trim();
  if (cleanLabel.isEmpty) throw Exception('Enter a window label.');

  final timePattern = RegExp(r'^([01]\d|2[0-3]):[0-5]\d$');
  if (!timePattern.hasMatch(startTime.trim()) ||
      !timePattern.hasMatch(endTime.trim())) {
    throw Exception('Start and end times must use HH:MM.');
  }

  final payload = <String, dynamic>{
    'day_of_week': dayOfWeek,
    'dispatch_method': method,
    'label': cleanLabel,
    'start_time': startTime.trim(),
    'end_time': endTime.trim(),
    'max_requests': maxRequests,
    'is_active': isActive,
    'updated_at': DateTime.now().toUtc().toIso8601String(),
  };

  final cleanId = id?.trim() ?? '';
  if (cleanId.isEmpty) {
    await supabase.from('wholesale_delivery_windows').insert(payload);
  } else {
    await supabase
        .from('wholesale_delivery_windows')
        .update(payload)
        .eq('id', cleanId);
  }
}

