class _WholesaleSavedBasketDraft {
  final List<_WholesaleBasketLine> lines;
  final List<String> unavailableProducts;

  const _WholesaleSavedBasketDraft({
    required this.lines,
    required this.unavailableProducts,
  });
}

Future<_WholesaleSavedBasketDraft> prepareWholesaleSavedBasket(
  List<WholesaleSavedOrderItem> savedItems,
) async {
  final catalogue = await fetchWholesaleCatalogue();
  final byId = <String, WholesaleProduct>{
    for (final item in catalogue) item.product.id: item,
  };
  final byName = <String, WholesaleProduct>{
    for (final item in catalogue) item.product.name.trim().toLowerCase(): item,
  };

  final lines = <_WholesaleBasketLine>[];
  final unavailable = <String>[];

  for (final saved in savedItems) {
    WholesaleProduct? current;
    final productId = saved.productId?.trim() ?? '';
    if (productId.isNotEmpty) current = byId[productId];
    current ??= byName[saved.productName.trim().toLowerCase()];

    if (current == null || !current.canOrder) {
      unavailable.add(saved.productName);
      continue;
    }

    int quantity = saved.quantity.ceil();
    if (quantity < current.minimumQuantity) quantity = current.minimumQuantity;
    lines.add(_WholesaleBasketLine(item: current, quantity: quantity));
  }

  return _WholesaleSavedBasketDraft(
    lines: lines,
    unavailableProducts: unavailable,
  );
}

