Future<void> adminUpdateBusinessStatus({
  required BusinessAccount account,
  required String status,
  String adminNotes = '',
}) async {
  await requireAdminAccess();

  final cleanStatus = normalizeBusinessAccountStatus(status);
  await supabase.rpc(
    'admin_set_business_status',
    params: {
      'p_business_account_id': account.id,
      'p_status': cleanStatus,
      'p_admin_notes': adminNotes.trim(),
    },
  );

  final title = cleanStatus == 'approved'
      ? 'Wholesale account approved'
      : cleanStatus == 'suspended'
          ? 'Wholesale account suspended'
          : cleanStatus == 'rejected'
              ? 'Wholesale application update'
              : 'Wholesale application under review';

  final message = cleanStatus == 'approved'
      ? 'Your business account has been approved. You can now access wholesale prices and submit bulk requests.'
      : cleanStatus == 'suspended'
          ? 'Wholesale access has been paused. Please contact The Harvest Place Ja for assistance.'
          : cleanStatus == 'rejected'
              ? 'Your wholesale application needs additional information. Open Business / Wholesale in your account to review the update.'
              : 'Your wholesale application is being reviewed.';

  await createFarmNotification(
    title: title,
    message: message,
    type: 'wholesale',
    userId: account.userId,
    userEmail: account.email,
    actionType: 'wholesale_account',
    actionId: account.id,
    dedupeKey:
        'wholesale-account:${account.id}:${status.trim().toLowerCase()}',
  );
}

// =====================================================
// PHASE 3P — ADMIN WHOLESALE CREDIT TERMS
// =====================================================

Future<void> adminUpdateWholesaleCreditTerms({
  required BusinessAccount account,
  required bool creditEnabled,
  required double creditLimit,
  required int paymentTermsDays,
  required String creditStatus,
  String creditNote = '',
}) async {
  await requireAdminAccess();

  if (creditLimit < 0 || creditLimit.isNaN || creditLimit.isInfinite) {
    throw Exception('Credit limit cannot be negative.');
  }

  if (paymentTermsDays < 0 || paymentTermsDays > 365) {
    throw Exception('Payment terms must be between 0 and 365 days.');
  }

  final cleanStatus =
      creditEnabled ? creditStatus.trim().toLowerCase() : 'cash_only';

  if (creditEnabled && !const {'active', 'hold'}.contains(cleanStatus)) {
    throw Exception('Choose Active or Credit Hold.');
  }

  await supabase.rpc(
    'admin_set_wholesale_credit_terms',
    params: {
      'p_business_account_id': account.id,
      'p_credit_enabled': creditEnabled,
      'p_credit_limit': creditLimit,
      'p_payment_terms_days': creditEnabled ? paymentTermsDays : 0,
      'p_credit_status': cleanStatus,
      'p_credit_note': creditNote.trim(),
    },
  );

  final statusText = !creditEnabled
      ? 'Cash / due now'
      : cleanStatus == 'hold'
          ? 'Credit hold'
          : 'Credit active';

  await createFarmNotification(
    title: 'Wholesale account terms updated',
    message: creditEnabled
        ? '$statusText • Net $paymentTermsDays • '
            '${creditLimit > 0 ? 'Limit ${formatJmd(creditLimit)}' : 'No hard credit limit'}.'
        : 'Your wholesale account is set to payment due on issue.',
    type: 'wholesale',
    userId: account.userId,
    userEmail: account.email,
    actionType: 'wholesale_account',
    actionId: account.id,
    dedupeKey: 'wholesale-account-terms:${account.id}:'
        '${creditEnabled ? 'credit' : 'cash'}:$paymentTermsDays:'
        '${creditLimit.toStringAsFixed(2)}',
  );
}

