// =====================================================
// APPROVED ORDER → WAREHOUSE-FIRST PROCUREMENT PREP
//
// The database migration creates procurement requirements
// for each approved wholesale order line. This helper also
// creates the fulfilment (if needed) and reserves usable
// warehouse lots first, so Procurement only asks farmers for
// the remaining uncovered quantity.
// =====================================================

Future<void> prepareApprovedWholesaleRequestForProcurement(
  String requestId,
) async {
  await requireAdminAccess();

  final cleanId = requestId.trim();
  if (cleanId.isEmpty) return;

  final requests = await fetchAdminWholesaleRequests();
  WholesaleOrderRequest? request;
  for (final item in requests) {
    if (item.id == cleanId) {
      request = item;
      break;
    }
  }

  if (request == null || request.status != 'approved') {
    return;
  }

  var fulfillment = await fetchWholesaleFulfillmentForRequest(cleanId);
  fulfillment ??= await createWholesaleFulfillment(request);

  await reserveWholesaleFulfillmentStock(fulfillment);
}

