String _wholesaleStatementDate(
  DateTime? value,
) {
  if (value == null) return '-';

  return '${value.year}-'
      '${value.month.toString().padLeft(2, '0')}-'
      '${value.day.toString().padLeft(2, '0')}';
}

String _wholesaleStatementStatus(
  String value,
) {
  final clean = value
      .trim()
      .replaceAll('_', ' ');

  if (clean.isEmpty) return '-';

  return clean
      .split(' ')
      .where((item) => item.isNotEmpty)
      .map(
        (item) =>
            '${item[0].toUpperCase()}${item.substring(1)}',
      )
      .join(' ');
}

Future<Uint8List>
    _buildWholesaleActivityStatementPdf(
  BusinessAccount account,
  _WholesaleTodaySnapshot data,
) async {
  final pdf = pw.Document();
  final logo =
      await _loadBusinessPortalPdfLogo();

  final green =
      PdfColor.fromInt(0xFF1F6B3A);
  final softGreen =
      PdfColor.fromInt(0xFFEAF3EC);

  final totalPaid =
      data.invoices.fold<double>(
    0,
    (sum, item) =>
        sum + item.paidAmount,
  );

  final totalDue =
      data.invoices.fold<double>(
    0,
    (sum, item) =>
        sum + item.amountDue,
  );

  final completedOrders =
      data.requests.where(
    (item) {
      final status =
          item.status.trim().toLowerCase();

      return status == 'completed' ||
          status == 'delivered';
    },
  ).length;

  pw.Widget metric(
    String label,
    String value,
  ) {
    return pw.Expanded(
      child: pw.Container(
        padding: const pw.EdgeInsets.all(9),
        decoration: pw.BoxDecoration(
          color: softGreen,
          borderRadius:
              pw.BorderRadius.circular(6),
        ),
        child: pw.Column(
          crossAxisAlignment:
              pw.CrossAxisAlignment.start,
          children: [
            pw.Text(
              label,
              style: const pw.TextStyle(
                fontSize: 7.5,
                color: PdfColors.grey700,
              ),
            ),
            pw.SizedBox(height: 4),
            pw.Text(
              _businessPortalPdfClean(
                value,
              ),
              style: pw.TextStyle(
                fontSize: 11,
                fontWeight:
                    pw.FontWeight.bold,
                color: green,
              ),
            ),
          ],
        ),
      ),
    );
  }

  pw.Widget sectionTitle(String value) {
    return pw.Container(
      width: double.infinity,
      padding:
          const pw.EdgeInsets.symmetric(
        vertical: 6,
        horizontal: 8,
      ),
      decoration: pw.BoxDecoration(
        color: softGreen,
        borderRadius:
            pw.BorderRadius.circular(5),
      ),
      child: pw.Text(
        value,
        style: pw.TextStyle(
          fontSize: 10,
          fontWeight: pw.FontWeight.bold,
          color: green,
        ),
      ),
    );
  }

  pw.Widget table({
    required List<String> headers,
    required List<List<String>> rows,
  }) {
    if (rows.isEmpty) {
      return pw.Padding(
        padding:
            const pw.EdgeInsets.symmetric(
          vertical: 8,
        ),
        child: pw.Text(
          'No records available.',
          style: const pw.TextStyle(
            fontSize: 8.5,
            color: PdfColors.grey600,
          ),
        ),
      );
    }

    return pw.TableHelper.fromTextArray(
      headers: headers,
      data: rows
          .map(
            (row) => row
                .map(
                  _businessPortalPdfClean,
                )
                .toList(),
          )
          .toList(),
      headerDecoration: pw.BoxDecoration(
        color: PdfColors.grey200,
      ),
      headerStyle: pw.TextStyle(
        fontSize: 7.5,
        fontWeight: pw.FontWeight.bold,
      ),
      cellStyle:
          const pw.TextStyle(fontSize: 7.2),
      cellPadding:
          const pw.EdgeInsets.all(4),
      border: pw.TableBorder.all(
        color: PdfColors.grey300,
        width: 0.5,
      ),
    );
  }

  final forecasts =
      List<WholesaleDemandForecast>.from(
    data.forecasts,
  )
        ..sort(
          (a, b) => b.needByDate
              .compareTo(a.needByDate),
        );

  final requests =
      List<WholesaleOrderRequest>.from(
    data.requests,
  )
        ..sort(
          (a, b) =>
              (b.createdAt ??
                      DateTime(2000))
                  .compareTo(
            a.createdAt ??
                DateTime(2000),
          ),
        );

  final invoices =
      List<WholesaleInvoice>.from(
    data.invoices,
  )
        ..sort(
          (a, b) =>
              (b.issueDate ??
                      b.createdAt ??
                      DateTime(2000))
                  .compareTo(
            a.issueDate ??
                a.createdAt ??
                DateTime(2000),
          ),
        );

  pdf.addPage(
    pw.MultiPage(
      pageFormat: PdfPageFormat.a4,
      margin: const pw.EdgeInsets.fromLTRB(
        32,
        30,
        32,
        34,
      ),
      footer: (context) => pw.Column(
        children: [
          pw.Divider(
            color: PdfColors.grey300,
          ),
          pw.Row(
            mainAxisAlignment:
                pw.MainAxisAlignment
                    .spaceBetween,
            children: [
              pw.Text(
                'The Harvest Place Ja',
                style: const pw.TextStyle(
                  fontSize: 7,
                  color: PdfColors.grey600,
                ),
              ),
              pw.Text(
                'Page ${context.pageNumber} of ${context.pagesCount}',
                style: const pw.TextStyle(
                  fontSize: 7,
                  color: PdfColors.grey600,
                ),
              ),
            ],
          ),
        ],
      ),
      build: (context) => [
        _businessPortalPdfHeader(
          logo: logo,
          title:
              'BUSINESS ACTIVITY STATEMENT',
          reference:
              _wholesaleStatementDate(
            DateTime.now(),
          ),
        ),

        pw.SizedBox(height: 14),

        pw.Container(
          width: double.infinity,
          padding:
              const pw.EdgeInsets.all(10),
          decoration: pw.BoxDecoration(
            border: pw.Border.all(
              color: PdfColors.grey300,
            ),
            borderRadius:
                pw.BorderRadius.circular(6),
          ),
          child: pw.Column(
            crossAxisAlignment:
                pw.CrossAxisAlignment.start,
            children: [
              pw.Text(
                _businessPortalPdfClean(
                  account.displayName,
                ),
                style: pw.TextStyle(
                  fontSize: 10.5,
                  fontWeight:
                      pw.FontWeight.bold,
                ),
              ),
              pw.SizedBox(height: 3),
              pw.Text(
                _businessPortalPdfClean(
                  [
                    if (account.parish
                        .trim()
                        .isNotEmpty)
                      account.parish,
                    if (account.phone
                        .trim()
                        .isNotEmpty)
                      account.phone,
                  ].join(' | '),
                ),
                style: const pw.TextStyle(
                  fontSize: 8,
                ),
              ),
            ],
          ),
        ),

        pw.SizedBox(height: 12),

        pw.Row(
          children: [
            metric(
              'Future needs',
              '${data.forecasts.length}',
            ),
            pw.SizedBox(width: 7),
            metric(
              'Orders completed',
              '$completedOrders',
            ),
            pw.SizedBox(width: 7),
            metric(
              'Payments recorded',
              formatJmd(totalPaid),
            ),
          ],
        ),

        pw.SizedBox(height: 7),

        pw.Row(
          children: [
            metric(
              'Orders placed',
              '${data.requests.length}',
            ),
            pw.SizedBox(width: 7),
            metric(
              'Invoices',
              '${data.invoices.length}',
            ),
            pw.SizedBox(width: 7),
            metric(
              'Amount due',
              formatJmd(totalDue),
            ),
          ],
        ),

        pw.SizedBox(height: 18),
        sectionTitle(
          'PLANNING AHEAD HISTORY',
        ),
        pw.SizedBox(height: 6),
        table(
          headers: const [
            'Product',
            'Quantity',
            'Need by',
            'Status',
          ],
          rows: forecasts
              .take(30)
              .map(
                (item) => [
                  item.productName,
                  item.formattedQuantity,
                  _wholesaleStatementDate(
                    item.needByDate,
                  ),
                  item.statusLabel,
                ],
              )
              .toList(),
        ),

        pw.SizedBox(height: 16),
        sectionTitle(
          'WHOLESALE ORDER HISTORY',
        ),
        pw.SizedBox(height: 6),
        table(
          headers: const [
            'Created',
            'Reference',
            'Estimate',
            'Status',
          ],
          rows: requests
              .take(30)
              .map(
                (item) => [
                  _wholesaleStatementDate(
                    item.createdAt,
                  ),
                  item.shortId,
                  formatJmd(
                    item.quotedTotal ??
                        item.subtotalEstimate,
                  ),
                  _wholesaleStatementStatus(
                    item.status,
                  ),
                ],
              )
              .toList(),
        ),

        pw.SizedBox(height: 16),
        sectionTitle(
          'INVOICE & PAYMENT HISTORY',
        ),
        pw.SizedBox(height: 6),
        table(
          headers: const [
            'Date',
            'Invoice',
            'Total',
            'Paid',
            'Due',
            'Status',
          ],
          rows: invoices
              .take(30)
              .map(
                (item) => [
                  _wholesaleStatementDate(
                    item.issueDate ??
                        item.createdAt,
                  ),
                  item.invoiceNumber,
                  formatJmd(
                    item.totalAmount,
                  ),
                  formatJmd(
                    item.paidAmount,
                  ),
                  formatJmd(
                    item.amountDue,
                  ),
                  item.paymentStatusLabel,
                ],
              )
              .toList(),
        ),

        pw.SizedBox(height: 18),

        pw.Container(
          padding:
              const pw.EdgeInsets.all(9),
          decoration: pw.BoxDecoration(
            color: PdfColors.grey100,
            borderRadius:
                pw.BorderRadius.circular(5),
          ),
          child: pw.Text(
            'This statement is a record of activity held in The Harvest Place Ja system. '
            'It is not a bank statement, audited financial statement, credit rating or tax certificate.',
            style: const pw.TextStyle(
              fontSize: 7.4,
              color: PdfColors.grey700,
            ),
          ),
        ),
      ],
    ),
  );

  return pdf.save();
}

class _WholesaleActivityStatementScreen
    extends StatefulWidget {
  final BusinessAccount account;

  const _WholesaleActivityStatementScreen({
    required this.account,
  });

  @override
  State<_WholesaleActivityStatementScreen>
      createState() =>
          _WholesaleActivityStatementScreenState();
}

class _WholesaleActivityStatementScreenState
    extends State<
        _WholesaleActivityStatementScreen> {
  late Future<_WholesaleTodaySnapshot>
      future;

  bool exporting = false;

  @override
  void initState() {
    super.initState();

    future =
        fetchWholesaleTodaySnapshot();
  }

  Future<void> _refresh() async {
    setState(() {
      future =
          fetchWholesaleTodaySnapshot();
    });

    await future;
  }

  Future<void> _printOrSave(
    _WholesaleTodaySnapshot data,
  ) async {
    if (exporting) return;

    setState(() {
      exporting = true;
    });

    try {
      final bytes =
          await _buildWholesaleActivityStatementPdf(
        widget.account,
        data,
      );

      await Printing.layoutPdf(
        onLayout: (_) async => bytes,
        name:
            'HPJ_Business_Activity_Statement.pdf',
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() {
          exporting = false;
        });
      }
    }
  }

  Future<void> _share(
    _WholesaleTodaySnapshot data,
  ) async {
    if (exporting) return;

    setState(() {
      exporting = true;
    });

    try {
      final bytes =
          await _buildWholesaleActivityStatementPdf(
        widget.account,
        data,
      );

      await Printing.sharePdf(
        bytes: bytes,
        filename:
            'HPJ_Business_Activity_Statement.pdf',
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() {
          exporting = false;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        title: const Text(
          'Business Activity Statement',
        ),
      ),
      body:
          FutureBuilder<_WholesaleTodaySnapshot>(
        future: future,
        builder: (context, snapshot) {
          if (snapshot.connectionState ==
                  ConnectionState.waiting &&
              snapshot.data == null) {
            return const Center(
              child:
                  CircularProgressIndicator(),
            );
          }

          if (snapshot.hasError ||
              snapshot.data == null) {
            return Center(
              child: Padding(
                padding:
                    const EdgeInsets.all(24),
                child: Column(
                  mainAxisSize:
                      MainAxisSize.min,
                  children: [
                    const Text(
                      'Your business statement could not be loaded.',
                      textAlign:
                          TextAlign.center,
                    ),
                    const SizedBox(
                      height: 12,
                    ),
                    OutlinedButton(
                      onPressed: _refresh,
                      child: const Text(
                        'Try Again',
                      ),
                    ),
                  ],
                ),
              ),
            );
          }

          final data = snapshot.data!;

          final totalPaid =
              data.invoices.fold<double>(
            0,
            (sum, item) =>
                sum + item.paidAmount,
          );

          final totalDue =
              data.invoices.fold<double>(
            0,
            (sum, item) =>
                sum + item.amountDue,
          );

          return RefreshIndicator(
            onRefresh: _refresh,
            child: ListView(
              padding:
                  const EdgeInsets.fromLTRB(
                18,
                16,
                18,
                32,
              ),
              children: [
                FarmCard(
                  padding:
                      const EdgeInsets.all(
                    16,
                  ),
                  child: Column(
                    crossAxisAlignment:
                        CrossAxisAlignment
                            .start,
                    children: [
                      Text(
                        widget.account
                            .displayName,
                        style:
                            const TextStyle(
                          color:
                              FarmColors.ink,
                          fontSize: 17,
                          fontWeight:
                              FontWeight.w900,
                        ),
                      ),
                      const SizedBox(
                        height: 4,
                      ),
                      const Text(
                        'Your own HPJ planning, purchasing and payment record.',
                        style: TextStyle(
                          color: FarmColors
                              .mutedText,
                          fontSize: 10.2,
                          height: 1.35,
                          fontWeight:
                              FontWeight.w600,
                        ),
                      ),
                      const SizedBox(
                        height: 14,
                      ),
                      Row(
                        children: [
                          Expanded(
                            child:
                                _WholesaleStatementMetric(
                              label:
                                  'Future needs',
                              value:
                                  '${data.forecasts.length}',
                            ),
                          ),
                          const SizedBox(
                            width: 8,
                          ),
                          Expanded(
                            child:
                                _WholesaleStatementMetric(
                              label:
                                  'Orders',
                              value:
                                  '${data.requests.length}',
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(
                        height: 8,
                      ),
                      Row(
                        children: [
                          Expanded(
                            child:
                                _WholesaleStatementMetric(
                              label:
                                  'Payments recorded',
                              value:
                                  formatJmd(totalPaid),
                            ),
                          ),
                          const SizedBox(
                            width: 8,
                          ),
                          Expanded(
                            child:
                                _WholesaleStatementMetric(
                              label:
                                  'Amount due',
                              value:
                                  formatJmd(totalDue),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),

                const SizedBox(height: 12),

                FarmCard(
                  child: Column(
                    crossAxisAlignment:
                        CrossAxisAlignment
                            .start,
                    children: [
                      const Text(
                        'Export your record',
                        style: TextStyle(
                          color:
                              FarmColors.ink,
                          fontSize: 13,
                          fontWeight:
                              FontWeight.w900,
                        ),
                      ),
                      const SizedBox(
                        height: 4,
                      ),
                      const Text(
                        'Keep a PDF copy for your internal records or share it with the appropriate person in your business.',
                        style: TextStyle(
                          color: FarmColors
                              .mutedText,
                          fontSize: 9.6,
                          height: 1.35,
                          fontWeight:
                              FontWeight.w600,
                        ),
                      ),
                      const SizedBox(
                        height: 12,
                      ),
                      SizedBox(
                        width:
                            double.infinity,
                        child: ElevatedButton
                            .icon(
                          onPressed: exporting
                              ? null
                              : () =>
                                  _printOrSave(
                                    data,
                                  ),
                          icon: const Icon(
                            Icons
                                .picture_as_pdf_outlined,
                          ),
                          label: Text(
                            exporting
                                ? 'Preparing...'
                                : 'View / Save PDF',
                          ),
                        ),
                      ),
                      const SizedBox(
                        height: 7,
                      ),
                      SizedBox(
                        width:
                            double.infinity,
                        child:
                            OutlinedButton.icon(
                          onPressed: exporting
                              ? null
                              : () =>
                                  _share(
                                    data,
                                  ),
                          icon: const Icon(
                            Icons.share_outlined,
                          ),
                          label:
                              const Text(
                            'Share PDF',
                          ),
                        ),
                      ),
                    ],
                  ),
                ),

                const SizedBox(height: 12),

                Container(
                  padding:
                      const EdgeInsets.all(
                    12,
                  ),
                  decoration: BoxDecoration(
                    color: const Color(
                      0xFFF0F4EC,
                    ),
                    borderRadius:
                        BorderRadius.circular(
                      15,
                    ),
                    border: Border.all(
                      color: const Color(
                        0xFFDCE4D8,
                      ),
                    ),
                  ),
                  child: const Text(
                    'This is an HPJ activity record, not a bank statement, audited financial statement, credit rating or tax certificate.',
                    style: TextStyle(
                      color: FarmColors
                          .mutedText,
                      fontSize: 9.4,
                      height: 1.35,
                      fontWeight:
                          FontWeight.w600,
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

