class WholesaleSchedulingAdminScreen extends StatefulWidget {
  const WholesaleSchedulingAdminScreen({super.key});

  @override
  State<WholesaleSchedulingAdminScreen> createState() =>
      _WholesaleSchedulingAdminScreenState();
}

class _WholesaleSchedulingAdminScreenState
    extends State<WholesaleSchedulingAdminScreen> {
  late Future<List<Object>> _future;

  @override
  void initState() {
    super.initState();
    _reloadFuture();
  }

  void _reloadFuture() {
    _future = Future.wait<Object>([
      fetchWholesaleScheduleSettings(),
      fetchAdminWholesaleScheduleWindows(),
      fetchAdminWholesaleScheduleBlackouts(),
    ]);
  }

  Future<void> _reload() async {
    setState(_reloadFuture);
    await _future;
  }

  Future<void> _editSettings(WholesaleScheduleSettings settings) async {
    final lead = TextEditingController(text: '${settings.minLeadDays}');
    final advance = TextEditingController(text: '${settings.maxAdvanceDays}');
    final cutoffText = settings.cutoffTime.length <= 5
        ? settings.cutoffTime
        : settings.cutoffTime.substring(0, 5);
    final cutoff = TextEditingController(text: cutoffText);
    final capacity = TextEditingController(text: '${settings.dailyCapacity}');

    final save = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Wholesale scheduling rules'),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                controller: lead,
                keyboardType: TextInputType.number,
                decoration:
                    const InputDecoration(labelText: 'Minimum lead days'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: advance,
                keyboardType: TextInputType.number,
                decoration:
                    const InputDecoration(labelText: 'Maximum days ahead'),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: cutoff,
                decoration: const InputDecoration(
                  labelText: 'Daily cutoff time',
                  hintText: '14:00',
                ),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: capacity,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  labelText: 'Maximum requests per day',
                  helperText: '0 = no separate daily cap',
                ),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Save'),
          ),
        ],
      ),
    );

    if (save != true) return;

    try {
      await adminUpdateWholesaleScheduleSettings(
        minLeadDays: int.tryParse(lead.text.trim()) ?? settings.minLeadDays,
        maxAdvanceDays:
            int.tryParse(advance.text.trim()) ?? settings.maxAdvanceDays,
        cutoffTime: cutoff.text.trim(),
        dailyCapacity:
            int.tryParse(capacity.text.trim()) ?? settings.dailyCapacity,
      );
      await _reload();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Wholesale scheduling rules updated.')),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      lead.dispose();
      advance.dispose();
      cutoff.dispose();
      capacity.dispose();
    }
  }

