  Future<void> _addBlackout() async {
    DateTime selectedDate = DateTime.now().add(const Duration(days: 1));
    String method = 'all';
    final reason = TextEditingController();

    final save = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) => AlertDialog(
          title: const Text('Add blackout date'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              ListTile(
                contentPadding: EdgeInsets.zero,
                leading: const Icon(Icons.event_busy_outlined),
                title: Text(
                  '${selectedDate.day}/${selectedDate.month}/${selectedDate.year}',
                ),
                trailing: const Icon(Icons.edit_calendar_outlined),
                onTap: () async {
                  final picked = await showDatePicker(
                    context: context,
                    initialDate: selectedDate,
                    firstDate: DateTime.now(),
                    lastDate: DateTime.now().add(const Duration(days: 365)),
                  );
                  if (picked != null)
                    setDialogState(() => selectedDate = picked);
                },
              ),
              DropdownButtonFormField<String>(
                value: method,
                decoration: const InputDecoration(labelText: 'Applies to'),
                items: const [
                  DropdownMenuItem(
                      value: 'all', child: Text('All wholesale fulfilment')),
                  DropdownMenuItem(
                      value: 'hpj_delivery', child: Text('HPJ Delivery only')),
                  DropdownMenuItem(
                      value: 'business_collection',
                      child: Text('Collection only')),
                ],
                onChanged: (value) {
                  if (value != null) setDialogState(() => method = value);
                },
              ),
              const SizedBox(height: 10),
              TextField(
                controller: reason,
                maxLines: 2,
                decoration: const InputDecoration(labelText: 'Reason / note'),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('Add Blackout'),
            ),
          ],
        ),
      ),
    );

    if (save != true) {
      reason.dispose();
      return;
    }

    try {
      await adminAddWholesaleBlackout(
        date: selectedDate,
        dispatchMethod: method,
        reason: reason.text,
      );
      await _reload();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      reason.dispose();
    }
  }

