}

class _WholesaleDailyPickCardState extends State<_WholesaleDailyPickCard> {
  bool seen = true;

  String get feedKey {
    final now = DateTime.now();
    final date = '${now.year.toString().padLeft(4, '0')}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
    return 'fresh:${widget.item.product.id}:$date';
  }

  @override
  void initState() {
    super.initState();
    _loadSeen();
  }

  @override
  void didUpdateWidget(covariant _WholesaleDailyPickCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.item.product.id != widget.item.product.id) {
      _loadSeen();
    }
  }

  Future<void> _loadSeen() async {
    final value = await isHpjFeedItemSeen(
      workspace: 'wholesale',
      itemKey: feedKey,
    );
    if (mounted) setState(() => seen = value);
  }

  Future<void> _open() async {
    if (!seen && mounted) setState(() => seen = true);
    await markHpjFeedItemSeen(
      workspace: 'wholesale',
      itemKey: feedKey,
    );
    if (!mounted) return;
    widget.onTap();
  }

  @override
  Widget build(BuildContext context) {
    final item = widget.item;
    return SizedBox(
      width: 148,
      child: Material(
        color: FarmColors.card,
        borderRadius: BorderRadius.circular(18),
        child: InkWell(
          borderRadius: BorderRadius.circular(18),
          onTap: _open,
          child: Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: FarmColors.line),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Stack(
                  children: [
                    HpjProductThumb(
                      productId: item.product.id,
                      productName: item.product.name,
                      size: 106,
                      radius: 14,
                    ),
                    if (!seen)
                      Positioned(
                        left: 6,
                        top: 6,
                        child: Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 7,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: FarmColors.danger,
                            borderRadius: BorderRadius.circular(99),
                          ),
                          child: const Text(
                            'NEW',
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 8.8,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ),
                  ],
                ),
                const SizedBox(height: 8),
                Text(
                  item.product.name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: FarmColors.ink,
                    fontSize: 12.6,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  '${item.formattedWholesalePrice} / ${item.wholesaleUnit}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: FarmColors.primary,
                    fontSize: 10.4,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const Spacer(),
                SizedBox(
                  width: double.infinity,
                  child: HpjWatchButton(
                    workspace: 'wholesale',
                    watchType: 'product',
                    entityKey: item.product.id,
                    entityName: item.product.name,
                    compact: true,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

