class _WholesaleActiveOrderCard extends StatelessWidget {
  final WholesaleOrderRequest request;
  final VoidCallback onTap;

  const _WholesaleActiveOrderCard({
    required this.request,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final requestedDate = request.requestedDate == null
        ? null
        : _wholesaleSimpleDate(request.requestedDate!);
    final fulfilment = request.requestedDispatchMethod == 'business_collection'
        ? 'Business collection'
        : 'HPJ delivery';
    final itemCount = request.items.length;
    final firstItem = itemCount == 0 ? null : request.items.first;

    Widget orderVisual() {
      if (firstItem == null) {
        return Container(
          width: 58,
          height: 58,
          decoration: BoxDecoration(
            color: FarmColors.primarySoft,
            borderRadius: BorderRadius.circular(14),
          ),
          child: const Icon(
            Icons.local_shipping_outlined,
            color: FarmColors.primary,
          ),
        );
      }

      return SizedBox(
        width: 62,
        height: 62,
        child: Stack(
          clipBehavior: Clip.none,
          children: [
            HpjProductThumb(
              productId: firstItem.productId,
              productName: firstItem.productName,
              size: 58,
              radius: 14,
            ),
            if (itemCount > 1)
              Positioned(
                right: -2,
                bottom: -2,
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: FarmColors.primary,
                    borderRadius: BorderRadius.circular(99),
                    border: Border.all(color: Colors.white, width: 2),
                  ),
                  child: Text(
                    '+${itemCount - 1}',
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 9,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ),
          ],
        ),
      );
    }

    return FarmCard(
      padding: EdgeInsets.zero,
      child: InkWell(
        borderRadius: BorderRadius.circular(20),
        onTap: onTap,
        child: Padding(
          padding: const EdgeInsets.all(14),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              orderVisual(),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Order in progress',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 9.2,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      'Order #${request.shortId}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 12.5,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      [
                        _wholesaleStatementStatus(request.status),
                        if (itemCount > 0)
                          '$itemCount item${itemCount == 1 ? '' : 's'}',
                        fulfilment,
                        if (requestedDate != null) 'Requested $requestedDate',
                      ].join(' • '),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 9.6,
                        height: 1.3,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 6),
              const Icon(
                Icons.chevron_right_rounded,
                color: FarmColors.mutedText,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

