class _WholesalePlanningValueSheet
    extends StatelessWidget {
  final String productName;
  final double quantity;
  final String unit;
  final DateTime needByDate;
  final String frequency;
  final String certainty;

  const _WholesalePlanningValueSheet({
    required this.productName,
    required this.quantity,
    required this.unit,
    required this.needByDate,
    required this.frequency,
    required this.certainty,
  });

  String get quantityLabel {
    if (quantity == quantity.roundToDouble()) {
      return quantity.toStringAsFixed(0);
    }

    return quantity.toStringAsFixed(1);
  }

  String get frequencyLabel {
    switch (frequency) {
      case 'weekly':
        return 'Weekly';
      case 'biweekly':
        return 'Every 2 weeks';
      case 'monthly':
        return 'Monthly';
      default:
        return 'One time';
    }
  }

  String get certaintyLabel {
    switch (certainty) {
      case 'expected':
        return 'Expected';
      case 'tentative':
        return 'Tentative';
      default:
        return 'Likely';
    }
  }

  int get noticeDays {
    final now = DateTime.now();
    final today = DateTime(
      now.year,
      now.month,
      now.day,
    );
    final need = DateTime(
      needByDate.year,
      needByDate.month,
      needByDate.day,
    );

    final days = need.difference(today).inDays;

    return days < 0 ? 0 : days;
  }

  @override
  Widget build(BuildContext context) {
    final screenHeight = MediaQuery.sizeOf(context).height;

    return ConstrainedBox(
      constraints: BoxConstraints(
        maxHeight: screenHeight * 0.88,
      ),
      child: Container(
        decoration: const BoxDecoration(
          color: FarmColors.card,
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(26),
          ),
        ),
        padding: const EdgeInsets.fromLTRB(
          18,
          14,
          18,
          12,
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Center(
              child: Container(
                width: 42,
                height: 4,
                decoration: BoxDecoration(
                  color: FarmColors.line,
                  borderRadius: BorderRadius.circular(99),
                ),
              ),
            ),
            const SizedBox(height: 12),

            Flexible(
              child: SingleChildScrollView(
                physics: const BouncingScrollPhysics(),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    HpjProductThumb(
                      productName: productName,
                      size: 76,
                      radius: 16,
                    ),
                    const SizedBox(height: 12),
                    const Text(
                      'PLANNED NEED SAVED',
                      style: TextStyle(
                        color: FarmColors.success,
                        fontSize: 9,
                        fontWeight: FontWeight.w900,
                        letterSpacing: 1.5,
                      ),
                    ),
                    const SizedBox(height: 5),
                    Text(
                      noticeDays > 0
                          ? 'HPJ now has $noticeDays day${noticeDays == 1 ? '' : 's'} to prepare.'
                          : 'HPJ has your planned need.',
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 20,
                        height: 1.08,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 14),
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: FarmColors.background,
                        borderRadius: BorderRadius.circular(15),
                        border: Border.all(
                          color: FarmColors.line,
                        ),
                      ),
                      child: Column(
                        children: [
                          _WholesaleValueRow(
                            label: 'Product',
                            value: productName,
                          ),
                          _WholesaleValueRow(
                            label: 'Quantity',
                            value: '$quantityLabel $unit',
                          ),
                          _WholesaleValueRow(
                            label: 'Need by',
                            value: _wholesaleSimpleDate(needByDate),
                          ),
                          _WholesaleValueRow(
                            label: 'Pattern',
                            value: '$frequencyLabel • $certaintyLabel',
                            showDivider: false,
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 12),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 2),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed: () =>
                        Navigator.of(context).pop(false),
                    child: const Text('Done'),
                  ),
                ),
                const SizedBox(width: 9),
                Expanded(
                  child: ElevatedButton(
                    onPressed: () =>
