class _WholesalePlanningSimpleCard
    extends StatelessWidget {
  final WholesaleDemandForecast forecast;
  final VoidCallback onChanged;

  const _WholesalePlanningSimpleCard({
    required this.forecast,
    required this.onChanged,
  });

  String _date(DateTime date) {
    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return '${date.day} '
        '${months[date.month - 1]} '
        '${date.year}';
  }

  Future<void> _confirmStillNeeded(
    BuildContext context,
  ) async {
    try {
      await confirmWholesaleDemandForecastCurrent(
        forecast,
      );

      onChanged();

      if (!context.mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${forecast.productName} confirmed as still needed.',
          ),
        ),
      );
    } catch (error) {
      if (!context.mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    }
  }

  Future<void> _review(
    BuildContext context,
  ) async {
    final changed =
        await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) =>
          _WholesaleForecastReviewSheet(
        forecast: forecast,
      ),
    );

    if (changed == true) {
      onChanged();
    }
  }

  @override
  Widget build(BuildContext context) {
    final needsReview =
        _wholesaleForecastNeedsReview(
      forecast,
    );

    final daysToNeed =
        _wholesaleForecastDaysToNeed(
      forecast,
    );

    final dueMessage = daysToNeed < 0
        ? 'Need date passed'
        : daysToNeed == 0
            ? 'Needed today'
            : daysToNeed <= 7
                ? 'Needed in $daysToNeed day${daysToNeed == 1 ? '' : 's'}'
                : _wholesaleForecastFreshnessLabel(
                    forecast,
                  );

    final showTiming = needsReview || daysToNeed <= 7;

    final statusLabel = needsReview
        ? 'Review'
        : forecast.isReserved
            ? 'Supply reserved'
            : forecast.isMatched
                ? 'Supply matched'
                : 'Planned';

    final statusColor =
        needsReview ? FarmColors.warning : FarmColors.primary;

    return FarmCard(
      padding: const EdgeInsets.all(14),
      child: Column(
        crossAxisAlignment:
            CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              HpjProductThumb(
                productId: forecast.productId,
                productName: forecast.productName,
                size: 74,
                radius: 14,
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Expanded(
                          child: Text(
                            forecast.productName,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: FarmColors.ink,
                              fontSize: 15,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                        const SizedBox(width: 6),
                        Text(
                          statusLabel,
                          style: TextStyle(
                            color: statusColor,
                            fontSize: 9.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    Text(
                      forecast.formattedQuantity,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 12.3,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      'Need by ${_date(forecast.needByDate)}',
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10.4,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      '${forecast.frequencyLabel} • ${forecast.certaintyLabel}',
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10.2,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),

          if (showTiming) ...[
            const SizedBox(height: 10),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(
                horizontal: 10,
                vertical: 8,
              ),
              decoration: BoxDecoration(
                color: needsReview
                    ? const Color(0xFFFFF7E8)
                    : FarmColors.background,
                borderRadius:
                    BorderRadius.circular(12),
                border: Border.all(
                  color: needsReview
                      ? FarmColors.warning.withOpacity(
                          0.28,
                        )
                      : FarmColors.line,
                ),
              ),
              child: Row(
                children: [
                  Icon(
                    needsReview
                        ? Icons.schedule_outlined
                        : Icons.event_available_outlined,
                    color: needsReview
                        ? FarmColors.warning
                        : FarmColors.primary,
                    size: 16,
                  ),
                  const SizedBox(width: 7),
                  Expanded(
                    child: Text(
                      dueMessage,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 9.7,
                        height: 1.25,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],

          if (forecast.isForecast) ...[
            const SizedBox(height: 9),

            if (needsReview && daysToNeed >= 0)
              Row(
                children: [
                  Expanded(
                    child: ElevatedButton.icon(
                      icon: const Icon(
                        Icons.check_rounded,
                        size: 17,
                      ),
                      label: const Text(
                        'Still Needed',
                      ),
                      onPressed: () =>
                          _confirmStillNeeded(
                        context,
                      ),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: OutlinedButton(
                      onPressed: () =>
                          _review(context),
                      child: const Text(
                        'Review',
                      ),
                    ),
                  ),
                ],
              )
            else
              Align(
                alignment: Alignment.centerRight,
                child: TextButton.icon(
                  onPressed: () =>
                      _review(context),
                  icon: const Icon(
                    Icons.edit_outlined,
                    size: 16,
                  ),
                  label: Text(
                    needsReview ? 'Review' : 'Edit plan',
                  ),
                ),
              ),
          ],
        ],
      ),
    );
  }
}

class _WholesaleForecastReviewSheet
    extends StatefulWidget {
  final WholesaleDemandForecast forecast;

  const _WholesaleForecastReviewSheet({
    required this.forecast,
  });

  @override
  State<_WholesaleForecastReviewSheet>
      createState() =>
          _WholesaleForecastReviewSheetState();
}

class _WholesaleForecastReviewSheetState
    extends State<_WholesaleForecastReviewSheet> {
  late final TextEditingController
      quantityController;
  late final TextEditingController
      notesController;

  late DateTime needByDate;
  late String frequency;
  late String certainty;

  bool saving = false;
  bool cancelling = false;

  WholesaleDemandForecast get forecast =>
      widget.forecast;

  @override
  void initState() {
    super.initState();

    quantityController = TextEditingController(
      text: forecast.quantity ==
              forecast.quantity.roundToDouble()
          ? forecast.quantity.toStringAsFixed(0)
          : forecast.quantity.toStringAsFixed(1),
    );

    notesController = TextEditingController(
      text: forecast.notes,
    );

    needByDate = forecast.needByDate;
    frequency = forecast.frequency;
    certainty = forecast.certainty;
  }

  @override
  void dispose() {
    quantityController.dispose();
    notesController.dispose();
    super.dispose();
  }

  Future<void> _chooseDate() async {
    final now = DateTime.now();

    final selected = await showDatePicker(
      context: context,
      initialDate:
          needByDate.isBefore(now)
              ? now.add(
                  const Duration(days: 7),
                )
              : needByDate,
      firstDate: now,
      lastDate: now.add(
        const Duration(days: 730),
      ),
    );

    if (!mounted || selected == null) return;

    setState(() {
      needByDate = selected;
    });
  }

  Future<void> _save() async {
    if (saving || cancelling) return;

    final quantity = double.tryParse(
      quantityController.text.trim(),
    );

    if (quantity == null || quantity <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Enter a valid quantity.',
          ),
        ),
      );
      return;
    }

    setState(() {
      saving = true;
    });

    try {
      await updateWholesaleDemandForecast(
        forecast: forecast,
        productId: forecast.productId,
        productName: forecast.productName,
        category: forecast.category,
        quantity: quantity,
        unit: forecast.unit,
        needByDate: needByDate,
        frequency: frequency,
        certainty: certainty,
        notes: notesController.text,
      );

      if (!mounted) return;

      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;

      setState(() {
        saving = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    }
  }

  Future<void> _cancel() async {
    if (saving || cancelling) return;

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text(
            'Cancel this future need?',
          ),
          content: Text(
            '${forecast.productName} will be removed from active Planning Ahead.',
          ),
          actions: [
            TextButton(
              onPressed: () =>
                  Navigator.of(dialogContext)
                      .pop(false),
              child: const Text('Keep'),
            ),
            TextButton(
              onPressed: () =>
                  Navigator.of(dialogContext)
                      .pop(true),
              child: const Text(
                'Cancel requirement',
              ),
            ),
          ],
        );
      },
    );

    if (confirmed != true || !mounted) return;

    setState(() {
      cancelling = true;
    });

    try {
      await cancelWholesaleDemandForecast(
        forecast.id,
      );

      if (!mounted) return;

      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;

      setState(() {
        cancelling = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    }
  }

  String _dateLabel(DateTime date) {
    return '${date.year}-'
        '${date.month.toString().padLeft(2, '0')}-'
        '${date.day.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    final busy = saving || cancelling;

    return AnimatedPadding(
      duration:
          const Duration(milliseconds: 160),
      curve: Curves.easeOut,
      padding: EdgeInsets.only(
        bottom:
            MediaQuery.of(context).viewInsets.bottom,
