      child: Container(
        decoration: const BoxDecoration(
          color: FarmColors.card,
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(26),
          ),
        ),
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(
            18,
            14,
            18,
            22,
          ),
          child: Column(
            crossAxisAlignment:
                CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: FarmColors.line,
                    borderRadius:
                        BorderRadius.circular(99),
                  ),
                ),
              ),

              const SizedBox(height: 16),

              Text(
                forecast.productName,
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 4),

              const Text(
                'Keep this future need current so HPJ can plan sourcing against reliable information.',
                style: TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.5,
                  height: 1.35,
                  fontWeight: FontWeight.w600,
                ),
              ),

              const SizedBox(height: 16),

              TextField(
                controller: quantityController,
                enabled: !busy,
                keyboardType:
                    const TextInputType.numberWithOptions(
                  decimal: true,
                ),
                decoration: InputDecoration(
                  labelText: 'Quantity',
                  suffixText: forecast.unit,
                ),
              ),

              const SizedBox(height: 12),

              InkWell(
                onTap: busy ? null : _chooseDate,
                borderRadius:
                    BorderRadius.circular(16),
                child: InputDecorator(
                  decoration: const InputDecoration(
                    labelText: 'Need by',
                    suffixIcon: Icon(
                      Icons.calendar_month_outlined,
                    ),
                  ),
                  child: Text(
                    _dateLabel(needByDate),
                    style: const TextStyle(
                      color: FarmColors.ink,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                ),
              ),

              const SizedBox(height: 14),

              const Text(
                'Frequency',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 11,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 7),

              Wrap(
                spacing: 7,
                runSpacing: 7,
                children: [
                  for (final option
                      in const <MapEntry<String, String>>[
                    MapEntry('one_time', 'One time'),
                    MapEntry('weekly', 'Weekly'),
                    MapEntry('biweekly', 'Every 2 weeks'),
                    MapEntry('monthly', 'Monthly'),
                  ])
                    ChoiceChip(
                      label: Text(option.value),
                      selected:
                          frequency == option.key,
                      onSelected: busy
                          ? null
                          : (_) {
                              setState(() {
                                frequency =
                                    option.key;
                              });
                            },
                    ),
                ],
              ),

              const SizedBox(height: 14),

              const Text(
                'Confidence',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 11,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 7),

              Wrap(
                spacing: 7,
                runSpacing: 7,
                children: [
                  for (final option
                      in const <MapEntry<String, String>>[
