class _AdminWholesaleManagementTabState
    extends State<AdminWholesaleManagementTab> {
  late Future<List<BusinessAccount>> accountsFuture;
  late Future<List<WholesaleProduct>> productsFuture;
  late Future<List<WholesaleOrderRequest>> requestsFuture;
  late Future<List<WholesaleDemandForecast>> demandFuture;
  late Future<List<FarmerSupplyForecast>> farmerSupplyFuture;
  late Future<List<SupplyDemandAllocation>> allocationsFuture;

  late Future<List<WholesaleReceivingBatch>> receivingFuture;
  late Future<List<WholesaleFulfillment>> fulfillmentFuture;
  late Future<List<WholesaleDispatch>> dispatchFuture;
  late Future<List<WholesaleInvoice>> invoicesFuture;
  late Future<List<WholesalePaymentSubmission>> paymentSubmissionsFuture;
  late Future<List<WholesaleStandingOrder>> standingOrdersFuture;
  late Future<List<WholesaleDeliveryStaff>> deliveryStaffFuture;
  late Future<List<FarmerProfile>> farmerProfilesFuture;
  late Future<_WholesaleProcurementSnapshot> procurementFuture;

  String demandFilter = 'active';

  @override
  void initState() {
    super.initState();
    _reloadAll();
  }
// =====================================================
// DISPATCH HELPERS
// =====================================================

  String _dispatchScheduleLabel(
    DateTime? value,
  ) {
    if (value == null) {
      return 'Not scheduled';
    }

    final date = value.toLocal();

    final hour = date.hour == 0
        ? 12
        : date.hour > 12
            ? date.hour - 12
            : date.hour;

    final minute = date.minute.toString().padLeft(
          2,
          '0',
        );

    final period = date.hour >= 12 ? 'PM' : 'AM';

    return '${date.day}/${date.month}/${date.year} '
        '$hour:$minute $period';
  }

  Color _dispatchStatusColor(
    WholesaleDispatch dispatch,
  ) {
    if (dispatch.isComplete) {
      return FarmColors.green;
    }

    if (dispatch.isOutForDelivery) {
      return FarmColors.primary;
    }

    if (dispatch.isAssigned || dispatch.isReadyForPickup) {
      return FarmColors.green;
    }

    if (dispatch.isCancelled) {
      return FarmColors.danger;
    }

    return FarmColors.warning;
  }

// =====================================================
// CREATE DISPATCH
// =====================================================

  Future<void> _openCreateDispatchSheet(
    WholesaleFulfillment fulfillment,
  ) async {
    String method = 'hpj_delivery';

    DateTime? scheduledFor;

    bool saving = false;

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (
            context,
            setSheetState,
          ) {
            Future<void> chooseSchedule() async {
              final now = DateTime.now();

              final date = await showDatePicker(
                context: sheetContext,
                initialDate: scheduledFor ??
                    now.add(
                      const Duration(
                        days: 1,
                      ),
                    ),
                firstDate: DateTime(
                  now.year,
                  now.month,
                  now.day,
                ),
                lastDate: DateTime(
                  now.year + 2,
                ),
              );

              if (date == null || !sheetContext.mounted) {
                return;
              }

              final time = await showTimePicker(
                context: sheetContext,
                initialTime: const TimeOfDay(
                  hour: 9,
                  minute: 0,
                ),
              );

              if (time == null) {
                return;
              }

              setSheetState(() {
                scheduledFor = DateTime(
                  date.year,
                  date.month,
                  date.day,
                  time.hour,
                  time.minute,
                );
              });
            }

            Future<void> save() async {
              if (saving) {
                return;
              }

              setSheetState(() {
                saving = true;
              });

              try {
                await createWholesaleDispatch(
                  fulfillment: fulfillment,
                  dispatchMethod: method,
                  scheduledFor: scheduledFor,
                );

                if (!sheetContext.mounted) {
                  return;
                }

                Navigator.pop(
                  sheetContext,
                );

                await _refresh();

                if (!mounted) {
                  return;
                }

                ScaffoldMessenger.of(
                  context,
                ).showSnackBar(
                  const SnackBar(
                    content: Text(
                      'Wholesale dispatch created.',
                    ),
                  ),
                );
              } catch (error) {
                if (!sheetContext.mounted) {
                  return;
                }

                setSheetState(() {
                  saving = false;
                });

                ScaffoldMessenger.of(
                  sheetContext,
                ).showSnackBar(
                  SnackBar(
                    content: Text(
                      friendlyAppError(
                        error,
                      ),
                    ),
                  ),
                );
              }
            }

            return Padding(
              padding: EdgeInsets.only(
                left: 14,
                right: 14,
                bottom: MediaQuery.of(
                      sheetContext,
                    ).viewInsets.bottom +
                    14,
              ),
              child: Container(
                padding: const EdgeInsets.all(
                  18,
                ),
                decoration: const BoxDecoration(
                  color: FarmColors.background,
                  borderRadius: BorderRadius.vertical(
                    top: Radius.circular(
                      26,
                    ),
                  ),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Create Dispatch',
                      style: TextStyle(
                        color: FarmColors.ink,
                        fontSize: 20,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(
                      height: 16,
                    ),
                    DropdownButtonFormField<String>(
                      value: method,
                      decoration: const InputDecoration(
                        labelText: 'Dispatch method',
                      ),
                      items: const [
                        DropdownMenuItem(
                          value: 'hpj_delivery',
                          child: Text(
                            'HPJ Delivery',
                          ),
                        ),
                        DropdownMenuItem(
                          value: 'business_collection',
                          child: Text(
                            'Business Collection',
                          ),
                        ),
                      ],
                      onChanged: saving
                          ? null
                          : (value) {
                              if (value == null) {
                                return;
                              }

                              setSheetState(
                                () {
                                  method = value;
                                },
                              );
                            },
                    ),
                    const SizedBox(
                      height: 12,
                    ),
                    InkWell(
                      onTap: saving ? null : chooseSchedule,
                      borderRadius: BorderRadius.circular(
                        14,
                      ),
                      child: InputDecorator(
                        decoration: const InputDecoration(
                          labelText: 'Schedule',
                          suffixIcon: Icon(
                            Icons.calendar_month_outlined,
                          ),
                        ),
                        child: Text(
                          _dispatchScheduleLabel(
                            scheduledFor,
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(
                      height: 16,
                    ),
                    SizedBox(
                      width: double.infinity,
                      child: ElevatedButton.icon(
                        onPressed: saving ? null : save,
                        icon: const Icon(
                          Icons.local_shipping_outlined,
                        ),
                        label: Text(
                          saving ? 'Creating...' : 'Create Dispatch',
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

// =====================================================
// ASSIGN DRIVER
// =====================================================

  Future<void> _assignDispatchDriver(
    WholesaleDispatch dispatch,
  ) async {
    try {
      final drivers = await deliveryStaffFuture;

      if (!mounted) {
        return;
      }

      if (drivers.isEmpty) {
        throw Exception(
          'No active Delivery staff are available. Add a Delivery staff member first.',
        );
      }

      String? selectedDriver = dispatch.assignedDriverId;

      final saved = await showDialog<bool>(
        context: context,
        builder: (
          dialogContext,
        ) {
          return StatefulBuilder(
            builder: (
              context,
              setDialogState,
            ) {
              return AlertDialog(
                title: const Text(
                  'Assign Driver',
                ),
                content: DropdownButtonFormField<String>(
                  value: drivers.any(
                    (driver) => driver.userId == selectedDriver,
                  )
                      ? selectedDriver
                      : null,
                  isExpanded: true,
                  decoration: const InputDecoration(
                    labelText: 'Delivery staff',
                  ),
                  items: drivers
                      .map(
                        (driver) => DropdownMenuItem<String>(
                          value: driver.userId,
                          child: Text(
                            driver.displayName,
                          ),
                        ),
                      )
                      .toList(),
                  onChanged: (value) {
                    setDialogState(
                      () {
                        selectedDriver = value;
                      },
                    );
                  },
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(
                      dialogContext,
                      false,
                    ),
                    child: const Text(
                      'Back',
                    ),
                  ),
                  ElevatedButton(
                    onPressed: () => Navigator.pop(
                      dialogContext,
                      true,
                    ),
                    child: const Text(
                      'Assign',
                    ),
                  ),
                ],
              );
            },
          );
        },
      );

      if (saved != true) {
        return;
      }

      final driverId = selectedDriver?.trim() ?? '';

      if (driverId.isEmpty) {
        throw Exception(
          'Select a driver.',
        );
      }

      await assignWholesaleDispatchDriver(
        dispatch: dispatch,
        driverUserId: driverId,
      );

      await _refresh();

      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Driver assigned.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(
              error,
            ),
          ),
        ),
      );
    }
  }

