// =====================================================
// COMPLETE DELIVERY OR COLLECTION
// =====================================================

  Future<void> _completeDispatch(
    WholesaleDispatch dispatch,
  ) async {
    final recipientController = TextEditingController();

    final proofController = TextEditingController();

    String proofPhotoUrl = '';

    bool uploadingPhoto = false;
    bool saving = false;

    await showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (
        dialogContext,
      ) {
        return StatefulBuilder(
          builder: (
            context,
            setDialogState,
          ) {
            Future<void> capturePhoto() async {
              if (uploadingPhoto || saving) {
                return;
              }

              setDialogState(() {
                uploadingPhoto = true;
              });

              try {
                final url = await captureWholesaleDispatchProofPhoto(
                  dispatch,
                );

                if (!dialogContext.mounted) {
                  return;
                }

                setDialogState(() {
                  proofPhotoUrl = url;
                  uploadingPhoto = false;
                });
              } catch (error) {
                if (!dialogContext.mounted) {
                  return;
                }

                setDialogState(() {
                  uploadingPhoto = false;
                });

                ScaffoldMessenger.of(
                  dialogContext,
                ).showSnackBar(
                  SnackBar(
                    content: Text(
                      friendlyAppError(
                        error,
                      ),
                    ),
                  ),
                );
              }
            }

            Future<void> complete() async {
              if (saving) {
                return;
              }

              final recipient = recipientController.text.trim();

              if (recipient.isEmpty) {
                ScaffoldMessenger.of(
                  dialogContext,
                ).showSnackBar(
                  const SnackBar(
                    content: Text(
                      'Enter the recipient or collector name.',
                    ),
                  ),
                );

                return;
              }

              setDialogState(() {
                saving = true;
              });

              try {
                if (dispatch.isHpjDelivery) {
                  await completeWholesaleDelivery(
                    dispatch: dispatch,
                    recipientName: recipient,
                    proofNote: proofController.text,
                    proofPhotoPath: proofPhotoUrl,
                  );
                } else {
                  await completeWholesaleBusinessCollection(
                    dispatch: dispatch,
                    recipientName: recipient,
                    proofNote: proofController.text,
                    proofPhotoPath: proofPhotoUrl,
                  );
                }

                if (!dialogContext.mounted) {
                  return;
                }

                Navigator.pop(
                  dialogContext,
                );

                await _refresh();

                widget.onChanged();

                if (!mounted) return;

                ScaffoldMessenger.of(
                  context,
                ).showSnackBar(
                  SnackBar(
                    content: Text(
                      dispatch.isHpjDelivery
                          ? 'Wholesale delivery completed.'
                          : 'Wholesale collection completed.',
                    ),
                  ),
                );
              } catch (error) {
                if (!dialogContext.mounted) {
                  return;
                }

                setDialogState(() {
                  saving = false;
                });

                ScaffoldMessenger.of(
                  dialogContext,
                ).showSnackBar(
                  SnackBar(
                    content: Text(
                      friendlyAppError(
                        error,
                      ),
                    ),
                  ),
                );
              }
            }

            return AlertDialog(
              title: Text(
                dispatch.isHpjDelivery
                    ? 'Complete Delivery'
                    : 'Complete Collection',
              ),
              content: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    TextField(
                      controller: recipientController,
                      enabled: !saving,
                      decoration: InputDecoration(
                        labelText: dispatch.isHpjDelivery
                            ? 'Received by'
                            : 'Collected by',
                      ),
                    ),
                    const SizedBox(
                      height: 12,
                    ),
                    TextField(
                      controller: proofController,
                      enabled: !saving,
                      minLines: 2,
                      maxLines: 3,
                      decoration: const InputDecoration(
                        labelText: 'Proof / delivery note',
                      ),
                    ),
                    const SizedBox(
                      height: 12,
                    ),
                    SizedBox(
                      width: double.infinity,
                      child: OutlinedButton.icon(
                        onPressed:
                            saving || uploadingPhoto ? null : capturePhoto,
                        icon: Icon(
                          proofPhotoUrl.isNotEmpty
                              ? Icons.check_circle_outline
                              : Icons.camera_alt_outlined,
                        ),
                        label: Text(
                          uploadingPhoto
                              ? 'Uploading...'
                              : proofPhotoUrl.isNotEmpty
                                  ? 'Proof Photo Added'
                                  : 'Capture Proof Photo',
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: saving
                      ? null
                      : () => Navigator.pop(
                            dialogContext,
                          ),
                  child: const Text(
                    'Back',
                  ),
                ),
                ElevatedButton(
                  onPressed: saving ? null : complete,
                  child: Text(
                    saving
                        ? 'Saving...'
                        : dispatch.isHpjDelivery
                            ? 'Confirm Delivered'
                            : 'Confirm Collected',
                  ),
                ),
              ],
            );
          },
        );
      },
    );

    recipientController.dispose();
    proofController.dispose();
  }

// =====================================================
// CANCEL DISPATCH
// =====================================================

  Future<void> _cancelDispatch(
    WholesaleDispatch dispatch,
  ) async {
    final controller = TextEditingController();

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (
        dialogContext,
      ) {
        return AlertDialog(
          title: const Text(
            'Cancel Dispatch?',
          ),
          content: TextField(
            controller: controller,
            minLines: 2,
            maxLines: 3,
            decoration: const InputDecoration(
              labelText: 'Reason',
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                false,
              ),
              child: const Text(
                'Back',
              ),
            ),
            TextButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                true,
              ),
              child: const Text(
                'Cancel Dispatch',
              ),
            ),
          ],
        );
      },
    );

    if (confirmed != true) {
      controller.dispose();
      return;
    }

    try {
      await cancelWholesaleDispatch(
        dispatch: dispatch,
        reason: controller.text,
      );

      await _refresh();

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Dispatch cancelled.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    } finally {
      controller.dispose();
    }
  }

  @override
  void didUpdateWidget(covariant AdminWholesaleManagementTab oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.refreshKey != widget.refreshKey) {
      _reloadAll();
    }
  }

  void _reloadAll() {
    accountsFuture = fetchAdminBusinessAccounts();
    dispatchFuture = fetchAdminWholesaleDispatches(
      includeCancelled: true,
    );

    deliveryStaffFuture = fetchWholesaleDeliveryStaff();
    productsFuture = fetchAdminWholesaleProducts();

    requestsFuture = fetchAdminWholesaleRequests();

    demandFuture = fetchAdminWholesaleDemandForecasts();
    invoicesFuture = fetchAdminWholesaleInvoices();
    paymentSubmissionsFuture = fetchAdminWholesalePaymentSubmissions();
    standingOrdersFuture = fetchAdminWholesaleStandingOrders();
    farmerSupplyFuture = fetchAdminFarmerSupplyForecasts();
    fulfillmentFuture = fetchAdminWholesaleFulfillments();
    farmerProfilesFuture = fetchFarmerProfiles();
    allocationsFuture = fetchSupplyDemandAllocations(
      includeInactive: true,
    );

    receivingFuture = fetchWholesaleReceivingBatches();

    procurementFuture = Future.wait<dynamic>([
      demandFuture,
      accountsFuture,
      farmerSupplyFuture,
      farmerProfilesFuture,
      allocationsFuture,
      requestsFuture,
      fulfillmentFuture,
      fetchWarehousePickQueue(),
      fetchWarehouseSupplierPerformance(),
    ]).then((values) {
      return _WholesaleProcurementSnapshot(
        demands: values[0] as List<WholesaleDemandForecast>,
        accounts: values[1] as List<BusinessAccount>,
        supplies: values[2] as List<FarmerSupplyForecast>,
        farmers: values[3] as List<FarmerProfile>,
        allocations: values[4] as List<SupplyDemandAllocation>,
        requests: values[5] as List<WholesaleOrderRequest>,
        fulfillments: values[6] as List<WholesaleFulfillment>,
        warehouseReservations: values[7] as List<WarehousePickQueueRow>,
        supplierPerformance:
            values[8] as List<WarehouseSupplierPerformanceRow>,
      );
    });
  }

  Future<void> _refresh() async {
    setState(_reloadAll);

    await Future.wait<Object>([
      accountsFuture,
      productsFuture,
      requestsFuture,
      demandFuture,
      farmerSupplyFuture,
      farmerProfilesFuture,
      allocationsFuture,
      receivingFuture,
      fulfillmentFuture,
      dispatchFuture,
      invoicesFuture,
      paymentSubmissionsFuture,
      standingOrdersFuture,
      deliveryStaffFuture,
      procurementFuture,
    ]);
  }

  Future<void> _changeBusinessStatus(
    BusinessAccount account,
    String status,
  ) async {
    final notesController = TextEditingController(text: account.adminNotes);

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: Text('${businessAccountStatusLabel(status)} account'),
        content: TextField(
          controller: notesController,
          maxLines: 3,
          decoration: const InputDecoration(
            labelText: 'Admin note (optional)',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text('Confirm'),
          ),
        ],
      ),
    );

    if (confirmed != true) {
      notesController.dispose();
      return;
    }

    try {
      await adminUpdateBusinessStatus(
        account: account,
        status: status,
        adminNotes: notesController.text,
      );
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${account.displayName} updated to ${businessAccountStatusLabel(status)}.',
          ),
        ),
      );
      widget.onChanged();
      await _refresh();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      notesController.dispose();
    }
  }

  Future<void> _editWholesaleProduct(WholesaleProduct item) async {
    final priceController = TextEditingController(
      text:
          item.wholesalePrice > 0 ? item.wholesalePrice.toStringAsFixed(0) : '',
    );
    final minimumController = TextEditingController(
      text: item.minimumQuantity.toString(),
    );
    final unitController = TextEditingController(text: item.wholesaleUnit);
    bool enabled = item.wholesaleEnabled;

    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          return AlertDialog(
            title: Text(item.product.name),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  SwitchListTile.adaptive(
                    contentPadding: EdgeInsets.zero,
                    title: const Text('Enable wholesale pricing'),
                    value: enabled,
                    onChanged: (value) {
                      setDialogState(() => enabled = value);
                    },
                  ),
                  TextField(
                    controller: priceController,
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(
                      labelText: 'Wholesale price (J\$)',
                    ),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: minimumController,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'Minimum quantity',
                    ),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: unitController,
                    decoration: const InputDecoration(
                      labelText: 'Wholesale unit',
                      hintText: 'lb, crate, case, dozen, tray',
                    ),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop(false),
                child: const Text('Cancel'),
              ),
              ElevatedButton(
                onPressed: () => Navigator.of(dialogContext).pop(true),
                child: const Text('Save'),
              ),
            ],
          );
        },
      ),
    );

    if (saved != true) {
      priceController.dispose();
      minimumController.dispose();
      unitController.dispose();
      return;
    }

    try {
      await adminSaveWholesaleProduct(
        item: item,
        enabled: enabled,
        wholesalePrice: double.tryParse(
              priceController.text.trim().replaceAll(',', ''),
            ) ??
            0,
        minimumQuantity: int.tryParse(minimumController.text.trim()) ?? 1,
        wholesaleUnit: unitController.text,
      );

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Wholesale pricing updated.')),
      );
      widget.onChanged();
      await _refresh();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      priceController.dispose();
      minimumController.dispose();
      unitController.dispose();
    }
  }

  Future<void> _updateRequest(WholesaleOrderRequest request) async {
    String status = request.status;
    final quoteController = TextEditingController(
      text: request.quotedTotal == null
          ? ''
          : request.quotedTotal!.toStringAsFixed(0),
    );
    final notesController = TextEditingController(text: request.adminNotes);

    const statuses = <String>[
      'pending',
      'quoted',
      'approved',
      'rejected',
      'cancelled',
    ];

    final isDeliveredOrder =
        request.status.trim().toLowerCase() == 'fulfilled';

    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (context, setDialogState) {
          return AlertDialog(
            title: Text('Request #${request.shortId}'),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (isDeliveredOrder)
                    const InputDecorator(
                      decoration: InputDecoration(
                        labelText: 'Order status',
                      ),
                      child: Text(
                        'DELIVERED / FULFILLED',
                        style: TextStyle(
                          color: FarmColors.green,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    )
                  else
                    DropdownButtonFormField<String>(
                      value: statuses.contains(status) ? status : 'pending',
                      decoration:
                          const InputDecoration(labelText: 'Order status'),
                      items: statuses
                          .map(
                            (item) => DropdownMenuItem<String>(
                              value: item,
                              child: Text(
                                item.replaceAll('_', ' ').toUpperCase(),
                              ),
                            ),
                          )
                          .toList(),
                      onChanged: (value) {
                        if (value != null) {
                          setDialogState(() => status = value);
                        }
                      },
                    ),
                  const SizedBox(height: 7),
                  Text(
                    isDeliveredOrder
                        ? 'Delivery is complete. This status is controlled by Fulfillment.'
                        : 'Delivery completion is recorded under Fulfillment → Wholesale → Delivery.',
                    style: const TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 10,
                      height: 1.3,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: quoteController,
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(
                      labelText: 'Quoted total (J\$)',
                    ),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: notesController,
                    maxLines: 3,
                    decoration:
                        const InputDecoration(labelText: 'Customer note'),
                  ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop(false),
                child: const Text('Cancel'),
              ),
              ElevatedButton(
                onPressed: () => Navigator.of(dialogContext).pop(true),
                child: const Text('Save Update'),
              ),
            ],
          );
        },
      ),
    );

    if (saved != true) {
      quoteController.dispose();
      notesController.dispose();
      return;
    }

    try {
      await adminUpdateWholesaleRequest(
        request: request,
        status: status,
        quotedTotal: double.tryParse(
          quoteController.text.trim().replaceAll(',', ''),
        ),
        adminNotes: notesController.text,
      );

      String? procurementWarning;
      if (status == 'approved') {
        try {
          await prepareApprovedWholesaleRequestForProcurement(
            request.id,
          );
        } catch (error) {
          farmDebugLog(
            'Wholesale request approved but warehouse-first procurement prep needs attention: $error',
          );
          procurementWarning =
              'Order approved. Open Procurement to review warehouse stock and sourcing.';
        }
      }

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            procurementWarning ?? 'Wholesale request updated.',
          ),
        ),
      );
      widget.onChanged();
      await _refresh();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      quoteController.dispose();
      notesController.dispose();
    }
  }

  // =====================================================
  // PHASE 3P — EDIT BUSINESS CREDIT TERMS
