  Future<void> _editBusinessCreditTerms(
    BusinessAccount account,
  ) async {
    bool creditEnabled = account.wholesaleCreditEnabled;
    String creditStatus =
        account.wholesaleCreditStatus == 'hold' ? 'hold' : 'active';

    final limitController = TextEditingController(
      text: account.wholesaleCreditLimit > 0
          ? account.wholesaleCreditLimit.toStringAsFixed(2)
          : '0',
    );
    final termsController = TextEditingController(
      text: account.wholesalePaymentTermsDays.toString(),
    );
    final noteController = TextEditingController(
      text: account.wholesaleCreditNote,
    );

    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return StatefulBuilder(
          builder: (context, setDialogState) {
            return AlertDialog(
              title: Text('Credit Terms • ${account.displayName}'),
              content: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SwitchListTile.adaptive(
                      contentPadding: EdgeInsets.zero,
                      title: const Text('Allow wholesale credit'),
                      subtitle: const Text(
                        'Off means invoices are due when issued.',
                      ),
                      value: creditEnabled,
                      onChanged: (value) {
                        setDialogState(() => creditEnabled = value);
                      },
                    ),
                    const SizedBox(height: 8),
                    DropdownButtonFormField<String>(
                      value: creditStatus,
                      decoration: const InputDecoration(
                        labelText: 'Credit status',
                      ),
                      items: const [
                        DropdownMenuItem(
                          value: 'active',
                          child: Text('Active'),
                        ),
                        DropdownMenuItem(
                          value: 'hold',
                          child: Text('Credit Hold'),
                        ),
                      ],
                      onChanged: creditEnabled
                          ? (value) {
                              if (value != null) {
                                setDialogState(() => creditStatus = value);
                              }
                            }
                          : null,
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: limitController,
                      enabled: creditEnabled,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: 'Credit limit',
                        prefixText: 'J\$ ',
                        helperText: '0 = no hard limit',
                      ),
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: termsController,
                      enabled: creditEnabled,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(
                        labelText: 'Payment terms',
                        suffixText: 'days',
                      ),
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: noteController,
                      minLines: 2,
                      maxLines: 4,
                      decoration: const InputDecoration(
                        labelText: 'Credit note',
                        hintText:
                            'Optional account note visible to the business.',
                      ),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(dialogContext, false),
                  child: const Text('Back'),
                ),
                ElevatedButton(
                  onPressed: () => Navigator.pop(dialogContext, true),
                  child: const Text('Save Terms'),
                ),
              ],
            );
          },
        );
      },
    );

    if (saved != true) {
      limitController.dispose();
      termsController.dispose();
      noteController.dispose();
      return;
    }

    final limit = double.tryParse(
      limitController.text.trim().replaceAll(',', ''),
    );
    final terms = int.tryParse(termsController.text.trim());

    if (limit == null ||
        limit < 0 ||
        terms == null ||
        terms < 0 ||
        terms > 365) {
      limitController.dispose();
      termsController.dispose();
      noteController.dispose();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Check the credit limit and payment terms.'),
        ),
      );
      return;
    }

    try {
      await adminUpdateWholesaleCreditTerms(
        account: account,
        creditEnabled: creditEnabled,
        creditLimit: limit,
        paymentTermsDays: terms,
        creditStatus: creditStatus,
        creditNote: noteController.text,
      );

      await _refresh();
      widget.onChanged();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Wholesale credit terms updated.')),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      limitController.dispose();
      termsController.dispose();
      noteController.dispose();
    }
  }

