  String _demandDateLabel(
    DateTime date,
  ) {
    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return '${date.day} '
        '${months[date.month - 1]} '
        '${date.year}';
  }

  Color _demandStatusColor(
    WholesaleDemandForecast forecast,
  ) {
    if (forecast.isReserved) {
      return FarmColors.success;
    }

    if (forecast.isMatched) {
      return FarmColors.primary;
    }

    if (forecast.isCancelled) {
      return FarmColors.danger;
    }

    if (forecast.isConverted) {
      return FarmColors.green;
    }

    return FarmColors.warning;
  }

  Future<void> _changeDemandStatus(
    WholesaleDemandForecast forecast,
    String status,
  ) async {
    final notesController = TextEditingController(
      text: forecast.adminNotes,
    );

    final labels = <String, String>{
      'forecast': 'Return to Forecast',
      'matched': 'Mark as Matched',
      'reserved': 'Reserve Supply',
      'cancelled': 'Cancel Requirement',
    };

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: Text(
            labels[status] ?? 'Update Requirement',
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                '${forecast.productName} • '
                '${forecast.formattedQuantity}',
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(
                height: 14,
              ),
              TextField(
                controller: notesController,
                maxLines: 3,
                decoration: const InputDecoration(
                  labelText: 'Admin note (optional)',
                  hintText: 'Add a short internal/customer note',
                ),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                false,
              ),
              child: const Text('Back'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                true,
              ),
              child: const Text('Confirm'),
            ),
          ],
        );
      },
    );

    if (confirmed != true) {
      notesController.dispose();
      return;
    }

    try {
      await adminUpdateWholesaleDemandForecast(
        forecast: forecast,
        status: status,
        adminNotes: notesController.text,
      );

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${forecast.productName} updated.',
          ),
        ),
      );

      widget.onChanged();

      await _refresh();
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    } finally {
      notesController.dispose();
    }
  }

