  Widget _demandFilterChip(
    String value,
    String label,
  ) {
    final selected = demandFilter == value;

    return ChoiceChip(
      label: Text(label),
      selected: selected,
      onSelected: (_) {
        setState(() {
          demandFilter = value;
        });
      },
    );
  }

  Widget _demandTab() {
    return FutureBuilder<List<WholesaleDemandForecast>>(
      future: demandFuture,
      builder: (
        context,
        demandSnapshot,
      ) {
        if (demandSnapshot.connectionState == ConnectionState.waiting &&
            !demandSnapshot.hasData) {
          return const Center(
            child: CircularProgressIndicator(),
          );
        }

        final forecasts =
            demandSnapshot.data ?? const <WholesaleDemandForecast>[];

        return FutureBuilder<List<BusinessAccount>>(
          future: accountsFuture,
          builder: (
            context,
            accountSnapshot,
          ) {
            final accounts = accountSnapshot.data ?? const <BusinessAccount>[];

            final accountNames = <String, String>{
              for (final account in accounts) account.id: account.displayName,
            };

            final forecastCount = forecasts
                .where(
                  (item) => item.isForecast,
                )
                .length;

            final matchedCount = forecasts
                .where(
                  (item) => item.isMatched,
                )
                .length;

            final reservedCount = forecasts
                .where(
                  (item) => item.isReserved,
                )
                .length;

            final activeCount = forecasts
                .where(
                  (item) => item.isActive,
                )
                .length;

            final filtered = forecasts.where(
              (item) {
                switch (demandFilter) {
                  case 'forecast':
                    return item.isForecast;

                  case 'matched':
                    return item.isMatched;

                  case 'reserved':
                    return item.isReserved;

                  case 'all':
                    return true;

                  default:
                    return item.isActive;
                }
              },
            ).toList()
              ..sort(
                (a, b) => a.needByDate.compareTo(
                  b.needByDate,
                ),
              );

            return RefreshIndicator(
              onRefresh: _refresh,
              child: ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.fromLTRB(
                  14,
                  14,
                  14,
                  100,
                ),
                children: [
                  // -------------------------------------
                  // HEADER
                  // -------------------------------------

                  FarmCard(
                    padding: const EdgeInsets.all(
                      16,
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 44,
                          height: 44,
                          decoration: BoxDecoration(
                            color: FarmColors.primarySoft,
                            borderRadius: BorderRadius.circular(
                              14,
                            ),
                          ),
                          child: const Icon(
                            Icons.insights_outlined,
                            color: FarmColors.primary,
                          ),
                        ),
                        const SizedBox(
                          width: 12,
                        ),
                        const Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'Future Demand',
                                style: TextStyle(
                                  color: FarmColors.ink,
                                  fontSize: 17,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              SizedBox(
                                height: 3,
                              ),
                              Text(
                                'Upcoming wholesale requirements reported by approved businesses.',
                                style: TextStyle(
                                  color: FarmColors.mutedText,
                                  fontSize: 11,
                                  height: 1.3,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),

                  const SizedBox(
                    height: 12,
                  ),

                  // -------------------------------------
                  // STATS
                  // -------------------------------------

                  SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: Row(
                      children: [
                        _demandStat(
                          label: 'Active',
                          value: activeCount,
                        ),
                        const SizedBox(
                          width: 8,
                        ),
                        _demandStat(
                          label: 'Forecast',
