// =====================================================
// SUPPLY VS DEMAND MATCHING
// =====================================================

  String _normalizeMatchName(
    String value,
  ) {
    return _normalizeProcurementName(value);
  }

  String _normalizeMatchUnit(
    String value,
  ) {
    return _normalizeProcurementUnit(value);
  }

// =====================================================
// Best quantity currently known for a supply record.
//
// Priority:
// HPJ confirmed
// farmer harvested
// expected harvest
// quantity growing
// =====================================================

  double _supplyPotentialQuantity(
    FarmerSupplyForecast supply,
  ) {
    final confirmed = supply.hpjConfirmedQuantity ?? 0;

    if (confirmed > 0) {
      return confirmed;
    }

    final harvested = supply.harvestedQuantity ?? 0;

    if (harvested > 0) {
      return harvested;
    }

    final expected = supply.expectedQuantity ?? 0;

    if (expected > 0) {
      return expected;
    }

    return supply.quantityGrowing ?? 0;
  }

  double _supplyConfirmedQuantity(
    FarmerSupplyForecast supply,
  ) {
    return supply.hpjConfirmedQuantity ?? 0;
  }

// =====================================================
// Fresh produce planning window.
//
// Supply must be expected no more than 14 days
// before the business need-by date.
//
// Supply without a date is not counted as coverage.
// =====================================================

  bool _supplyFitsDemandDate(
    FarmerSupplyForecast supply,
    WholesaleDemandForecast demand,
  ) {
    final harvestDate = supply.expectedHarvestDate;

    if (harvestDate == null) {
      return false;
    }

    final needDate = DateTime(
      demand.needByDate.year,
      demand.needByDate.month,
      demand.needByDate.day,
    );

    final harvest = DateTime(
      harvestDate.year,
      harvestDate.month,
      harvestDate.day,
    );

    final earliest = needDate.subtract(
      const Duration(days: 14),
    );

    return !harvest.isBefore(earliest) && !harvest.isAfter(needDate);
  }

  String _matchQuantityLabel(
    double value,
    String unit,
  ) {
    final amount = value == value.roundToDouble()
        ? value.toInt().toString()
        : value.toStringAsFixed(1);

    return '$amount $unit';
  }

  Color _matchCoverageColor({
    required double confirmed,
    required double potential,
    required double demand,
  }) {
    if (confirmed >= demand && demand > 0) {
      return FarmColors.success;
    }

    if (potential >= demand && demand > 0) {
      return FarmColors.primary;
    }

    return FarmColors.warning;
  }

  String _matchCoverageLabel({
    required double confirmed,
    required double potential,
    required double demand,
  }) {
    if (confirmed >= demand && demand > 0) {
      return 'Covered';
    }

    if (potential >= demand && demand > 0) {
      return 'Potentially Covered';
    }

    return 'Supply Gap';
  }
  // =====================================================
// KEEP DEMAND STATUS IN SYNC WITH RESERVATIONS
// =====================================================

  Future<void> _syncDemandReservationStatus(
    WholesaleDemandForecast demand,
  ) async {
    final reserved = await fetchAllocatedDemandQuantity(
      demand.id,
    );

    String nextStatus;

    if (reserved <= 0) {
      nextStatus = 'forecast';
    } else if (reserved >= demand.quantity) {
      nextStatus = 'reserved';
    } else {
      nextStatus = 'matched';
    }

    if (demand.status == nextStatus) {
      return;
    }

    await adminUpdateWholesaleDemandForecast(
      forecast: demand,
      status: nextStatus,
      adminNotes: demand.adminNotes,
    );
  }
// =====================================================
// RESERVE CONFIRMED FARMER SUPPLY
// =====================================================

  Future<void> _openReserveSupplySheet({
    required WholesaleDemandForecast demand,
    required List<FarmerSupplyForecast> supplies,
    required Map<String, FarmerProfile> farmerMap,
    double? maximumAdditionalQuantity,
  }) async {
    if (supplies.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'No HPJ-confirmed farmer supply is available for this requirement.',
          ),
        ),
      );
      return;
    }

    try {
      // Existing active reservations for this demand.
      final demandAllocations = await fetchSupplyDemandAllocations(
        demandForecastId: demand.id,
      );

      final existingBySupply = <String, SupplyDemandAllocation>{
        for (final allocation in demandAllocations)
          allocation.supplyForecastId: allocation,
      };

      double demandReserved = 0;

      for (final allocation in demandAllocations) {
        demandReserved += allocation.allocatedQuantity;
      }

      // Total reserved from each farmer supply,
      // including allocations to other businesses.
      final allocatedTotals = <String, double>{};

      for (final supply in supplies) {
        allocatedTotals[supply.id] = await fetchAllocatedSupplyQuantity(
          supply.id,
        );
      }

      if (!mounted) return;

      FarmerSupplyForecast? selectedSupply;

      final quantityController = TextEditingController();

      final notesController = TextEditingController();

      bool saving = false;

      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (
              context,
              setSheetState,
            ) {
              double currentPairQuantity(
                FarmerSupplyForecast supply,
              ) {
                return existingBySupply[supply.id]?.allocatedQuantity ?? 0;
              }

              double maximumForSupply(
                FarmerSupplyForecast supply,
              ) {
                final confirmed = supply.hpjConfirmedQuantity ?? 0;

                final globallyAllocated = allocatedTotals[supply.id] ?? 0;

                final currentPair = currentPairQuantity(
                  supply,
                );

                // Remove this demand's existing allocation
                // before calculating what can be edited.
                final usedElsewhere = globallyAllocated - currentPair;

                final supplyAvailable = confirmed - usedElsewhere;

                final otherDemandReservations = demandReserved - currentPair;

                var demandAvailable =
                    demand.quantity - otherDemandReservations;

                // For real orders, warehouse stock and previously converted
                // Planning Ahead supply can already cover part of the line.
                // Limit manual farmer reservations to the remaining sourcing
                // requirement rather than the original order quantity.
                final extraCap = maximumAdditionalQuantity;
                if (extraCap != null) {
                  final operationalCap = currentPair + extraCap;
                  if (operationalCap < demandAvailable) {
                    demandAvailable = operationalCap;
                  }
                }

                final safeSupply = supplyAvailable < 0 ? 0.0 : supplyAvailable;

                final safeDemand = demandAvailable < 0 ? 0.0 : demandAvailable;

                return safeSupply < safeDemand ? safeSupply : safeDemand;
              }

              void chooseSupply(
                FarmerSupplyForecast supply,
              ) {
                final existing = currentPairQuantity(
                  supply,
                );

                final maximum = maximumForSupply(
                  supply,
                );

                double suggested;

                if (existing > 0) {
                  suggested = existing;
                } else {
                  final remaining = maximumAdditionalQuantity ??
                      (demand.quantity - demandReserved);

                  suggested = maximum < remaining ? maximum : remaining;
                }

                if (suggested < 0) {
                  suggested = 0;
                }

                quantityController.text = suggested == suggested.roundToDouble()
                    ? suggested.toInt().toString()
                    : suggested.toStringAsFixed(
                        1,
                      );

                setSheetState(() {
                  selectedSupply = supply;
                });
              }

              Future<void> reserve() async {
                if (saving) return;

                final supply = selectedSupply;

                if (supply == null) {
                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Choose a farmer supply first.',
                      ),
                    ),
                  );
                  return;
                }

                final quantity = double.tryParse(
                  quantityController.text.trim().replaceAll(
                        ',',
                        '',
                      ),
                );

                if (quantity == null || quantity <= 0) {
                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Enter a valid reservation quantity.',
                      ),
                    ),
                  );
                  return;
                }

                final maximum = maximumForSupply(
                  supply,
                );

                if (quantity > maximum) {
                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        'Maximum available for this reservation is '
                        '${_matchQuantityLabel(maximum, supply.unit)}.',
                      ),
                    ),
                  );
                  return;
                }

                setSheetState(() {
                  saving = true;
                });

                try {
                  await createSupplyDemandAllocation(
                    supply: supply,
                    demand: demand,
                    quantity: quantity,
                    adminNotes: notesController.text,
                  );

                  // Demand status is derived from real allocations.
                  await _syncDemandReservationStatus(
                    demand,
                  );

                  if (!sheetContext.mounted) {
                    return;
                  }

                  Navigator.pop(
                    sheetContext,
                  );

                  await _refresh();

                  if (!mounted) return;

                  ScaffoldMessenger.of(
                    context,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        '${_matchQuantityLabel(quantity, supply.unit)} reserved for ${demand.productName}.',
                      ),
                    ),
                  );
                } catch (error) {
                  if (!sheetContext.mounted) {
                    return;
                  }

                  setSheetState(() {
                    saving = false;
                  });

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        friendlyAppError(
                          error,
                        ),
                      ),
                    ),
                  );
                }
              }

              final selected = selectedSupply;

              return Padding(
                padding: EdgeInsets.only(
                  left: 14,
                  right: 14,
                  bottom: MediaQuery.of(
                        sheetContext,
                      ).viewInsets.bottom +
                      14,
                ),
                child: Container(
                  constraints: const BoxConstraints(
                    maxHeight: 650,
                  ),
                  padding: const EdgeInsets.fromLTRB(
                    18,
                    12,
                    18,
                    18,
                  ),
                  decoration: const BoxDecoration(
                    color: FarmColors.background,
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(
                        26,
                      ),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Center(
                        child: Container(
                          width: 42,
                          height: 4,
                          decoration: BoxDecoration(
                            color: FarmColors.line,
                            borderRadius: BorderRadius.circular(
                              99,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(
                        height: 15,
                      ),
                      const Text(
                        'Reserve Supply',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 20,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(
                        height: 3,
                      ),
                      Text(
                        '${demand.productName} • ${demand.formattedQuantity}',
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 11.5,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(
                        height: 4,
                      ),
                      Text(
                        'Already reserved: '
                        '${_matchQuantityLabel(demandReserved, demand.unit)}',
                        style: const TextStyle(
                          color: FarmColors.primary,
                          fontSize: 10.5,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(
                        height: 16,
                      ),
                      const Text(
                        'Choose farmer supply',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 12,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(
                        height: 8,
                      ),
                      Expanded(
                        child: ListView.separated(
                          itemCount: supplies.length,
                          separatorBuilder: (_, __) => const SizedBox(
                            height: 7,
                          ),
                          itemBuilder: (
                            context,
                            index,
                          ) {
                            final supply = supplies[index];

                            final farmer = farmerMap[supply.farmerId];

                            final confirmed = supply.hpjConfirmedQuantity ?? 0;

                            final globallyAllocated =
                                allocatedTotals[supply.id] ?? 0;

                            final current = currentPairQuantity(
                              supply,
                            );

                            final maximum = maximumForSupply(
                              supply,
                            );

                            final selectedRow = selectedSupply?.id == supply.id;

                            return InkWell(
                              borderRadius: BorderRadius.circular(
                                14,
                              ),
                              onTap: saving || maximum <= 0
                                  ? null
                                  : () => chooseSupply(
                                        supply,
                                      ),
                              child: Container(
                                padding: const EdgeInsets.all(
                                  12,
                                ),
                                decoration: BoxDecoration(
                                  color: selectedRow
                                      ? FarmColors.primarySoft
                                      : FarmColors.card,
                                  borderRadius: BorderRadius.circular(
                                    14,
                                  ),
                                  border: Border.all(
                                    color: selectedRow
                                        ? FarmColors.primary
                                        : FarmColors.line,
                                  ),
                                ),
                                child: Row(
                                  children: [
                                    Radio<String>(
                                      value: supply.id,
                                      groupValue: selectedSupply?.id,
                                      onChanged: saving || maximum <= 0
                                          ? null
                                          : (_) => chooseSupply(
                                                supply,
                                              ),
                                    ),
                                    Expanded(
                                      child: Column(
                                        crossAxisAlignment:
                                            CrossAxisAlignment.start,
                                        children: [
                                          Text(
                                            farmer?.farmName ?? 'Farmer Supply',
                                            style: const TextStyle(
                                              color: FarmColors.ink,
                                              fontSize: 13,
                                              fontWeight: FontWeight.w900,
                                            ),
                                          ),
                                          if (farmer != null) ...[
                                            const SizedBox(
                                              height: 2,
                                            ),
                                            Text(
                                              '${farmer.farmerName} • ${farmer.parish}',
                                              maxLines: 1,
                                              overflow: TextOverflow.ellipsis,
                                              style: const TextStyle(
                                                color: FarmColors.mutedText,
                                                fontSize: 9.5,
                                                fontWeight: FontWeight.w700,
                                              ),
                                            ),
                                          ],
                                          const SizedBox(
                                            height: 5,
                                          ),
                                          Text(
                                            'Confirmed ${_matchQuantityLabel(confirmed, supply.unit)}',
                                            style: const TextStyle(
                                              color: FarmColors.green,
                                              fontSize: 10,
                                              fontWeight: FontWeight.w800,
                                            ),
                                          ),
                                          Text(
                                            'Reserved ${_matchQuantityLabel(globallyAllocated, supply.unit)}'
                                            ' • Available ${_matchQuantityLabel(maximum, supply.unit)}',
                                            style: const TextStyle(
                                              color: FarmColors.mutedText,
                                              fontSize: 9.5,
                                              fontWeight: FontWeight.w700,
                                            ),
                                          ),
                                          if (current > 0)
                                            Text(
                                              'This requirement already has ${_matchQuantityLabel(current, supply.unit)} from this farm.',
                                              style: const TextStyle(
                                                color: FarmColors.primary,
                                                fontSize: 9.5,
                                                fontWeight: FontWeight.w800,
                                              ),
                                            ),
                                        ],
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            );
                          },
                        ),
                      ),
                      if (selected != null) ...[
                        const SizedBox(
                          height: 12,
                        ),
                        TextField(
                          controller: quantityController,
                          enabled: !saving,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
