                        SizedBox(
                          width: double.infinity,
                          child: ElevatedButton.icon(
                            icon: saving
                                ? const SizedBox(
                                    width: 17,
                                    height: 17,
                                    child: CircularProgressIndicator(
                                      strokeWidth: 2,
                                      color: Colors.white,
                                    ),
                                  )
                                : const Icon(
                                    Icons.lock_outline_rounded,
                                  ),
                            label: Text(
                              saving ? 'Reserving...' : 'Reserve Supply',
                            ),
                            onPressed: saving ? null : reserve,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              );
            },
          );
        },
      );

      quantityController.dispose();
      notesController.dispose();
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(
              error,
            ),
          ),
        ),
      );
    }
  }
  // =====================================================
// MANAGE EXISTING RESERVATIONS
// =====================================================

  Future<void> _openManageReservationsSheet({
    required WholesaleDemandForecast demand,
    required List<FarmerSupplyForecast> supplies,
    required Map<String, FarmerProfile> farmerMap,
  }) async {
    try {
      var allocations = await fetchSupplyDemandAllocations(
        demandForecastId: demand.id,
      );

      if (!mounted) return;

      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (
              context,
              setSheetState,
            ) {
              Future<void> reload() async {
                final updated = await fetchSupplyDemandAllocations(
                  demandForecastId: demand.id,
                );

                if (!sheetContext.mounted) {
                  return;
                }

                setSheetState(() {
                  allocations = updated;
                });
              }

              FarmerSupplyForecast? supplyFor(
                SupplyDemandAllocation allocation,
              ) {
                for (final supply in supplies) {
                  if (supply.id == allocation.supplyForecastId) {
                    return supply;
                  }
                }

                return null;
              }

              double totalReserved() {
                var total = 0.0;

                for (final allocation in allocations) {
                  if (allocation.isActive) {
                    total += allocation.allocatedQuantity;
                  }
                }

                return total;
              }

              Future<void> editAllocation(
                SupplyDemandAllocation allocation,
              ) async {
                if (!allocation.isReserved) {
                  return;
                }

                final supply = supplyFor(allocation);

                if (supply == null) {
                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'The linked farmer supply could not be found.',
                      ),
                    ),
                  );
                  return;
                }

                final globalReserved = await fetchAllocatedSupplyQuantity(
                  supply.id,
                );

                final demandReserved = totalReserved();

                final confirmed = supply.hpjConfirmedQuantity ?? 0;

                final usedByOtherDemand =
                    globalReserved - allocation.allocatedQuantity;

                final supplyAvailable = confirmed - usedByOtherDemand;

                final reservedForOtherFarms =
                    demandReserved - allocation.allocatedQuantity;

                final demandAvailable = demand.quantity - reservedForOtherFarms;

                final maxSupply = supplyAvailable < 0 ? 0.0 : supplyAvailable;

                final maxDemand = demandAvailable < 0 ? 0.0 : demandAvailable;

                final maximum = maxSupply < maxDemand ? maxSupply : maxDemand;

                final quantityController = TextEditingController(
                  text: allocation.allocatedQuantity ==
                          allocation.allocatedQuantity.roundToDouble()
                      ? allocation.allocatedQuantity.toInt().toString()
                      : allocation.allocatedQuantity.toStringAsFixed(1),
                );

                final notesController = TextEditingController(
                  text: allocation.adminNotes,
                );

                final saved = await showDialog<bool>(
                  context: sheetContext,
                  builder: (
                    dialogContext,
                  ) {
                    return AlertDialog(
                      title: const Text(
                        'Edit reservation',
                      ),
                      content: SingleChildScrollView(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              farmerMap[supply.farmerId]?.farmName ??
                                  'Farmer Supply',
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(
                              height: 4,
                            ),
                            Text(
                              'Maximum ${_matchQuantityLabel(maximum, supply.unit)}',
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 11,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                            const SizedBox(
                              height: 14,
                            ),
                            TextField(
                              controller: quantityController,
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                decimal: true,
                              ),
                              decoration: InputDecoration(
                                labelText: 'Reserved quantity',
                                suffixText: supply.unit,
                              ),
                            ),
                            const SizedBox(
                              height: 12,
                            ),
                            TextField(
                              controller: notesController,
                              maxLines: 3,
                              decoration: const InputDecoration(
                                labelText: 'Admin note',
                              ),
                            ),
                          ],
                        ),
                      ),
                      actions: [
                        TextButton(
                          onPressed: () => Navigator.pop(
                            dialogContext,
                            false,
                          ),
                          child: const Text(
                            'Back',
                          ),
                        ),
                        ElevatedButton(
                          onPressed: () => Navigator.pop(
                            dialogContext,
                            true,
                          ),
                          child: const Text(
                            'Save',
                          ),
                        ),
                      ],
                    );
                  },
                );

                if (saved != true) {
                  quantityController.dispose();

                  notesController.dispose();

                  return;
                }

                final quantity = double.tryParse(
                  quantityController.text.trim().replaceAll(
                        ',',
                        '',
                      ),
                );

                if (quantity == null || quantity <= 0) {
                  quantityController.dispose();

                  notesController.dispose();

                  if (!sheetContext.mounted) {
                    return;
                  }

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Enter a valid quantity.',
                      ),
                    ),
                  );

                  return;
                }

                if (quantity > maximum) {
                  quantityController.dispose();

                  notesController.dispose();

                  if (!sheetContext.mounted) {
                    return;
                  }

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        'Maximum reservation is ${_matchQuantityLabel(maximum, supply.unit)}.',
                      ),
                    ),
                  );

                  return;
                }

                try {
                  await updateSupplyDemandAllocation(
                    allocation: allocation,
                    quantity: quantity,
                    adminNotes: notesController.text,
                  );

                  await _syncDemandReservationStatus(
                    demand,
                  );

                  await reload();

                  await _refresh();

                  if (!sheetContext.mounted) {
                    return;
                  }

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Reservation updated.',
                      ),
                    ),
                  );
                } catch (error) {
                  if (!sheetContext.mounted) {
                    return;
                  }

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        friendlyAppError(
                          error,
                        ),
                      ),
                    ),
                  );
                } finally {
                  quantityController.dispose();

                  notesController.dispose();
                }
              }

              Future<void> releaseAllocation(
                SupplyDemandAllocation allocation,
              ) async {
                if (!allocation.isReserved) {
                  return;
                }

                final supply = supplyFor(allocation);

                final farmer =
                    supply == null ? null : farmerMap[supply.farmerId];

                final confirmed = await showDialog<bool>(
                  context: sheetContext,
                  builder: (
                    dialogContext,
                  ) {
                    return AlertDialog(
                      title: const Text(
                        'Release reservation?',
                      ),
                      content: Text(
                        '${allocation.formattedQuantity} from '
                        '${farmer?.farmName ?? 'this farmer'} '
                        'will become available again.',
                      ),
                      actions: [
                        TextButton(
                          onPressed: () => Navigator.pop(
                            dialogContext,
                            false,
                          ),
                          child: const Text(
                            'Keep',
                          ),
                        ),
                        TextButton(
                          onPressed: () => Navigator.pop(
                            dialogContext,
                            true,
                          ),
                          child: const Text(
                            'Release',
                          ),
                        ),
                      ],
                    );
                  },
                );

                if (confirmed != true) {
                  return;
                }

                try {
                  await releaseSupplyDemandAllocation(
                    allocation,
                  );

                  await _syncDemandReservationStatus(
                    demand,
                  );

                  await reload();

                  await _refresh();

                  if (!sheetContext.mounted) {
                    return;
                  }

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Reserved supply released.',
                      ),
                    ),
                  );
                } catch (error) {
                  if (!sheetContext.mounted) {
                    return;
                  }

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        friendlyAppError(
                          error,
                        ),
                      ),
                    ),
                  );
                }
              }

              final reserved = totalReserved();

              final remaining = demand.quantity - reserved;

              final safeRemaining = remaining < 0 ? 0.0 : remaining;

              return Padding(
                padding: EdgeInsets.only(
                  left: 14,
                  right: 14,
                  bottom: MediaQuery.of(
                        sheetContext,
                      ).viewInsets.bottom +
                      14,
                ),
                child: Container(
                  constraints: const BoxConstraints(
                    maxHeight: 650,
                  ),
                  padding: const EdgeInsets.fromLTRB(
                    18,
                    12,
                    18,
                    18,
                  ),
                  decoration: const BoxDecoration(
                    color: FarmColors.background,
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(
                        26,
                      ),
                    ),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Center(
                        child: Container(
                          width: 42,
                          height: 4,
                          decoration: BoxDecoration(
                            color: FarmColors.line,
                            borderRadius: BorderRadius.circular(
                              99,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(
                        height: 15,
                      ),
                      const Text(
                        'Manage Reservations',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 20,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(
                        height: 3,
                      ),
                      Text(
                        '${demand.productName} • ${demand.formattedQuantity}',
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 11.5,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(
                        height: 12,
                      ),
                      Row(
                        children: [
                          Expanded(
                            child: _SupplyMatchMetric(
                              label: 'Reserved',
                              value: _matchQuantityLabel(
                                reserved,
                                demand.unit,
                              ),
                            ),
                          ),
                          const SizedBox(
                            width: 8,
                          ),
                          Expanded(
                            child: _SupplyMatchMetric(
                              label: 'Still Needed',
                              value: _matchQuantityLabel(
                                safeRemaining,
                                demand.unit,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(
                        height: 14,
                      ),
                      Expanded(
                        child: allocations.isEmpty
                            ? const Center(
                                child: Column(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Icon(
                                      Icons.lock_open_outlined,
                                      size: 30,
                                      color: FarmColors.mutedText,
                                    ),
                                    SizedBox(
                                      height: 8,
                                    ),
                                    Text(
                                      'No active reservations',
                                      style: TextStyle(
                                        color: FarmColors.ink,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                  ],
                                ),
                              )
                            : ListView.separated(
                                itemCount: allocations.length,
                                separatorBuilder: (
                                  _,
                                  __,
                                ) =>
                                    const SizedBox(
                                  height: 8,
                                ),
                                itemBuilder: (
                                  context,
                                  index,
                                ) {
                                  final allocation = allocations[index];

                                  final supply = supplyFor(
                                    allocation,
                                  );

                                  final farmer = supply == null
                                      ? null
                                      : farmerMap[supply.farmerId];

                                  return Container(
                                    padding: const EdgeInsets.all(
                                      12,
                                    ),
                                    decoration: BoxDecoration(
                                      color: FarmColors.card,
                                      borderRadius: BorderRadius.circular(
                                        14,
                                      ),
                                      border: Border.all(
                                        color: FarmColors.line,
                                      ),
                                    ),
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Row(
                                          children: [
                                            Expanded(
                                              child: Text(
                                                farmer?.farmName ??
                                                    'Farmer Supply',
                                                style: const TextStyle(
                                                  color: FarmColors.ink,
                                                  fontSize: 13,
                                                  fontWeight: FontWeight.w900,
                                                ),
                                              ),
                                            ),
                                            Text(
                                              allocation.formattedQuantity,
                                              style: const TextStyle(
                                                color: FarmColors.green,
                                                fontSize: 12,
                                                fontWeight: FontWeight.w900,
                                              ),
                                            ),
                                          ],
                                        ),
                                        if (farmer != null) ...[
                                          const SizedBox(
                                            height: 3,
                                          ),
                                          Text(
                                            '${farmer.farmerName} • ${farmer.parish}',
                                            style: const TextStyle(
                                              color: FarmColors.mutedText,
                                              fontSize: 9.5,
                                              fontWeight: FontWeight.w700,
                                            ),
                                          ),
                                        ],
                                        if (allocation.adminNotes
                                            .trim()
                                            .isNotEmpty) ...[
                                          const SizedBox(
                                            height: 7,
                                          ),
                                          Text(
                                            allocation.adminNotes,
                                            style: const TextStyle(
                                              color: FarmColors.mutedText,
                                              fontSize: 10,
                                              height: 1.3,
                                            ),
                                          ),
                                        ],
                                        if (allocation.isReserved) ...[
                                          const SizedBox(
                                            height: 9,
                                          ),
                                          Row(
                                            children: [
                                              Expanded(
                                                child: OutlinedButton.icon(
                                                  icon: const Icon(
                                                    Icons.edit_outlined,
                                                    size: 15,
                                                  ),
                                                  label: const Text(
                                                    'Edit',
                                                  ),
                                                  onPressed: () =>
                                                      editAllocation(
                                                    allocation,
                                                  ),
                                                ),
                                              ),
                                              const SizedBox(
                                                width: 7,
                                              ),
                                              Expanded(
                                                child: TextButton(
                                                  onPressed: () =>
                                                      releaseAllocation(
                                                    allocation,
                                                  ),
                                                  child: const Text(
                                                    'Release',
                                                  ),
                                                ),
                                              ),
                                            ],
                                          ),
                                        ],
                                      ],
                                    ),
                                  );
                                },
                              ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    }
  }
// =====================================================
// CONVERT RESERVED DEMAND TO WHOLESALE REQUEST
// =====================================================

  Future<void> _openConvertDemandSheet(
    WholesaleDemandForecast demand,
  ) async {
    if (!demand.isReserved) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Fully reserve the requirement before creating a wholesale request.',
          ),
        ),
      );
      return;
    }

    try {
      // -------------------------------------------------
      // FIND BUSINESS ACCOUNT
      // -------------------------------------------------

      final accounts = await accountsFuture;

      BusinessAccount? business;

      for (final account in accounts) {
        if (account.id == demand.businessAccountId) {
          business = account;
          break;
        }
      }

      if (business == null) {
        throw Exception(
          'The wholesale business account could not be found.',
        );
      }

      // -------------------------------------------------
      // TRY TO PREFILL CURRENT WHOLESALE PRICE
      // -------------------------------------------------

      final products = await productsFuture;

      double suggestedPrice = 0;

      for (final item in products) {
        final productId = item.product.id.toString();

        final demandProductId = demand.productId?.trim();

        final sameId = demandProductId != null &&
            demandProductId.isNotEmpty &&
            productId == demandProductId;

        final sameName = item.product.name.trim().toLowerCase() ==
            demand.productName.trim().toLowerCase();

        if (sameId || sameName) {
          suggestedPrice = item.wholesalePrice;
          break;
        }
      }

      if (!mounted) return;

      final priceController = TextEditingController(
        text: suggestedPrice > 0
            ? suggestedPrice == suggestedPrice.roundToDouble()
                ? suggestedPrice.toInt().toString()
                : suggestedPrice.toStringAsFixed(2)
            : '',
      );

      final addressController = TextEditingController(
        text: business.address,
      );

      final parishController = TextEditingController(
        text: business.parish,
      );

      final notesController = TextEditingController(
        text: demand.notes,
      );

      DateTime requestedDate = demand.needByDate;

      bool saving = false;

      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (
              context,
              setSheetState,
            ) {
              double currentPrice() {
                return double.tryParse(
                      priceController.text.trim().replaceAll(',', ''),
                    ) ??
                    0;
              }

              double estimatedTotal() {
                return currentPrice() * demand.quantity;
              }

              Future<void> chooseDate() async {
                final today = DateTime.now();

                final initial = requestedDate.isBefore(
                  DateTime(
                    today.year,
                    today.month,
                    today.day,
                  ),
                )
                    ? today
                    : requestedDate;

                final picked = await showDatePicker(
                  context: sheetContext,
                  initialDate: initial,
                  firstDate: DateTime(
                    today.year,
                    today.month,
                    today.day,
                  ),
                  lastDate: DateTime(
                    today.year + 2,
                  ),
                );

                if (picked == null) return;

                setSheetState(() {
                  requestedDate = picked;
                });
              }

              Future<void> convert() async {
                if (saving) return;

                final price = currentPrice();

                if (price <= 0) {
                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Enter a valid wholesale unit price.',
                      ),
                    ),
                  );
                  return;
                }

                setSheetState(() {
                  saving = true;
                });

                try {
                  final requestId = await adminConvertReservedDemandToRequest(
                    demand: demand,
                    unitPrice: price,
                    deliveryAddress: addressController.text,
                    deliveryParish: parishController.text,
                    requestedDate: requestedDate,
                    notes: notesController.text,
                  );

                  await ensureWholesaleReceivingBatchesForDemand(
                    demandForecastId: demand.id,
                    wholesaleRequestId: requestId,
                  );

                  if (!sheetContext.mounted) {
                    return;
                  }

                  Navigator.pop(
                    sheetContext,
                  );

                  widget.onChanged();

                  await _refresh();

                  if (!mounted) return;

                  final shortId = requestId.replaceAll('-', '').toUpperCase();

                  final displayId = shortId.length > 8
                      ? shortId.substring(
                          0,
                          8,
                        )
                      : shortId;

                  ScaffoldMessenger.of(
                    context,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        'Wholesale request #$displayId created successfully.',
                      ),
                    ),
                  );
                } catch (error) {
                  if (!sheetContext.mounted) {
                    return;
                  }

                  setSheetState(() {
                    saving = false;
                  });

                  ScaffoldMessenger.of(
                    sheetContext,
                  ).showSnackBar(
                    SnackBar(
                      content: Text(
                        friendlyAppError(
                          error,
                        ),
                      ),
                    ),
                  );
                }
              }

              return Padding(
                padding: EdgeInsets.only(
                  left: 14,
                  right: 14,
                  bottom: MediaQuery.of(
                        sheetContext,
                      ).viewInsets.bottom +
                      14,
                ),
                child: Container(
                  constraints: const BoxConstraints(
                    maxHeight: 680,
                  ),
                  padding: const EdgeInsets.fromLTRB(
                    18,
                    12,
                    18,
                    18,
                  ),
                  decoration: const BoxDecoration(
                    color: FarmColors.background,
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(
                        26,
                      ),
                    ),
                  ),
                  child: SingleChildScrollView(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Center(
                          child: Container(
                            width: 42,
                            height: 4,
                            decoration: BoxDecoration(
                              color: FarmColors.line,
                              borderRadius: BorderRadius.circular(
                                99,
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(
                          height: 15,
                        ),
                        const Text(
                          'Create Wholesale Request',
                          style: TextStyle(
                            color: FarmColors.ink,
                            fontSize: 20,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        const SizedBox(
                          height: 4,
                        ),
                        Text(
                          business!.displayName,
                          style: const TextStyle(
                            color: FarmColors.primary,
                            fontSize: 11.5,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                        const SizedBox(
                          height: 14,
                        ),
                        FarmCard(
                          padding: const EdgeInsets.all(
                            14,
                          ),
                          child: Row(
                            children: [
                              Container(
                                width: 40,
                                height: 40,
                                decoration: BoxDecoration(
                                  color: FarmColors.primarySoft,
                                  borderRadius: BorderRadius.circular(
                                    13,
                                  ),
                                ),
                                child: const Icon(
                                  Icons.inventory_2_outlined,
                                  color: FarmColors.primary,
                                ),
                              ),
                              const SizedBox(
                                width: 10,
                              ),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      demand.productName,
                                      style: const TextStyle(
                                        color: FarmColors.ink,
                                        fontSize: 15,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    const SizedBox(
                                      height: 2,
                                    ),
                                    Text(
                                      '${demand.formattedQuantity} reserved',
                                      style: const TextStyle(
                                        color: FarmColors.green,
                                        fontSize: 10.5,
                                        fontWeight: FontWeight.w800,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                        const SizedBox(
                          height: 14,
                        ),
                        TextField(
                          controller: priceController,
                          enabled: !saving,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          onChanged: (_) {
                            setSheetState(() {});
                          },
                          decoration: InputDecoration(
                            labelText: 'Wholesale unit price',
                            prefixText: 'J\$ ',
                            suffixText: '/ ${demand.unit}',
                          ),
                        ),
                        const SizedBox(
                          height: 10,
                        ),
                        Container(
                          width: double.infinity,
                          padding: const EdgeInsets.all(
                            13,
                          ),
                          decoration: BoxDecoration(
                            color: FarmColors.primarySoft,
                            borderRadius: BorderRadius.circular(
                              14,
                            ),
                          ),
                          child: Row(
                            children: [
                              const Expanded(
                                child: Text(
                                  'Estimated total',
                                  style: TextStyle(
                                    color: FarmColors.ink,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                              ),
                              Text(
                                formatJmd(
                                  estimatedTotal(),
                                ),
                                style: const TextStyle(
                                  color: FarmColors.green,
                                  fontSize: 17,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ],
                          ),
                        ),
                        const SizedBox(
                          height: 12,
                        ),
                        InkWell(
                          borderRadius: BorderRadius.circular(
                            14,
