  Future<void> _verifyFarmerSupplyForDemand({
    required WholesaleDemandForecast demand,
    required List<FarmerSupplyForecast> candidates,
    required Map<String, FarmerProfile> farmerMap,
  }) async {
    if (candidates.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('No farmer supply is waiting for verification.'),
        ),
      );
      return;
    }

    final selected = await showModalBottomSheet<FarmerSupplyForecast>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return Container(
          constraints: const BoxConstraints(maxHeight: 620),
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 18),
          decoration: const BoxDecoration(
            color: FarmColors.background,
            borderRadius: BorderRadius.vertical(top: Radius.circular(26)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: FarmColors.line,
                    borderRadius: BorderRadius.circular(99),
                  ),
                ),
              ),
              const SizedBox(height: 15),
              const Text(
                'Verify Farmer Supply',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 4),
              Text(
                '${demand.productName} • ${demand.formattedQuantity}',
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Choose a farmer report to verify. Farmer-reported quantity is not reservable until HPJ confirms it.',
                style: TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.5,
                  height: 1.35,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 12),
              Expanded(
                child: ListView.separated(
                  itemCount: candidates.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 8),
                  itemBuilder: (_, index) {
                    final supply = candidates[index];
                    final farmer = farmerMap[supply.farmerId];
                    final potential = _supplyPotentialQuantity(supply);
                    final harvest = supply.expectedHarvestDate;
                    final harvestLabel = harvest == null
                        ? 'Harvest date not set'
                        : 'Harvest ${_demandDateLabel(harvest)}';

                    return FarmCard(
                      padding: const EdgeInsets.all(12),
                      child: Row(
                        children: [
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  farmer?.farmName ?? 'Farmer Supply',
                                  style: const TextStyle(
                                    color: FarmColors.ink,
                                    fontSize: 13,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                                const SizedBox(height: 3),
                                Text(
                                  '${_matchQuantityLabel(potential, supply.unit)} reported • $harvestLabel',
                                  style: const TextStyle(
                                    color: FarmColors.mutedText,
                                    fontSize: 10,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          const SizedBox(width: 8),
                          ElevatedButton(
                            onPressed: potential <= 0
                                ? null
                                : () => Navigator.pop(sheetContext, supply),
                            child: const Text('Verify'),
                          ),
                        ],
                      ),
                    );
                  },
                ),
              ),
            ],
          ),
        );
      },
    );

    if (selected == null || !mounted) return;

    final reported = _supplyPotentialQuantity(selected);
    final quantityController = TextEditingController(
      text: reported == reported.roundToDouble()
          ? reported.toInt().toString()
          : reported.toStringAsFixed(1),
    );

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text('Confirm verified quantity'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                farmerMap[selected.farmerId]?.farmName ?? 'Farmer Supply',
                style: const TextStyle(fontWeight: FontWeight.w900),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: quantityController,
                keyboardType: const TextInputType.numberWithOptions(
                  decimal: true,
                ),
                decoration: InputDecoration(
                  labelText: 'HPJ verified quantity',
                  suffixText: selected.unit,
                  helperText:
                      'Farmer reported ${_matchQuantityLabel(reported, selected.unit)}',
                ),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Back'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Confirm Supply'),
            ),
          ],
        );
      },
    );

    if (confirmed != true) {
      quantityController.dispose();
      return;
    }

    final quantity = double.tryParse(
      quantityController.text.trim().replaceAll(',', ''),
    );
    quantityController.dispose();

    if (quantity == null || quantity <= 0) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter a valid verified quantity.')),
      );
      return;
    }

    try {
      await adminConfirmFarmerSupplyForecast(
        supply: selected,
        confirmedQuantity: quantity,
      );
      await _refresh();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${selected.cropName} verified at ${_matchQuantityLabel(quantity, selected.unit)}.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _useRecommendedProcurementMatch({
    required WholesaleDemandForecast demand,
    required List<FarmerSupplyForecast> rankedCandidates,
    required Map<String, double> availableBySupply,
    required double quantityNeeded,
  }) async {
    if (quantityNeeded <= 0) return;

    var remaining = quantityNeeded;
    var reserved = 0.0;

    try {
      for (final supply in rankedCandidates) {
        if (remaining <= 0.0001) break;

        final available = availableBySupply[supply.id] ?? 0;
        if (available <= 0) continue;

        final quantity = available < remaining ? available : remaining;

        await createSupplyDemandAllocation(
          supply: supply,
          demand: demand,
          quantity: quantity,
          adminNotes: 'HPJ recommended procurement match',
        );

        reserved += quantity;
        remaining -= quantity;
      }

      await _syncDemandReservationStatus(demand);
      await _refresh();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            reserved > 0
                ? '${_matchQuantityLabel(reserved, demand.unit)} secured from recommended farmers.'
                : 'No confirmed farmer quantity was available to reserve.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _confirmExistingOrderProcurement({
    required WholesaleDemandForecast demand,
    required double coveredQuantity,
  }) async {
    final requestId = demand.sourceRequestId?.trim() ?? '';

    if (requestId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('This procurement requirement is not linked to an order.'),
        ),
      );
      return;
    }

    if (coveredQuantity + 0.0001 < demand.quantity) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Secure the remaining quantity before confirming procurement.'),
        ),
      );
      return;
    }

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Confirm Procurement?'),
        content: Text(
          '${demand.productName} is fully covered. Confirming moves farmer reservations into the existing wholesale order and sends them to collection/receiving.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Back'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Confirm Procurement'),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    try {
      final allocations = await fetchSupplyDemandAllocations(
        demandForecastId: demand.id,
      );

      for (final allocation in allocations) {
        if (allocation.isReserved) {
          await convertSupplyDemandAllocation(
            allocation: allocation,
            wholesaleRequestId: requestId,
          );
        }
      }

      await ensureWholesaleReceivingBatchesForDemand(
        demandForecastId: demand.id,
        wholesaleRequestId: requestId,
      );

      await adminUpdateWholesaleDemandForecast(
        forecast: demand,
        status: 'converted',
        convertedRequestId: requestId,
        adminNotes: demand.adminNotes,
      );

      await _refresh();

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Procurement confirmed. Farmer supply is now waiting in Collection/Receiving planning.'),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Widget _procurementLoadError(Object? error) {
    return RefreshIndicator(
      onRefresh: _refresh,
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.all(18),
        children: [
          FarmCard(
            padding: const EdgeInsets.all(18),
            child: Column(
              children: [
                const Icon(
                  Icons.cloud_off_outlined,
                  color: FarmColors.danger,
                  size: 34,
                ),
                const SizedBox(height: 10),
                const Text(
                  'Procurement data could not be loaded',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 5),
                Text(
                  friendlyAppError(error ?? Exception('Unknown procurement error')),
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 10.5,
                    height: 1.35,
                  ),
                ),
                const SizedBox(height: 12),
                OutlinedButton.icon(
                  onPressed: _refresh,
                  icon: const Icon(Icons.refresh_rounded),
                  label: const Text('Retry'),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

// =====================================================
// PROCUREMENT — DEMAND + MATCHING IN ONE WORKFLOW
// =====================================================

  Widget _matchingTab() {
    return FutureBuilder<_WholesaleProcurementSnapshot>(
      future: procurementFuture,
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting &&
            !snapshot.hasData) {
          return const Center(child: CircularProgressIndicator());
        }

        if (snapshot.hasError) {
          return _procurementLoadError(snapshot.error);
        }

        final data = snapshot.data;
        if (data == null) {
          return _procurementLoadError(
            Exception('Procurement data is unavailable.'),
          );
        }

        final allActiveDemands =
            data.demands.where((item) => item.isActive).toList()
              ..sort((a, b) => a.needByDate.compareTo(b.needByDate));

        final requestedDemandId =
            widget.demandIdFilter?.trim() ?? '';

        final focusedDemands = requestedDemandId.isEmpty
            ? const <WholesaleDemandForecast>[]
            : allActiveDemands
                .where(
                  (demand) => demand.id.trim() == requestedDemandId,
                )
                .toList();

        final exactDemandFound = focusedDemands.isNotEmpty;
        final demands =
            exactDemandFound ? focusedDemands : allActiveDemands;

        final farmerMap = <String, FarmerProfile>{
          for (final farmer in data.farmers) farmer.id: farmer,
        };
        final businessMap = <String, BusinessAccount>{
          for (final account in data.accounts) account.id: account,
        };
        final demandMap = <String, WholesaleDemandForecast>{
          for (final item in data.demands) item.id: item,
        };
        final performanceMap = <String, WarehouseSupplierPerformanceRow>{
          for (final row in data.supplierPerformance) row.farmerId: row,
        };

        final activeAllocations = data.allocations
            .where((allocation) => allocation.isActive)
            .toList();

        final allocatedBySupply = <String, double>{};
        final allocatedByDemand = <String, double>{};
        for (final allocation in activeAllocations) {
          allocatedBySupply[allocation.supplyForecastId] =
              (allocatedBySupply[allocation.supplyForecastId] ?? 0) +
                  allocation.allocatedQuantity;
          allocatedByDemand[allocation.demandForecastId] =
              (allocatedByDemand[allocation.demandForecastId] ?? 0) +
                  allocation.allocatedQuantity;
        }

        double warehouseReservedForDemand(WholesaleDemandForecast demand) {
          if (!demand.isOrderDemand) return 0;
          final requestId = demand.sourceRequestId?.trim() ?? '';
          if (requestId.isEmpty) return 0;

          var total = 0.0;
          for (final reservation in data.warehouseReservations) {
            if (reservation.requestId != requestId) continue;
            if (_normalizeMatchName(reservation.productName) !=
                _normalizeMatchName(demand.productName)) {
              continue;
            }
            if (_normalizeMatchUnit(reservation.unit) !=
                _normalizeMatchUnit(demand.unit)) {
              continue;
            }

            final covered =
                reservation.reservedQuantity - reservation.releasedQuantity;
            if (covered > 0) total += covered;
          }
          return total;
        }

        // A Planning Ahead requirement can be converted into a real order
        // before the order itself appears in Procurement. Those converted
        // farmer allocations already belong to the request and must count as
        // secured supply so HPJ never sources the same quantity twice.
        double priorConvertedFarmerCoverageForDemand(
          WholesaleDemandForecast demand,
        ) {
          if (!demand.isOrderDemand) return 0;

          final requestId = demand.sourceRequestId?.trim() ?? '';
          if (requestId.isEmpty) return 0;

          var total = 0.0;
          for (final allocation in activeAllocations) {
            if (!allocation.isConverted ||
                allocation.wholesaleRequestId != requestId ||
                allocation.demandForecastId == demand.id) {
              continue;
            }

            final originalDemand = demandMap[allocation.demandForecastId];
            if (originalDemand == null) continue;

            if (_normalizeMatchName(originalDemand.productName) !=
                _normalizeMatchName(demand.productName)) {
              continue;
            }
            if (_normalizeMatchUnit(originalDemand.unit) !=
                _normalizeMatchUnit(demand.unit)) {
              continue;
            }

            total += allocation.allocatedQuantity;
          }

          return total.clamp(0.0, demand.quantity).toDouble();
        }

        if (demands.isEmpty) {
          return RefreshIndicator(
            onRefresh: _refresh,
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.all(18),
              children: const [
                FarmEmptyState(
                  icon: Icons.check_circle_outline_rounded,
                  title: 'Procurement is clear',
                  message:
                      'Approved wholesale orders, Planning Ahead demand and receiving shortfalls will appear here only while supply still needs attention.',
                ),
              ],
            ),
          );
        }

        return RefreshIndicator(
          onRefresh: _refresh,
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(14, 14, 14, 100),
            children: [
              FarmCard(
                padding: const EdgeInsets.all(16),
                child: const Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(
                      Icons.account_tree_outlined,
                      color: FarmColors.primary,
                      size: 26,
                    ),
                    SizedBox(width: 11),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Procurement',
                            style: TextStyle(
                              color: FarmColors.ink,
                              fontSize: 18,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          SizedBox(height: 4),
                          Text(
                            'HPJ reserves warehouse stock first for approved orders, then shows the farmer quantity still needed. Verify supply, use the recommended match, and confirm procurement.',
                            style: TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 10.5,
                              height: 1.35,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 14),
              if (requestedDemandId.isNotEmpty) ...[
                _WholesaleAdminFocusNotice(
                  found: exactDemandFound,
                  foundMessage:
                      'Opened from your notification. Showing the related procurement requirement.',
                  missingMessage:
                      'That procurement requirement is no longer active. Showing current supply needs instead.',
                ),
                const SizedBox(height: 12),
              ],
              ...demands.map((demand) {
                final demandName = _normalizeMatchName(demand.productName);
                final demandUnit = _normalizeMatchUnit(demand.unit);

                final sameCrop = data.supplies.where((supply) {
                  return supply.isActive &&
                      _normalizeMatchName(supply.cropName) == demandName;
                }).toList();

                final sameUnit = sameCrop.where((supply) {
                  return _normalizeMatchUnit(supply.unit) == demandUnit;
                }).toList();

                final matching = sameUnit.where((supply) {
                  return _supplyFitsDemandDate(supply, demand);
                }).toList();

                final unverified = matching.where((supply) {
                  return !supply.isHpjConfirmed &&
                      _supplyPotentialQuantity(supply) > 0;
                }).toList();

                final availableBySupply = <String, double>{};
                final rankedCandidates = matching.where((supply) {
                  if (!supply.isHpjConfirmed) return false;
                  final confirmed = supply.hpjConfirmedQuantity ?? 0;
                  final used = allocatedBySupply[supply.id] ?? 0;
                  final available = confirmed - used;
                  availableBySupply[supply.id] = available > 0 ? available : 0;
                  final performance = performanceMap[supply.farmerId];
                  return available > 0 && performance?.isPaused != true;
                }).toList()
                  ..sort((a, b) {
                    final pa = performanceMap[a.farmerId];
                    final pb = performanceMap[b.farmerId];
                    if (pa?.isPreferred == true && pb?.isPreferred != true) {
                      return -1;
                    }
                    if (pb?.isPreferred == true && pa?.isPreferred != true) {
                      return 1;
                    }
                    final sa = pa?.supplierScore ?? -1;
                    final sb = pb?.supplierScore ?? -1;
                    final byScore = sb.compareTo(sa);
                    if (byScore != 0) return byScore;
                    final da = a.expectedHarvestDate ?? DateTime(9999);
                    final db = b.expectedHarvestDate ?? DateTime(9999);
                    return da.compareTo(db);
                  });

                var confirmedAvailable = 0.0;
                for (final supply in rankedCandidates) {
                  confirmedAvailable += availableBySupply[supply.id] ?? 0;
                }

                var unverifiedPotential = 0.0;
                for (final supply in unverified) {
                  unverifiedPotential += _supplyPotentialQuantity(supply);
                }

                final warehouseReserved = warehouseReservedForDemand(demand);
                final priorFarmerSecured =
                    priorConvertedFarmerCoverageForDemand(demand);
                final currentFarmerSecured = allocatedByDemand[demand.id] ?? 0;
                final farmerSecured =
                    (priorFarmerSecured + currentFarmerSecured)
                        .clamp(0.0, demand.quantity)
                        .toDouble();
                final farmerTarget = demand.isOrderDemand
                    ? (demand.quantity - warehouseReserved - priorFarmerSecured)
                        .clamp(0.0, demand.quantity)
                        .toDouble()
                    : demand.quantity;
                final stillNeeded = (farmerTarget - currentFarmerSecured)
                    .clamp(0.0, demand.quantity)
                    .toDouble();
                final totalCovered =
                    (warehouseReserved + farmerSecured)
                        .clamp(0.0, demand.quantity)
                        .toDouble();

                String coverageLabel;
                Color coverageColor;
                if (totalCovered >= demand.quantity - 0.0001) {
                  coverageLabel = demand.isPlanningDemand
                      ? 'Supply Secured'
                      : 'Ready to Confirm';
                  coverageColor = FarmColors.success;
                } else if (farmerSecured > 0 || warehouseReserved > 0) {
                  coverageLabel = 'Partially Secured';
                  coverageColor = FarmColors.primary;
                } else if (confirmedAvailable >= stillNeeded && stillNeeded > 0) {
                  coverageLabel = 'Supply Available';
                  coverageColor = FarmColors.primary;
                } else if (unverifiedPotential > 0) {
                  coverageLabel = 'Needs Verification';
                  coverageColor = FarmColors.warning;
                } else {
                  coverageLabel = 'Supply Gap';
                  coverageColor = FarmColors.warning;
                }

                final account = businessMap[demand.businessAccountId];
                String businessName = account?.displayName ?? 'Wholesale demand';
                if (demand.sourceRequestId != null) {
                  for (final request in data.requests) {
                    if (request.id == demand.sourceRequestId) {
                      businessName = request.businessName.trim().isEmpty
                          ? businessName
                          : request.businessName.trim();
                      break;
                    }
                  }
                }

                final hasUnitMismatch = sameCrop.isNotEmpty && sameUnit.isEmpty;
                final topFarmLabels = rankedCandidates.take(3).map((supply) {
                  final farm = farmerMap[supply.farmerId]?.farmName ?? 'Farm';
                  final score = performanceMap[supply.farmerId]?.supplierScore;
                  final available = availableBySupply[supply.id] ?? 0;
                  return score == null
                      ? '$farm • ${_matchQuantityLabel(available, supply.unit)}'
                      : '$farm • ${_matchQuantityLabel(available, supply.unit)} • ${score.toStringAsFixed(0)}%';
                }).toList();

                return Padding(
                  padding: const EdgeInsets.only(bottom: 11),
                  child: FarmCard(
                    padding: const EdgeInsets.all(14),
                    child: Column(
