                        if (stillNeeded > 0 &&
                            rankedCandidates.isEmpty &&
                            unverified.isEmpty) ...[
                          const SizedBox(height: 8),
                          const Text(
                            'No eligible farmer supply is available yet. Keep this requirement open and add/verify supply when a farmer reports it.',
