// =====================================================
// RECORD SHORTAGE
// =====================================================

  Future<void> _recordFulfillmentShortage(
    WholesaleFulfillmentItem item,
  ) async {
    final saved =
        await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) =>
          _WholesaleFulfillmentShortageSheet(
        item: item,
      ),
    );

    if (!mounted || saved != true) {
      return;
    }

    await _refresh();

    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${item.productName} shortage recorded.',
        ),
      ),
    );
  }

// =====================================================
// REMOVE FULFILMENT LINE
// =====================================================

  Future<void> _removeFulfillmentLine(
    WholesaleFulfillmentItem item,
  ) async {
    final removed =
        await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) =>
          _WholesaleFulfillmentRemoveSheet(
        item: item,
      ),
    );

    if (!mounted || removed != true) {
      return;
    }

    await _refresh();

    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${item.productName} removed from fulfilment.',
        ),
      ),
    );
  }

// =====================================================
// READY FOR DISPATCH
// =====================================================

  Future<void> _markFulfillmentReady(
    WholesaleFulfillment fulfillment,
  ) async {
    if (!fulfillment.allItemsAccountedFor) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Pack, mark short, or remove every item first.',
          ),
        ),
      );

      return;
    }

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text(
            'Ready for dispatch?',
          ),
          content: const Text(
            'Confirm that packing is complete and this wholesale order can move to dispatch.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                false,
              ),
              child: const Text('Back'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                true,
              ),
              child: const Text(
                'Ready for Dispatch',
              ),
            ),
          ],
        );
      },
    );

    if (confirmed != true) {
      return;
    }

    try {
      await markWholesaleFulfillmentReadyForDispatch(
        fulfillment,
      );

      await _refresh();

      widget.onChanged();

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Wholesale order is ready for dispatch.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    }
  }



// =====================================================
// FULFILMENT TAB
// =====================================================

  Widget _fulfillmentTab() {
    return FutureBuilder<List<Object>>(
      future: Future.wait<Object>([
        fulfillmentFuture,
        requestsFuture,
        dispatchFuture,
      ]),
      builder: (
        context,
        snapshot,
      ) {
        if (snapshot.connectionState == ConnectionState.waiting &&
            !snapshot.hasData) {
          return const Center(
            child: CircularProgressIndicator(),
          );
        }

        if (snapshot.hasError) {
          return Center(
            child: Padding(
              padding: const EdgeInsets.all(
                24,
              ),
              child: Text(
                friendlyAppError(
                  snapshot.error!,
                ),
                textAlign: TextAlign.center,
              ),
            ),
          );
        }

        final data = snapshot.data;

        if (data == null) {
          return const SizedBox.shrink();
        }

        final fulfillments = data[0] as List<WholesaleFulfillment>;

        final requests = data[1] as List<WholesaleOrderRequest>;
        final dispatches = data[2] as List<WholesaleDispatch>;

        final requestMap = <String, WholesaleOrderRequest>{
          for (final request in requests) request.id: request,
        };

        final dispatchByFulfillment = <String, WholesaleDispatch>{
          for (final dispatch in dispatches)
            if (!dispatch.isCancelled) dispatch.fulfillmentId: dispatch,
        };

        final activeFulfillments = fulfillments.where((fulfillment) {
          if (fulfillment.isCancelled) return false;
          final dispatch = dispatchByFulfillment[fulfillment.id];
          return dispatch?.isComplete != true;
        }).toList();

        final fulfillmentRequestIds = fulfillments
            .map(
              (item) => item.requestId,
            )
            .toSet();

        final readyToCreate = requests
            .where(
              (request) =>
                  request.status == 'approved' &&
                  !fulfillmentRequestIds.contains(
                    request.id,
                  ),
            )
            .toList();

        final waiting = activeFulfillments
            .where(
              (item) => item.isWaitingStock,
            )
            .length;

        final preparing = activeFulfillments
            .where(
              (item) => item.isPreparing,
            )
            .length;

        final packing = activeFulfillments
            .where(
              (item) => item.isPacking,
            )
            .length;

        final ready = activeFulfillments
            .where(
              (item) => item.isReadyForDispatch,
            )
            .length;

        return RefreshIndicator(
          onRefresh: _refresh,
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(
              14,
              14,
              14,
              100,
            ),
            children: [
              // ==========================================
              // HEADER
              // ==========================================

              FarmCard(
                padding: const EdgeInsets.all(
                  16,
                ),
                child: Row(
                  children: [
                    Container(
                      width: 44,
                      height: 44,
                      decoration: BoxDecoration(
                        color: FarmColors.primarySoft,
                        borderRadius: BorderRadius.circular(
                          14,
                        ),
                      ),
                      child: const Icon(
                        Icons.inventory_2_outlined,
                        color: FarmColors.primary,
                      ),
                    ),
                    const SizedBox(
                      width: 12,
                    ),
                    const Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Wholesale Fulfillment',
                            style: TextStyle(
                              color: FarmColors.ink,
                              fontSize: 17,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          SizedBox(
                            height: 3,
                          ),
                          Text(
                            'Prepare and pack approved business orders before dispatch.',
                            style: TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 10.5,
                              height: 1.3,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),

              const SizedBox(
                height: 12,
              ),

              // ==========================================
              // SUMMARY
              // ==========================================

              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  children: [
                    _demandStat(
                      label: 'Waiting',
                      value: waiting,
                    ),
                    const SizedBox(
                      width: 8,
                    ),
                    _demandStat(
                      label: 'Preparing',
                      value: preparing,
                    ),
                    const SizedBox(
                      width: 8,
                    ),
                    _demandStat(
                      label: 'Packing',
                      value: packing,
                    ),
                    const SizedBox(
                      width: 8,
                    ),
                    _demandStat(
                      label: 'Dispatch',
                      value: ready,
                    ),
                  ],
                ),
              ),

              const SizedBox(
                height: 20,
              ),

              // ==========================================
              // APPROVED REQUESTS WITHOUT FULFILMENT
              // ==========================================

              if (readyToCreate.isNotEmpty) ...[
                const Text(
                  'Ready for Fulfillment',
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(
                  height: 4,
                ),
                const Text(
                  'Approved wholesale requests that have not entered warehouse preparation yet.',
                  style: TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 10.5,
                    height: 1.3,
                  ),
                ),
                const SizedBox(
                  height: 10,
                ),
                ...readyToCreate.map(
                  (request) {
                    return Padding(
                      padding: const EdgeInsets.only(
                        bottom: 9,
                      ),
                      child: FarmCard(
                        padding: const EdgeInsets.all(
                          14,
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        request.businessName.trim().isEmpty
                                            ? 'Wholesale Business'
                                            : request.businessName,
                                        style: const TextStyle(
                                          color: FarmColors.ink,
                                          fontSize: 14,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      const SizedBox(
                                        height: 3,
                                      ),
                                      Text(
                                        'Request #${request.shortId}',
                                        style: const TextStyle(
                                          color: FarmColors.mutedText,
                                          fontSize: 10,
                                          fontWeight: FontWeight.w700,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                Text(
                                  '${request.items.length} '
                                  '${request.items.length == 1 ? 'item' : 'items'}',
                                  style: const TextStyle(
                                    color: FarmColors.green,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              ],
                            ),
                            if (request.items.isNotEmpty) ...[
                              const SizedBox(
                                height: 10,
                              ),
                              ...request.items.take(3).map(
                                    (item) => Padding(
                                      padding: const EdgeInsets.only(
                                        bottom: 3,
                                      ),
                                      child: Text(
                                        '${item.productName} • '
                                        '${item.quantityLabel} ${item.unit}',
                                        style: const TextStyle(
                                          color: FarmColors.mutedText,
                                          fontSize: 10,
                                          fontWeight: FontWeight.w700,
                                        ),
                                      ),
                                    ),
                                  ),
                              if (request.items.length > 3)
                                Text(
                                  '+ ${request.items.length - 3} more',
                                  style: const TextStyle(
                                    color: FarmColors.primary,
                                    fontSize: 9.5,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                            ],
                            const SizedBox(
                              height: 11,
                            ),
                            SizedBox(
                              width: double.infinity,
                              child: ElevatedButton.icon(
                                icon: const Icon(
                                  Icons.inventory_outlined,
                                  size: 17,
                                ),
                                label: const Text(
                                  'Create Fulfillment',
                                ),
                                onPressed: () => _createFulfillment(
                                  request,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  },
                ),
                const SizedBox(
                  height: 12,
                ),
              ],

              // ==========================================
              // ACTIVE FULFILMENTS
              // ==========================================

              const Text(
                'Warehouse Orders',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 16,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(
                height: 10,
              ),

              if (activeFulfillments.isEmpty)
                FarmCard(
                  padding: const EdgeInsets.all(
                    22,
                  ),
                  child: const Column(
                    children: [
                      Icon(
                        Icons.inventory_2_outlined,
                        size: 30,
                        color: FarmColors.mutedText,
                      ),
                      SizedBox(
                        height: 8,
                      ),
                      Text(
                        'No active wholesale fulfillment',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      SizedBox(
                        height: 4,
                      ),
                      Text(
                        'Approved orders appear above. Delivered orders remain in Orders history.',
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 11,
                        ),
                      ),
                    ],
                  ),
                )
              else
                ...activeFulfillments.map(
                  (fulfillment) {
                    final request = requestMap[fulfillment.requestId];

                    final statusColor = _fulfillmentStatusColor(
                      fulfillment,
                    );

                    final progress = fulfillment.packingProgress
                        .clamp(
                          0.0,
                          1.0,
                        )
                        .toDouble();

                    return Padding(
                      padding: const EdgeInsets.only(
                        bottom: 11,
                      ),
                      child: FarmCard(
                        padding: const EdgeInsets.all(
                          14,
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            // ----------------------------
                            // ORDER HEADER
                            // ----------------------------

                            Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Container(
                                  width: 40,
                                  height: 40,
                                  decoration: BoxDecoration(
                                    color: statusColor.withOpacity(
                                      0.10,
                                    ),
                                    borderRadius: BorderRadius.circular(
                                      13,
                                    ),
                                  ),
                                  child: Icon(
                                    Icons.inventory_2_outlined,
                                    color: statusColor,
                                    size: 20,
                                  ),
                                ),
                                const SizedBox(
                                  width: 10,
                                ),
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        request?.businessName
                                                    .trim()
                                                    .isNotEmpty ==
                                                true
                                            ? request!.businessName
                                            : 'Wholesale Order',
                                        style: const TextStyle(
                                          color: FarmColors.ink,
                                          fontSize: 14,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      const SizedBox(
                                        height: 2,
                                      ),
                                      Text(
                                        request == null
                                            ? 'Wholesale request'
                                            : 'Request #${request.shortId}',
                                        style: const TextStyle(
                                          color: FarmColors.mutedText,
                                          fontSize: 10,
                                          fontWeight: FontWeight.w700,
                                        ),
                                      ),
                                    ],
