// =====================================================
// RECORD PAYMENT
// =====================================================

  Future<void> _recordInvoicePayment(
    WholesaleInvoice invoice,
  ) async {
    final amountController = TextEditingController(
      text: invoice.amountDue.toStringAsFixed(
        2,
      ),
    );

    final referenceController = TextEditingController();

    final noteController = TextEditingController();

    String method = 'bank_transfer';

    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return StatefulBuilder(
          builder: (
            context,
            setDialogState,
          ) {
            return AlertDialog(
              title: Text(
                'Record Payment • ${invoice.invoiceNumber}',
              ),
              content: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Outstanding: ${invoice.formattedDue}',
                      style: const TextStyle(
                        color: FarmColors.green,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(
                      height: 14,
                    ),
                    TextField(
                      controller: amountController,
                      keyboardType: const TextInputType.numberWithOptions(
                        decimal: true,
                      ),
                      decoration: const InputDecoration(
                        labelText: 'Payment amount',
                        prefixText: 'J\$ ',
                      ),
                    ),
                    const SizedBox(
                      height: 10,
                    ),
                    DropdownButtonFormField<String>(
                      value: method,
                      isExpanded: true,
                      decoration: const InputDecoration(
                        labelText: 'Payment method',
                      ),
                      items: const [
                        DropdownMenuItem(
                          value: 'bank_transfer',
                          child: Text(
                            'Bank Transfer',
                          ),
                        ),
                        DropdownMenuItem(
                          value: 'cash',
                          child: Text(
                            'Cash',
                          ),
                        ),
                        DropdownMenuItem(
                          value: 'card',
                          child: Text(
                            'Card',
                          ),
                        ),
                        DropdownMenuItem(
                          value: 'cheque',
                          child: Text(
                            'Cheque',
                          ),
                        ),
                        DropdownMenuItem(
                          value: 'other',
                          child: Text(
                            'Other',
                          ),
                        ),
                      ],
                      onChanged: (value) {
                        if (value == null) {
                          return;
                        }

                        setDialogState(
                          () {
                            method = value;
                          },
                        );
                      },
                    ),
                    const SizedBox(
                      height: 10,
                    ),
                    TextField(
                      controller: referenceController,
                      decoration: const InputDecoration(
                        labelText: 'Payment reference',
                        hintText: 'Bank reference, cheque number, etc.',
                      ),
                    ),
                    const SizedBox(
                      height: 10,
                    ),
                    TextField(
                      controller: noteController,
                      minLines: 2,
                      maxLines: 3,
                      decoration: const InputDecoration(
                        labelText: 'Payment note',
                      ),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(
                    dialogContext,
                    false,
                  ),
                  child: const Text(
                    'Back',
                  ),
                ),
                ElevatedButton(
                  onPressed: () => Navigator.pop(
                    dialogContext,
                    true,
                  ),
                  child: const Text(
                    'Record Payment',
                  ),
                ),
              ],
            );
          },
        );
      },
    );

    if (saved != true) {
      amountController.dispose();
      referenceController.dispose();
      noteController.dispose();

      return;
    }

    final amount = double.tryParse(
      amountController.text.trim().replaceAll(
            ',',
            '',
          ),
    );

    if (amount == null || amount <= 0 || amount > invoice.amountDue + 0.01) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Enter a payment between J\$0.01 and ${invoice.formattedDue}.',
            ),
          ),
        );
      }

      amountController.dispose();
      referenceController.dispose();
      noteController.dispose();

      return;
    }

    try {
      final updated = await recordWholesaleInvoicePayment(
        invoice: invoice,
        amount: amount,
        paymentMethod: method,
        paymentReference: referenceController.text,
        paymentNote: noteController.text,
      );

      await _refresh();

      widget.onChanged();

      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            updated.isPaid
                ? '${updated.invoiceNumber} is fully paid.'
                : 'Payment recorded. Balance: ${updated.formattedDue}.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(
              error,
            ),
          ),
        ),
      );
    } finally {
      amountController.dispose();
      referenceController.dispose();
      noteController.dispose();
    }
  }

// =====================================================
// REVERSE PAYMENT
// =====================================================

  Future<void> _reverseInvoicePayment(
    WholesaleInvoice invoice,
    WholesaleInvoicePayment payment,
  ) async {
    final controller = TextEditingController();

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text(
            'Reverse Payment?',
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                payment.formattedAmount,
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 18,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(
                height: 12,
              ),
              TextField(
                controller: controller,
                minLines: 2,
                maxLines: 4,
                decoration: const InputDecoration(
                  labelText: 'Reason',
                  hintText: 'Why is this payment being reversed?',
                ),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                false,
              ),
              child: const Text(
                'Back',
              ),
            ),
            TextButton(
              onPressed: () => Navigator.pop(
                dialogContext,
                true,
              ),
              child: const Text(
                'Reverse Payment',
              ),
            ),
          ],
        );
      },
    );

    if (confirmed != true) {
      controller.dispose();
      return;
    }

    if (controller.text.trim().isEmpty) {
      controller.dispose();

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Enter a reason for reversing the payment.',
            ),
          ),
        );
      }

      return;
    }

    try {
      await reverseWholesaleInvoicePayment(
        invoice: invoice,
        payment: payment,
        reason: controller.text,
      );

      await _refresh();

      widget.onChanged();

      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Payment reversed. Invoice balance recalculated.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(
              error,
            ),
          ),
        ),
      );
    } finally {
      controller.dispose();
    }
  }

