  String _wholesalePdfClean(
    String? value, {
    String fallback = '',
  }) {
    final clean = value
            ?.replaceAll('•', '-')
            .replaceAll('–', '-')
            .replaceAll('—', '-')
            .replaceAll('\u00A0', ' ')
            .trim() ??
        '';

    return clean.isEmpty ? fallback : clean;
  }

  String _wholesalePdfDate(
    DateTime? value,
  ) {
    if (value == null) {
      return 'Not available';
    }

    final date = value.toLocal();

    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return '${months[date.month - 1]} '
        '${date.day}, ${date.year}';
  }

  String _wholesalePdfMoney(
    double value,
  ) {
    return 'J\$${value.toStringAsFixed(2)}';
  }

  String _shortWholesalePdfId(
    String value,
  ) {
    final clean = value
        .replaceAll(
          RegExp(
            r'[^A-Za-z0-9]',
          ),
          '',
        )
        .toUpperCase();

    if (clean.length <= 8) {
      return clean;
    }

    return clean.substring(
      0,
      8,
    );
  }

