  Future<Uint8List> _buildWholesaleInvoicePdf(
    WholesaleInvoice invoice,
  ) async {
    final pdf = pw.Document();

    final logo = await _loadWholesalePdfLogo();

    final green = PdfColor.fromInt(
      0xFF1F6B3A,
    );

    final softGreen = PdfColor.fromInt(
      0xFFEAF3EC,
    );

    final requestRef = _shortWholesalePdfId(
      invoice.requestId,
    );

    pw.Widget tableCell(
      String value, {
      bool bold = false,
      pw.TextAlign align = pw.TextAlign.left,
      PdfColor? color,
    }) {
      return pw.Padding(
        padding: const pw.EdgeInsets.symmetric(
          horizontal: 6,
          vertical: 6,
        ),
        child: pw.Text(
          _wholesalePdfClean(
            value,
          ),
          textAlign: align,
          style: pw.TextStyle(
            fontSize: 8.5,
            fontWeight: bold ? pw.FontWeight.bold : pw.FontWeight.normal,
            color: color ?? PdfColors.black,
