// =====================================================
// BUILD PAYMENT RECEIPT PDF
// =====================================================

  Future<Uint8List> _buildWholesalePaymentReceiptPdf(
    WholesaleInvoice invoice,
    WholesaleInvoicePayment payment,
  ) async {
    if (payment.isReversed) {
      throw Exception(
        'A reversed payment cannot produce an active receipt.',
      );
    }

    final pdf = pw.Document();

    final logo = await _loadWholesalePdfLogo();

    final green = PdfColor.fromInt(
      0xFF1F6B3A,
    );

    final confirmed = invoice.payments
        .where(
          (item) => item.isConfirmed,
        )
        .toList()
      ..sort(
        (a, b) {
          final aDate = a.paidAt ??
              DateTime.fromMillisecondsSinceEpoch(
                0,
              );

          final bDate = b.paidAt ??
              DateTime.fromMillisecondsSinceEpoch(
                0,
              );

          return aDate.compareTo(
            bDate,
          );
        },
      );

    double paidToDate = 0;

    bool found = false;

    for (final item in confirmed) {
      paidToDate += item.amount;

      if (item.id == payment.id) {
        found = true;
        break;
      }
    }

    if (!found) {
      paidToDate = invoice.paidAmount;
    }

    final balanceAfter = invoice.totalAmount - paidToDate;

    final cleanBalance = balanceAfter < 0 ? 0.0 : balanceAfter;

    final receiptNumber = _shortWholesalePdfId(
      payment.id,
    );

    pdf.addPage(
      pw.Page(
        pageFormat: PdfPageFormat.a4,
        margin: const pw.EdgeInsets.all(
          38,
        ),
        build: (context) {
          return pw.Column(
            crossAxisAlignment: pw.CrossAxisAlignment.start,
            children: [
              _wholesalePdfHeader(
                logo: logo,
                documentTitle: 'OFFICIAL WHOLESALE PAYMENT RECEIPT',
                reference: 'Receipt #$receiptNumber',
              ),
              pw.SizedBox(
                height: 22,
              ),
              pw.Row(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  pw.Expanded(
                    child: _wholesalePdfInfoBox(
                      title: 'RECEIVED FROM',
                      lines: [
                        invoice.businessName.trim().isEmpty
                            ? 'Wholesale Business'
                            : invoice.businessName,
                        if (invoice.contactName.trim().isNotEmpty)
                          invoice.contactName,
                        if (invoice.contactPhone.trim().isNotEmpty)
                          invoice.contactPhone,
                      ],
                    ),
                  ),
                  pw.SizedBox(
                    width: 12,
                  ),
                  pw.Expanded(
                    child: _wholesalePdfInfoBox(
                      title: 'PAYMENT DETAILS',
                      lines: [
                        'Invoice: ${invoice.invoiceNumber}',
                        'Date: ${_wholesalePdfDate(payment.paidAt)}',
                        'Method: ${payment.methodLabel}',
                        if (payment.paymentReference.isNotEmpty)
                          'Reference: ${payment.paymentReference}',
                      ],
                    ),
                  ),
                ],
              ),
              pw.SizedBox(
                height: 22,
              ),
              pw.Container(
                width: double.infinity,
                padding: const pw.EdgeInsets.all(
                  18,
                ),
                decoration: pw.BoxDecoration(
                  color: PdfColor.fromInt(
                    0xFFEAF3EC,
                  ),
                  borderRadius: pw.BorderRadius.circular(
                    10,
                  ),
                ),
                child: pw.Column(
                  children: [
                    pw.Text(
                      'PAYMENT RECEIVED',
                      style: pw.TextStyle(
                        color: green,
                        fontSize: 10,
                        fontWeight: pw.FontWeight.bold,
                      ),
                    ),
                    pw.SizedBox(
                      height: 8,
                    ),
                    pw.Text(
                      _wholesalePdfMoney(
                        payment.amount,
                      ),
                      style: pw.TextStyle(
                        color: green,
                        fontSize: 27,
                        fontWeight: pw.FontWeight.bold,
                      ),
                    ),
                  ],
                ),
              ),
              pw.SizedBox(
                height: 22,
              ),
              pw.Container(
                padding: const pw.EdgeInsets.all(
                  14,
                ),
                decoration: pw.BoxDecoration(
                  border: pw.Border.all(
                    color: PdfColors.grey300,
                  ),
                  borderRadius: pw.BorderRadius.circular(
                    8,
                  ),
                ),
                child: pw.Column(
                  children: [
                    _wholesalePdfAmountRow(
                      'Invoice Total',
                      _wholesalePdfMoney(
                        invoice.totalAmount,
                      ),
                      strong: true,
                    ),
                    _wholesalePdfAmountRow(
                      'This Payment',
                      _wholesalePdfMoney(
                        payment.amount,
                      ),
                      green: true,
                    ),
                    _wholesalePdfAmountRow(
                      'Paid To Date',
                      _wholesalePdfMoney(
                        paidToDate,
                      ),
                    ),
                    pw.Divider(),
                    _wholesalePdfAmountRow(
                      'Remaining Balance',
                      _wholesalePdfMoney(
                        cleanBalance,
                      ),
                      strong: true,
                      green: cleanBalance <= 0.01,
                    ),
                  ],
                ),
              ),
              if (payment.paymentNote.trim().isNotEmpty) ...[
                pw.SizedBox(
                  height: 18,
                ),
                pw.Text(
                  'PAYMENT NOTE',
                  style: pw.TextStyle(
                    fontSize: 10,
                    fontWeight: pw.FontWeight.bold,
                    color: green,
                  ),
                ),
                pw.SizedBox(
                  height: 5,
                ),
                pw.Text(
                  _wholesalePdfClean(
                    payment.paymentNote,
                  ),
                  style: const pw.TextStyle(
                    fontSize: 9,
                  ),
                ),
              ],
              pw.Spacer(),
              pw.Container(
                width: double.infinity,
                padding: const pw.EdgeInsets.symmetric(
                  vertical: 10,
                ),
                decoration: pw.BoxDecoration(
                  color: green,
                  borderRadius: pw.BorderRadius.circular(
                    5,
                  ),
                ),
                child: pw.Center(
                  child: pw.Text(
                    cleanBalance <= 0.01
                        ? 'PAID IN FULL'
                        : 'PAYMENT RECEIVED - THANK YOU',
                    style: pw.TextStyle(
                      color: PdfColors.white,
                      fontSize: 11,
                      fontWeight: pw.FontWeight.bold,
                    ),
                  ),
                ),
              ),
              pw.SizedBox(
                height: 8,
              ),
              pw.Center(
                child: pw.Text(
                  'This receipt confirms payment recorded against '
                  '${invoice.invoiceNumber}.',
                  style: const pw.TextStyle(
                    fontSize: 8,
                    color: PdfColors.grey600,
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );

    return pdf.save();
  }

// =====================================================
// SHARE / SAVE INVOICE
// =====================================================

  Future<void> _shareWholesaleInvoicePdf(
    WholesaleInvoice invoice,
  ) async {
    try {
      final bytes = await _buildWholesaleInvoicePdf(
        invoice,
      );

      final safeNumber = invoice.invoiceNumber.replaceAll(
        RegExp(
          r'[^A-Za-z0-9_-]',
        ),
        '_',
      );

      await Printing.sharePdf(
        bytes: bytes,
        filename: '$safeNumber.pdf',
      );
    } catch (error) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Could not create invoice PDF: '
            '${friendlyAppError(error)}',
          ),
        ),
      );
    }
  }

// =====================================================
// PRINT INVOICE
// =====================================================

  Future<void> _printWholesaleInvoicePdf(
    WholesaleInvoice invoice,
  ) async {
    try {
      await Printing.layoutPdf(
        name: invoice.invoiceNumber,
        format: PdfPageFormat.a4,
        onLayout: (_) => _buildWholesaleInvoicePdf(
          invoice,
        ),
      );
    } catch (error) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Could not print invoice: '
            '${friendlyAppError(error)}',
          ),
        ),
      );
    }
  }

// =====================================================
// SHARE / SAVE PAYMENT RECEIPT
// =====================================================

  Future<void> _shareWholesalePaymentReceiptPdf(
    WholesaleInvoice invoice,
    WholesaleInvoicePayment payment,
  ) async {
    try {
      final bytes = await _buildWholesalePaymentReceiptPdf(
        invoice,
        payment,
      );

      final receiptId = _shortWholesalePdfId(
        payment.id,
      );

      await Printing.sharePdf(
        bytes: bytes,
        filename: 'HPJ-Wholesale-Receipt-$receiptId.pdf',
      );
    } catch (error) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Could not create payment receipt: '
            '${friendlyAppError(error)}',
          ),
        ),
      );
    }
  }

