  Future<void> _approvePaymentConfirmation(
    WholesalePaymentSubmission submission,
  ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Approve Payment?'),
        content: Text(
          'Approve ${submission.formattedAmount} for '
          '${submission.invoiceNumber.isEmpty ? 'this invoice' : submission.invoiceNumber}?\n\n'
          'This will record the payment and immediately recalculate the invoice balance.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Back'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Approve Payment'),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    try {
      await approveWholesalePaymentConfirmation(submission);
      await _refresh();
      widget.onChanged();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Payment approved and invoice balance updated.'),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _rejectPaymentConfirmation(
    WholesalePaymentSubmission submission,
  ) async {
    final controller = TextEditingController();

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Payment Needs Attention'),
        content: TextField(
          controller: controller,
          minLines: 2,
          maxLines: 4,
          decoration: const InputDecoration(
            labelText: 'Reason',
            hintText: 'Example: amount does not match the bank transaction.',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Back'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Send Back'),
          ),
        ],
      ),
    );

    if (confirmed != true) {
      controller.dispose();
      return;
    }

    final reason = controller.text.trim();
    if (reason.isEmpty) {
      controller.dispose();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter a reason first.')),
      );
      return;
    }

    try {
      await rejectWholesalePaymentConfirmation(
        submission: submission,
        reason: reason,
      );
      await _refresh();
      widget.onChanged();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Payment confirmation returned to the business.'),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      controller.dispose();
    }
  }

