  Widget _invoicesTab() {
    return FutureBuilder<List<Object>>(
      future: Future.wait<Object>([
        invoicesFuture,
        requestsFuture,
        fulfillmentFuture,
        paymentSubmissionsFuture,
      ]),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting &&
            !snapshot.hasData) {
          return const Center(
            child: CircularProgressIndicator(),
          );
        }

        if (snapshot.hasError) {
          return Center(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Text(
                friendlyAppError(snapshot.error!),
                textAlign: TextAlign.center,
              ),
            ),
          );
        }

        final data = snapshot.data;

        if (data == null) {
          return const SizedBox.shrink();
        }

        final allInvoices = data[0] as List<WholesaleInvoice>;

        final requestedInvoiceId =
            widget.invoiceIdFilter?.trim() ?? '';

        final focusedInvoices = requestedInvoiceId.isEmpty
            ? const <WholesaleInvoice>[]
            : allInvoices
                .where(
                  (invoice) => invoice.id.trim() == requestedInvoiceId,
                )
                .toList();

        final exactInvoiceFound = focusedInvoices.isNotEmpty;
        final invoices =
            exactInvoiceFound ? focusedInvoices : allInvoices;

        final requests = data[1] as List<WholesaleOrderRequest>;

        final fulfillments = data[2] as List<WholesaleFulfillment>;

        final paymentSubmissions = data[3] as List<WholesalePaymentSubmission>;

        final pendingPaymentSubmissions =
            paymentSubmissions.where((item) => item.isPending).toList();

        final requestById = <String, WholesaleOrderRequest>{
          for (final request in requests) request.id: request,
        };

        final activeInvoiceRequestIds = allInvoices
            .where(
              (invoice) => !invoice.isVoid,
            )
            .map(
              (invoice) => invoice.requestId,
            )
            .toSet();

        final readyToInvoice = <WholesaleOrderRequest>[];

        for (final fulfillment in fulfillments) {
          if (!fulfillment.isReadyForDispatch) {
            continue;
          }

          if (activeInvoiceRequestIds.contains(
            fulfillment.requestId,
          )) {
            continue;
          }

          final request = requestById[fulfillment.requestId];

          if (request == null) {
            continue;
          }

          if (request.status != 'approved' && request.status != 'fulfilled') {
            continue;
          }

          readyToInvoice.add(request);
        }

        final draftCount = allInvoices
            .where(
              (invoice) => invoice.isDraft,
            )
            .length;

        final overdueCount = allInvoices
            .where(
              (invoice) => invoice.isOverdue,
            )
            .length;

        final paidCount = allInvoices
            .where(
              (invoice) => invoice.isPaid && !invoice.isVoid,
            )
            .length;

        final outstanding = allInvoices
            .where(
              (invoice) =>
                  invoice.isIssued && !invoice.isPaid && !invoice.isVoid,
            )
            .fold<double>(
              0,
              (total, invoice) => total + invoice.amountDue,
            );

        return RefreshIndicator(
          onRefresh: _refresh,
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(
              14,
              14,
              14,
              100,
            ),
