                              fontSize: 10.5,
                              height: 1.3,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 12),
              if (requestedInvoiceId.isNotEmpty) ...[
                _WholesaleAdminFocusNotice(
                  found: exactInvoiceFound,
