  Widget _invoiceAmountRow({
    required String label,
    required String value,
    bool strong = false,
  }) {
    return Padding(
      padding: const EdgeInsets.symmetric(
        vertical: 2,
      ),
      child: Row(
        children: [
          Expanded(
            child: Text(
              label,
              style: TextStyle(
                color: strong ? FarmColors.ink : FarmColors.mutedText,
                fontSize: strong ? 11 : 10,
                fontWeight: strong ? FontWeight.w900 : FontWeight.w700,
              ),
            ),
          ),
          Text(
            value,
            style: TextStyle(
              color: strong ? FarmColors.ink : FarmColors.mutedText,
              fontSize: strong ? 12 : 10,
              fontWeight: strong ? FontWeight.w900 : FontWeight.w700,
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _changeStandingOrderAdminStatus(
    WholesaleStandingOrder order,
    String status,
  ) async {
    final noteController = TextEditingController();
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(
          status == 'active'
              ? 'Approve standing order'
              : '${status.replaceAll('_', ' ')} standing order',
        ),
        content: TextField(
          controller: noteController,
          maxLines: 3,
          decoration: const InputDecoration(
            labelText: 'HPJ note (optional)',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Confirm'),
          ),
        ],
      ),
    );

    if (confirmed != true) {
      noteController.dispose();
      return;
    }

    try {
      await adminUpdateWholesaleStandingOrderStatus(
        order: order,
        status: status,
        adminNote: noteController.text,
      );
      await _refresh();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Standing order updated.')),
        );
      }
    } catch (error) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(friendlyAppError(error))),
        );
      }
    } finally {
      noteController.dispose();
    }
  }

  Widget _recurringOrdersTab() {
    return FutureBuilder<List<WholesaleStandingOrder>>(
      future: standingOrdersFuture,
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting &&
            !snapshot.hasData) {
          return const Center(child: CircularProgressIndicator());
        }
        if (snapshot.hasError) {
          return Center(child: Text(friendlyAppError(snapshot.error!)));
        }

        final orders = snapshot.data ?? const <WholesaleStandingOrder>[];
        final proposed = orders.where((item) => item.isProposed).length;
        final active = orders.where((item) => item.isActive).length;
        final paused = orders.where((item) => item.isPaused).length;

        return RefreshIndicator(
          onRefresh: _refresh,
          child: ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(14, 14, 14, 100),
            children: [
              FarmCard(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Row(
                      children: [
                        Icon(Icons.event_repeat_rounded,
                            color: FarmColors.primary),
                        SizedBox(width: 10),
                        Expanded(
                          child: Text(
                            'Standing Orders',
                            style: TextStyle(
                              color: FarmColors.ink,
                              fontSize: 17,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 7),
                    Text(
                      'Awaiting approval: $proposed • Active: $active • Paused: $paused',
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 5),
                    const Text(
                      'Standing orders reserve a recurring business intent, not stock or capacity. Each generated request still passes live availability, scheduling and credit controls.',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10.5,
                        height: 1.35,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 12),
              if (orders.isEmpty)
                const FarmEmptyState(
                  icon: Icons.event_busy_outlined,
                  title: 'No standing orders yet',
                  message:
                      'Business customers can create a standing order from one of their saved repeat-order templates.',
                )
              else
                ...orders.map((order) {
                  final color = order.isActive
                      ? FarmColors.success
                      : order.isRejected || order.isCancelled
                          ? FarmColors.danger
                          : order.isPaused
                              ? FarmColors.warning
                              : FarmColors.primary;
                  final next = order.nextDueDate?.toLocal();
                  final nextLabel = next == null
                      ? 'Not set'
                      : '${next.day}/${next.month}/${next.year}';

                  return Padding(
                    padding: const EdgeInsets.only(bottom: 10),
                    child: FarmCard(
                      padding: const EdgeInsets.all(14),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              Expanded(
                                child: Text(
                                  order.businessName.isEmpty
                                      ? order.name
                                      : '${order.businessName} • ${order.name}',
                                  style: const TextStyle(
                                    color: FarmColors.ink,
                                    fontSize: 14,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              ),
                              Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 8,
                                  vertical: 5,
                                ),
                                decoration: BoxDecoration(
                                  color: color.withOpacity(0.10),
                                  borderRadius: BorderRadius.circular(999),
                                ),
                                child: Text(
                                  order.statusLabel,
                                  style: TextStyle(
                                    color: color,
                                    fontSize: 9,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 6),
                          Text(
                            '${order.frequencyLabel} • ${order.dispatchMethodLabel} • Next $nextLabel • ${order.items.length} item${order.items.length == 1 ? '' : 's'}',
                            style: const TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 10.5,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                          const SizedBox(height: 10),
                          Wrap(
                            spacing: 7,
                            runSpacing: 7,
                            children: [
                              if (order.isProposed)
                                ElevatedButton.icon(
                                  onPressed: () =>
                                      _changeStandingOrderAdminStatus(
                                    order,
                                    'active',
                                  ),
                                  icon: const Icon(Icons.check_circle_outline,
                                      size: 17),
                                  label: const Text('Approve'),
                                ),
                              if (order.isProposed)
                                OutlinedButton(
                                  onPressed: () =>
                                      _changeStandingOrderAdminStatus(
                                    order,
                                    'rejected',
                                  ),
                                  child: const Text('Needs Attention'),
                                ),
                              if (order.isActive)
                                OutlinedButton(
                                  onPressed: () =>
                                      _changeStandingOrderAdminStatus(
                                    order,
                                    'paused',
                                  ),
                                  child: const Text('Pause'),
                                ),
                              if (order.isPaused)
                                ElevatedButton(
                                  onPressed: () =>
                                      _changeStandingOrderAdminStatus(
                                    order,
                                    'active',
                                  ),
                                  child: const Text('Resume'),
                                ),
                              if (order.isActive || order.isPaused)
                                TextButton(
                                  onPressed: () =>
                                      _changeStandingOrderAdminStatus(
                                    order,
                                    'cancelled',
                                  ),
                                  child: const Text('Cancel'),
                                ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  );
                }),
            ],
          ),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final allSections = <_WholesaleAdminSectionSpec>[
      _WholesaleAdminSectionSpec(
        keyName: 'executive',
        tab: const Tab(icon: Icon(Icons.dashboard_outlined), text: 'Executive'),
        child: const ExecutiveIntelligenceScreen(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'applications',
        tab: const Tab(icon: Icon(Icons.business_outlined), text: 'Applications'),
        child: _applicationsTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'access',
        tab: const Tab(icon: Icon(Icons.admin_panel_settings_outlined), text: 'Access'),
        child: const OwnerMarketplaceProgramSettingsPanel(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'pricing',
        tab: const Tab(icon: Icon(Icons.price_change_outlined), text: 'Pricing'),
        child: _pricingTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'requests',
        tab: const Tab(icon: Icon(Icons.inventory_2_outlined), text: 'Orders'),
        child: _requestsTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'procurement',
        tab: const Tab(icon: Icon(Icons.account_tree_outlined), text: 'Procurement'),
        child: _matchingTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'receiving',
        tab: Tab(
          icon: const Icon(Icons.warehouse_outlined),
          text: widget.receivingMode == 'collections'
              ? 'Collections'
              : widget.receivingMode == 'receiving'
                  ? 'Receiving'
                  : 'Collections & Receiving',
        ),
        child: _receivingTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'warehouse',
        tab: const Tab(icon: Icon(Icons.factory_outlined), text: 'Warehouse'),
        child: const WarehouseOperationsPanel(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'fulfillment',
        tab: const Tab(
          icon: Icon(Icons.inventory_outlined),
          text: 'Prepare & Pack',
        ),
        child: _fulfillmentTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'recurring',
        tab: const Tab(icon: Icon(Icons.event_repeat_rounded), text: 'Recurring'),
        child: _recurringOrdersTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'invoices',
        tab: const Tab(icon: Icon(Icons.receipt_long_outlined), text: 'Invoices'),
        child: _invoicesTab(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'finance',
        tab: const Tab(icon: Icon(Icons.account_balance_wallet_outlined), text: 'Finance'),
        child: const WholesaleFinanceScreen(),
      ),
      _WholesaleAdminSectionSpec(
        keyName: 'dispatch',
        tab: const Tab(
          icon: Icon(Icons.local_shipping_outlined),
          text: 'Delivery',
        ),
        child: _dispatchTab(),
      ),
    ];

    final requested = widget.sections
        ?.map((value) => value.trim().toLowerCase())
        .where((value) => value.isNotEmpty)
        .toSet();

    final sections = requested == null || requested.isEmpty
        ? allSections
        : allSections
            .where((section) => requested.contains(section.keyName))
            .toList();

    if (sections.isEmpty) {
      return const FarmEmptyState(
        icon: Icons.grid_view_outlined,
        title: 'No wholesale tools selected',
        message: 'This workspace has no wholesale sections assigned.',
      );
    }

    final requestedInitial = widget.initialSection.trim().toLowerCase();
    final initialIndex = sections.indexWhere(
      (section) => section.keyName == requestedInitial,
    );

    return DefaultTabController(
      key: ValueKey(
        'wholesale-${sections.map((section) => section.keyName).join('-')}-$requestedInitial-${widget.receivingMode}-${widget.receivingFilter}-${widget.requestStatusFilter ?? ''}-${widget.requestIdFilter ?? ''}-${widget.businessAccountIdFilter ?? ''}-${widget.invoiceIdFilter ?? ''}-${widget.demandIdFilter ?? ''}',
      ),
      length: sections.length,
      initialIndex: initialIndex < 0 ? 0 : initialIndex,
      child: Column(
        children: [
          if (sections.length > 1)
            Material(
              color: Colors.transparent,
              child: TabBar(
                isScrollable: true,
                tabs: [for (final section in sections) section.tab],
              ),
            ),
          Expanded(
            child: TabBarView(
              physics: sections.length == 1
                  ? const NeverScrollableScrollPhysics()
                  : null,
              children: [for (final section in sections) section.child],
            ),
          ),
        ],
      ),
    );
  }
}

class _WholesaleFulfillmentShortageSheet
    extends StatefulWidget {
  final WholesaleFulfillmentItem item;

  const _WholesaleFulfillmentShortageSheet({
    required this.item,
  });

  @override
  State<_WholesaleFulfillmentShortageSheet>
      createState() =>
          _WholesaleFulfillmentShortageSheetState();
}

class _WholesaleFulfillmentShortageSheetState
    extends State<_WholesaleFulfillmentShortageSheet> {
  late final TextEditingController
      packedController;
  late final TextEditingController
      shortageController;
  late final TextEditingController
      noteController;

  bool saving = false;

  WholesaleFulfillmentItem get item =>
      widget.item;

  @override
  void initState() {
    super.initState();

    packedController =
        TextEditingController();

    shortageController =
        TextEditingController();

    noteController =
        TextEditingController();
  }

  @override
  void dispose() {
    packedController.dispose();
    shortageController.dispose();
    noteController.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (saving) return;

    final packed = double.tryParse(
      packedController.text
          .trim()
          .replaceAll(',', ''),
    );

    final shortage = double.tryParse(
      shortageController.text
          .trim()
          .replaceAll(',', ''),
    );

    if (packed == null ||
        shortage == null ||
        packed < 0 ||
        shortage <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Enter valid packed and shortage quantities.',
          ),
        ),
      );
      return;
    }

    if ((packed +
                    shortage -
                    item.orderedQuantity)
                .abs() >
            0.001) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Packed + shortage must equal ${item.orderedLabel}.',
          ),
        ),
      );
      return;
    }

    setState(() {
      saving = true;
    });

    try {
      await markWholesaleFulfillmentItemShort(
        item: item,
        packedQuantity: packed,
        shortageQuantity: shortage,
        substitutionNote:
            noteController.text,
      );

      if (!mounted) return;

      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;

      setState(() {
        saving = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            _wholesaleWarehouseError(error),
          ),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedPadding(
      duration:
          const Duration(milliseconds: 160),
      curve: Curves.easeOut,
      padding: EdgeInsets.only(
        bottom:
            MediaQuery.of(context).viewInsets.bottom,
      ),
      child: Container(
        decoration: const BoxDecoration(
          color: FarmColors.card,
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(26),
          ),
        ),
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(
            18,
            14,
            18,
            22,
          ),
          child: Column(
            crossAxisAlignment:
                CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: FarmColors.line,
                    borderRadius:
                        BorderRadius.circular(99),
                  ),
                ),
              ),
              const SizedBox(height: 16),

              Text(
                'Shortage • ${item.productName}',
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 5),

              Text(
                'Ordered ${item.orderedLabel}. Record exactly what was packed and what is unavailable.',
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.5,
                  height: 1.35,
                  fontWeight: FontWeight.w600,
                ),
              ),

              const SizedBox(height: 16),

              TextField(
                controller: packedController,
                enabled: !saving,
                keyboardType:
                    const TextInputType.numberWithOptions(
                  decimal: true,
                ),
                decoration: InputDecoration(
                  labelText: 'Quantity packed',
                  suffixText: item.unit,
                ),
              ),

              const SizedBox(height: 11),

              TextField(
                controller: shortageController,
                enabled: !saving,
                keyboardType:
                    const TextInputType.numberWithOptions(
                  decimal: true,
                ),
                decoration: InputDecoration(
                  labelText: 'Shortage quantity',
                  suffixText: item.unit,
                ),
              ),

              const SizedBox(height: 11),

              TextField(
                controller: noteController,
                enabled: !saving,
                minLines: 2,
                maxLines: 3,
                decoration: const InputDecoration(
                  labelText:
                      'Shortage / substitution note',
                  hintText:
                      'Explain what is unavailable or any proposed substitute.',
                ),
              ),

              const SizedBox(height: 18),

              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed:
                      saving ? null : _save,
                  child: Text(
                    saving
                        ? 'Saving...'
                        : 'Save Shortage',
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

