class _WholesaleFulfillmentRemoveSheetState
    extends State<_WholesaleFulfillmentRemoveSheet> {
  late final TextEditingController
      reasonController;

  bool saving = false;

  WholesaleFulfillmentItem get item =>
      widget.item;

  @override
  void initState() {
    super.initState();

    reasonController =
        TextEditingController();
  }

  @override
  void dispose() {
    reasonController.dispose();
    super.dispose();
  }

  Future<void> _remove() async {
    if (saving) return;

    final reason =
        reasonController.text.trim();

    if (reason.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Enter a reason before removing the item.',
          ),
        ),
      );
      return;
    }

    setState(() {
      saving = true;
    });

    try {
      await removeWholesaleFulfillmentItem(
        item: item,
        reason: reason,
      );

      if (!mounted) return;

      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;

      setState(() {
        saving = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            _wholesaleWarehouseError(error),
          ),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedPadding(
      duration:
          const Duration(milliseconds: 160),
      curve: Curves.easeOut,
      padding: EdgeInsets.only(
        bottom:
            MediaQuery.of(context).viewInsets.bottom,
      ),
      child: Container(
        decoration: const BoxDecoration(
          color: FarmColors.card,
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(26),
          ),
        ),
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(
            18,
            14,
            18,
            22,
          ),
          child: Column(
            crossAxisAlignment:
                CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: FarmColors.line,
                    borderRadius:
                        BorderRadius.circular(99),
                  ),
                ),
              ),

              const SizedBox(height: 16),

              Text(
                'Remove ${item.productName}?',
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                ),
              ),

              const SizedBox(height: 5),

              const Text(
                'The line stays in the fulfilment history, but any unused warehouse reservation is released.',
