// ================================================================
// OWNER WORKSPACE SWITCHER
// Allows an authorised owner account to move between customer,
// administration, farmer, and wholesale workspaces using one login.
// Database permission checks remain unchanged.
// ================================================================

class OwnerWorkspaceAccessSnapshot {
  final String staffRole;
  final FarmerProfile? farmerProfile;
  final BusinessAccount? businessAccount;
  final MarketplaceProgramSettings programSettings;

  const OwnerWorkspaceAccessSnapshot({
    required this.staffRole,
    required this.farmerProfile,
    required this.businessAccount,
    required this.programSettings,
  });

  bool get isOwner => normalizeStaffRole(staffRole) == 'owner';

  bool get hasFarmerProfile => farmerProfile != null;

  bool get isApprovedFarmer => farmerProfile?.isApproved == true;

  bool get hasBusinessAccount => businessAccount != null;

  bool get isApprovedWholesale => businessAccount?.isApproved == true;
}

Future<OwnerWorkspaceAccessSnapshot> fetchOwnerWorkspaceAccessSnapshot() async {
  final staffRole = await fetchCurrentStaffRole();
  final farmerProfile = await fetchCurrentFarmerProfile();
  final programSettings = await fetchMarketplaceProgramSettings();
  final businessAccount = await fetchCurrentBusinessAccount();

  return OwnerWorkspaceAccessSnapshot(
    staffRole: staffRole,
    farmerProfile: farmerProfile,
    businessAccount: businessAccount,
    programSettings: programSettings,
  );
}

class OwnerWorkspaceSwitcherScreen
    extends StatefulWidget {
  final VoidCallback? onShopTap;
  final String currentWorkspace;
  final bool showCloseButton;

  const OwnerWorkspaceSwitcherScreen({
    super.key,
    this.onShopTap,
    this.currentWorkspace = '',
    this.showCloseButton = true,
  });

  @override
  State<OwnerWorkspaceSwitcherScreen> createState() =>
      _OwnerWorkspaceSwitcherScreenState();
}

class _OwnerWorkspaceSwitcherScreenState
    extends State<OwnerWorkspaceSwitcherScreen> {
  late Future<OwnerWorkspaceAccessSnapshot> _future;
  StreamSubscription<AuthState>? _authBoundarySubscription;
  String? _authBoundaryUserId;

  static const String _customerPhoto =
      'https://images.unsplash.com/photo-1775825772432-58a1a31dcf40'
      '?auto=format&fit=crop&w=1200&q=82';

  static const String _wholesalePhoto =
      'https://images.unsplash.com/photo-1769355104335-acef3aa4c9b6'
      '?auto=format&fit=crop&w=1200&q=82';

  static const String _farmerPhoto =
      'https://images.unsplash.com/photo-1767590954924-9ff1057b9f65'
      '?auto=format&fit=crop&w=1200&q=82';

  static const String _staffPhoto =
      'https://images.unsplash.com/photo-1770992225308-154250075727'
      '?auto=format&fit=crop&w=1200&q=82';

  @override
  void initState() {
    super.initState();
    _authBoundaryUserId =
        supabase.auth.currentUser?.id.trim();
    _future = _loadAccessForCurrentBoundary();

    _authBoundarySubscription =
        supabase.auth.onAuthStateChange.listen((authState) {
      if (!mounted) return;

      final rawUserId =
          authState.session?.user.id.trim() ?? '';
      final nextUserId =
          rawUserId.isEmpty ? null : rawUserId;
      final previousUserId = _authBoundaryUserId;

      if (nextUserId == previousUserId) return;

      _authBoundaryUserId = nextUserId;
      clearHpjPrivateAccountMemory();

      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute<void>(
            builder: (_) => nextUserId == null
                ? const AuthGate()
                : const OwnerWorkspaceSwitcherScreen(
                    showCloseButton: false,
                  ),
          ),
          (route) => false,
        );
      });
    });
  }

  Future<OwnerWorkspaceAccessSnapshot>
      _loadAccessForCurrentBoundary() async {
    final operationBoundary =
        captureHpjPrivateOperationBoundary();

    final snapshot = await fetchOwnerWorkspaceAccessSnapshot();

    if (!isHpjPrivateOperationBoundaryCurrent(operationBoundary)) {
      throw StateError(
        'Workspace access response became stale after account change.',
      );
    }

    return snapshot;
  }

  @override
  void dispose() {
    _authBoundarySubscription?.cancel();
    super.dispose();
  }

  Future<void> _reload() async {
    final next = _loadAccessForCurrentBoundary();

    if (mounted) {
      setState(() {
        _future = next;
      });
    }

    try {
      await next;
    } catch (error) {
      farmDebugLog(
        'Workspace access reload skipped: $error',
      );
    }
  }

  bool _isCurrent(String value) {
    return widget.currentWorkspace.trim().toLowerCase() ==
        value.trim().toLowerCase();
  }

  void _closeSwitcher() {
    Navigator.of(context).maybePop();
  }

  void _switchRoot(Widget screen) {
    Navigator.of(context).pushAndRemoveUntil(
      MaterialPageRoute<void>(
        builder: (_) => screen,
      ),
      (route) => false,
    );
  }

  Future<int> _rememberedTab(String workspace) async {
    final preference = await fetchHpjNavigationPreference();
    return preference?.tabFor(workspace) ?? 0;
  }

  void _openCustomer(bool marketplaceEnabled) {
    unawaited(() async {
      final tab = await _rememberedTab('customer');
      await saveHpjNavigationPreference(
        workspace: 'customer',
        tab: tab,
      );
      if (!mounted) return;

      if (!marketplaceEnabled) {
        _switchRoot(const CustomerMarketplaceComingSoonScreen());
        return;
      }

      final callback = widget.onShopTap;
      if (callback != null) {
        Navigator.of(context).pop();
        callback();
        return;
      }

      _switchRoot(
        MainNavigation(initialIndex: tab),
      );
    }());
  }

  void _openFarmer() {
    unawaited(() async {
      final tab = await _rememberedTab('farmer');
      await saveHpjNavigationPreference(
        workspace: 'farmer',
        tab: tab,
      );
      if (!mounted) return;
      _switchRoot(
        FarmerAccessGate(initialTab: tab),
      );
    }());
  }

  void _openWholesale() {
    unawaited(() async {
      final tab = await _rememberedTab('wholesale');
      await saveHpjNavigationPreference(
        workspace: 'wholesale',
        tab: tab,
      );
      if (!mounted) return;
      _switchRoot(
        BusinessWholesaleHubScreen(initialTab: tab),
      );
    }());
  }

  void _openStaff() {
    _switchRoot(
      const AdminDashboardScreen(),
    );
  }

  Future<void> _signOut() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text('Sign out of HPJ?'),
          content: const Text(
            'You will need to sign in again to open your approved workspaces.',
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('Sign Out'),
            ),
          ],
        );
      },
    );

    if (confirmed != true || !mounted) return;

    await signOutFromHpjSession();

    if (!mounted) return;

    Navigator.of(context).pushAndRemoveUntil(
      MaterialPageRoute<void>(
        builder: (_) => const AuthGate(),
      ),
      (route) => false,
    );
  }

  @override
  Widget build(BuildContext context) {
    const pageBackground = Color(0xFFF7F4EE);

    return Scaffold(
      backgroundColor: pageBackground,
      appBar: AppBar(
        backgroundColor: pageBackground,
        surfaceTintColor: Colors.transparent,
        automaticallyImplyLeading: false,
        leading: widget.showCloseButton
            ? IconButton(
                tooltip: 'Close',
                onPressed: _closeSwitcher,
                icon: const Icon(
                  Icons.close_rounded,
                ),
              )
            : null,
        titleSpacing: widget.showCloseButton ? 2 : 16,
        title: Row(
          children: [
            Container(
              width: 48,
              height: 34,
              padding: const EdgeInsets.all(3),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(10),
                border: Border.all(
                  color: const Color(0xFFE5E0D7),
                ),
              ),
              child: Image.asset(
                'lib/assets/images/logo.png',
                fit: BoxFit.contain,
                errorBuilder: (_, __, ___) => const Icon(
                  Icons.eco_outlined,
                  color: Color(0xFF0B4C36),
                  size: 20,
                ),
              ),
            ),
            const SizedBox(width: 10),
            const Text(
              'Workspaces',
              style: TextStyle(
                color: Color(0xFF173E31),
                fontSize: 19,
                fontWeight: FontWeight.w900,
                letterSpacing: -0.35,
              ),
            ),
          ],
        ),
        actions: [
          IconButton(
            tooltip: 'Refresh access',
            onPressed: _reload,
            icon: const Icon(
              Icons.refresh_rounded,
            ),
          ),
          IconButton(
            tooltip: 'Sign out',
            onPressed: _signOut,
            icon: const Icon(
              Icons.logout_rounded,
            ),
          ),
          const SizedBox(width: 4),
        ],
      ),
      body: SafeArea(
        top: false,
        child: FutureBuilder<OwnerWorkspaceAccessSnapshot>(
          future: _future,
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting &&
                snapshot.data == null) {
              return const _WorkspaceLoadingView();
            }

            final access = snapshot.data;

            if (access == null) {
              return _WorkspaceLoadErrorView(
                onRetry: _reload,
                onCustomerSelected: () => _openCustomer(false),
                onSignOut: () async {
                  await signOutFromHpjSession();
                  if (!mounted) return;
                  Navigator.of(context).pushAndRemoveUntil(
                    MaterialPageRoute<void>(
                      builder: (_) => const AuthGate(),
                    ),
                    (route) => false,
                  );
                },
              );
            }

            final hasStaffAccess = isStaffRoleActive(
              access.staffRole,
            );

            final customerEnabled =
                access.programSettings.customerMarketplaceEnabled;

            final customerCurrent =
                customerEnabled && _isCurrent('customer');

            final wholesaleCurrent =
                access.isApprovedWholesale &&
                access.programSettings.wholesaleWorkspaceEnabled &&
                _isCurrent('wholesale');

            final farmerCurrent =
                access.isApprovedFarmer &&
                access.programSettings.farmerWorkspaceEnabled &&
                _isCurrent('farmer');

            final staffCurrent =
                hasStaffAccess && _isCurrent('staff');

            final wholesaleStatus = wholesaleCurrent
                ? 'Current'
                : access.businessAccount == null
                    ? access.programSettings.wholesaleApplicationsEnabled
                        ? 'Apply'
                        : 'Paused'
                    : access.isApprovedWholesale
                        ? 'Approved'
                        : businessAccountStatusLabel(
                            access.businessAccount!.status,
                          );

            final wholesaleStatusColor = wholesaleCurrent
                ? const Color(0xFF2C754A)
                : access.isApprovedWholesale
                    ? const Color(0xFF2C754A)
                    : access.businessAccount == null &&
                            !access.programSettings.wholesaleApplicationsEnabled
                        ? const Color(0xFF78817D)
                        : businessAccountStatusColor(
                            access.businessAccount?.status,
                          );

            final farmerStatus = farmerCurrent
                ? 'Current'
                : access.farmerProfile == null
                    ? access.programSettings.farmerApplicationsEnabled
                        ? 'Apply'
                        : 'Paused'
                    : access.isApprovedFarmer
                        ? 'Approved'
                        : access.farmerProfile!.statusLabel;

            final farmerStatusColor = farmerCurrent
                ? const Color(0xFF2C754A)
                : access.isApprovedFarmer
                    ? const Color(0xFF2C754A)
                    : access.farmerProfile == null &&
                            !access.programSettings.farmerApplicationsEnabled
                        ? const Color(0xFF78817D)
                        : FarmColors.warning;

            final staffStatus = staffCurrent
                ? 'Current'
                : staffRoleDisplayLabel(access.staffRole);

            return RefreshIndicator(
              onRefresh: _reload,
              color: const Color(0xFF0B4C36),
              child: LayoutBuilder(
                builder: (context, constraints) {
                  final isTablet = constraints.maxWidth >= 760;
                  final horizontal = isTablet ? 34.0 : 14.0;
                  final maxContentWidth =
                      constraints.maxWidth > 980 ? 920.0 : constraints.maxWidth;

                  return ListView(
                    physics: const AlwaysScrollableScrollPhysics(),
                    padding: EdgeInsets.fromLTRB(
                      horizontal,
                      14,
                      horizontal,
                      34,
                    ),
                    children: [
                      Center(
                        child: ConstrainedBox(
                          constraints: BoxConstraints(
                            maxWidth: maxContentWidth,
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              const Text(
                                'YOUR HPJ ACCOUNT',
                                style: TextStyle(
                                  color: Color(0xFF758079),
                                  fontSize: 9.5,
                                  fontWeight: FontWeight.w900,
                                  letterSpacing: 2.0,
                                ),
                              ),
                              const SizedBox(height: 7),
                              const Text(
                                'Choose your workspace',
                                style: TextStyle(
                                  color: Color(0xFF103F2F),
                                  fontSize: 27,
                                  height: 1.0,
                                  fontWeight: FontWeight.w900,
                                  letterSpacing: -0.7,
                                ),
                              ),
                              const SizedBox(height: 8),
                              const Text(
                                'Open the tools available to your account. Your login and approved permissions stay connected.',
                                style: TextStyle(
                                  color: Color(0xFF68716D),
                                  fontSize: 12.1,
                                  height: 1.42,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                              const SizedBox(height: 18),
                              _EliteWorkspaceGrid(
                                children: [
                                  _EliteWorkspaceCard(
                                    photoUrl: _customerPhoto,
                                    title: 'Customer Shopping',
                                    subtitle: customerEnabled
                                        ? 'Shop fresh produce'
                                        : 'Fresh Jamaican produce coming soon',
                                    status: customerEnabled
                                        ? (customerCurrent
                                            ? 'Current'
                                            : 'Available')
                                        : 'Coming Soon',
                                    statusColor: customerEnabled
                                        ? const Color(0xFF2C754A)
                                        : const Color(0xFF9A6A1C),
                                    isCurrent: customerCurrent,
                                    actionLabel: customerEnabled
                                        ? (customerCurrent
                                            ? 'You are here'
                                            : 'Open')
                                        : 'View',
                                    onTap: customerCurrent
                                        ? _closeSwitcher
                                        : () => _openCustomer(customerEnabled),
                                  ),
                                  _EliteWorkspaceCard(
                                    photoUrl: _wholesalePhoto,
                                    title: 'Wholesale Business',
                                    subtitle: access.isApprovedWholesale
                                        ? 'Buy for your business'
                                        : access.businessAccount == null
                                            ? access.programSettings
                                                    .wholesaleApplicationsEnabled
                                                ? 'Apply for wholesale access'
                                                : 'Applications paused'
                                            : 'Review your application status',
                                    status: wholesaleStatus,
                                    statusColor: wholesaleStatusColor,
                                    isCurrent: wholesaleCurrent,
                                    actionLabel: wholesaleCurrent
                                        ? 'You are here'
                                        : 'Open',
                                    onTap: wholesaleCurrent
                                        ? _closeSwitcher
                                        : _openWholesale,
                                  ),
                                  _EliteWorkspaceCard(
                                    photoUrl: _farmerPhoto,
                                    title: 'Farmer Partner',
                                    subtitle: access.isApprovedFarmer
                                        ? 'Supply HPJ'
                                        : access.farmerProfile == null
                                            ? access.programSettings
                                                    .farmerApplicationsEnabled
                                                ? 'Apply to supply HPJ'
                                                : 'Applications paused'
                                            : 'Review your application status',
                                    status: farmerStatus,
                                    statusColor: farmerStatusColor,
                                    isCurrent: farmerCurrent,
                                    actionLabel: farmerCurrent
                                        ? 'You are here'
                                        : 'Open',
                                    onTap: farmerCurrent
                                        ? _closeSwitcher
                                        : _openFarmer,
                                  ),
                                  if (hasStaffAccess)
                                    _EliteWorkspaceCard(
                                      photoUrl: _staffPhoto,
                                      title: 'HPJ Staff & Operations',
                                      subtitle: _balancedStaffSubtitle(
                                        access.staffRole,
                                      ),
                                      status: staffStatus,
                                      statusColor: staffCurrent
                                          ? const Color(0xFF2C754A)
                                          : const Color(0xFF526763),
                                      isCurrent: staffCurrent,
                                      actionLabel: staffCurrent
                                          ? 'You are here'
                                          : 'Open',
                                      onTap: staffCurrent
                                          ? _closeSwitcher
                                          : _openStaff,
                                    ),
                                ],
                              ),
                              const SizedBox(height: 16),
                              const _EliteAccountSummary(),
                              const SizedBox(height: 12),
                              const _EliteWorkspaceInfoLinks(),
                              const SizedBox(height: 10),
                              const _WorkspaceSwitcherLegalFooter(),
                            ],
                          ),
                        ),
                      ),
                    ],
                  );
                },
              ),
            );
          },
        ),
      ),
    );
  }
}



class _EliteWorkspaceGrid extends StatelessWidget {
  final List<Widget> children;

  const _EliteWorkspaceGrid({
    required this.children,
  });

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final oneColumn = constraints.maxWidth < 330;
        final gap = 12.0;
        final width = oneColumn
            ? constraints.maxWidth
            : (constraints.maxWidth - gap) / 2;

        return Wrap(
          spacing: gap,
          runSpacing: 12,
          children: children
              .map(
                (child) => SizedBox(
                  width: width,
                  child: child,
                ),
              )
              .toList(),
        );
      },
    );
  }
}

class _EliteWorkspaceCard extends StatelessWidget {
  final String photoUrl;
  final String title;
  final String subtitle;
  final String status;
  final Color statusColor;
  final VoidCallback onTap;
  final bool isCurrent;
  final String actionLabel;

  const _EliteWorkspaceCard({
    required this.photoUrl,
    required this.title,
    required this.subtitle,
    required this.status,
    required this.statusColor,
    required this.onTap,
    this.isCurrent = false,
    this.actionLabel = 'Open',
  });

  @override
  Widget build(BuildContext context) {
    const forest = Color(0xFF0B4C36);
    const ink = Color(0xFF183D30);

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 205;
        final cardHeight = compact ? 216.0 : 222.0;
        final imageHeight = compact ? 90.0 : 96.0;

        return Semantics(
          button: true,
          label: '$title. $subtitle. $status.',
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: onTap,
              borderRadius: BorderRadius.circular(20),
              child: Container(
                height: cardHeight,
                clipBehavior: Clip.antiAlias,
                decoration: BoxDecoration(
                  color: const Color(0xFFFFFEFB),
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(
                    color: isCurrent
                        ? forest
                        : const Color(0xFFE2DED5),
                    width: isCurrent ? 1.6 : 1,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFF183D30).withOpacity(0.055),
                      blurRadius: 18,
                      offset: const Offset(0, 7),
                    ),
                  ],
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(
                      height: imageHeight,
                      width: double.infinity,
                      child: Stack(
                        fit: StackFit.expand,
                        children: [
                          Image.network(
                            photoUrl,
                            fit: BoxFit.cover,
                            alignment: Alignment.center,
                            filterQuality: FilterQuality.medium,
                            loadingBuilder: (context, child, progress) {
                              if (progress == null) return child;
                              return const ColoredBox(
                                color: Color(0xFFE9EEE9),
                              );
                            },
                            errorBuilder: (_, __, ___) {
                              return const ColoredBox(
                                color: Color(0xFFE9EEE9),
                                child: Center(
                                  child: Icon(
                                    Icons.storefront_outlined,
                                    color: forest,
                                    size: 27,
                                  ),
                                ),
                              );
                            },
                          ),
                          const Positioned.fill(
                            child: DecoratedBox(
                              decoration: BoxDecoration(
                                gradient: LinearGradient(
                                  begin: Alignment.topCenter,
                                  end: Alignment.bottomCenter,
                                  colors: [
                                    Color(0x00000000),
                                    Color(0x0D000000),
                                    Color(0x52000000),
                                  ],
                                  stops: [0, 0.62, 1],
                                ),
                              ),
                            ),
                          ),
                          Positioned(
                            top: 9,
                            right: 9,
                            child: _EliteStatusPill(
                              label: status,
                              color: statusColor,
                            ),
                          ),
                        ],
                      ),
                    ),
                    Expanded(
                      child: Padding(
                        padding: EdgeInsets.fromLTRB(
                          compact ? 12 : 13,
                          11,
                          compact ? 10 : 12,
                          10,
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              title,
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: ink,
                                fontSize: compact ? 13.7 : 14.5,
                                height: 1.05,
                                fontWeight: FontWeight.w900,
                                letterSpacing: -0.2,
                              ),
                            ),
                            const SizedBox(height: 5),
                            Text(
                              subtitle,
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color: const Color(0xFF6B746F),
                                fontSize: compact ? 9.7 : 10.2,
                                height: 1.28,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            const Spacer(),
                            Row(
                              children: [
                                Text(
                                  actionLabel,
                                  style: TextStyle(
                                    color: forest,
                                    fontSize: compact ? 9.8 : 10.4,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                                const Spacer(),
                                Container(
                                  width: 28,
                                  height: 28,
                                  alignment: Alignment.center,
                                  decoration: BoxDecoration(
                                    color: const Color(0xFFEAF3EC),
                                    borderRadius: BorderRadius.circular(999),
                                  ),
                                  child: Icon(
                                    isCurrent
                                        ? Icons.check_rounded
                                        : Icons.arrow_outward_rounded,
                                    color: forest,
                                    size: 15.5,
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

